INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96907, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "键", "is_correct": true, "explanation": "键（jiàn）：按一下就能打字或开机的小块，即本词。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是酱料。"}, {"text": "线", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是线条、线路。"}, {"text": "检", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是检查。"}, {"text": "煎", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是煎炸。"}], "explanations": {"键": "键（jiàn）：按一下就能打字或开机的小块，即本词。", "酱": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是酱料。", "线": "xiàn 与 jiàn 声母不同（x 与 j），意思是线条、线路。", "检": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是检查。", "煎": "jiān（第一声）与 jiàn（第四声）声调不同，意思是煎炸。"}, "sentence_index": null, "correct_answer": "键"}, "level_3": {"options": [{"text": "键", "is_correct": true, "explanation": "语义相合：按这个键才能开机，符合句意。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明用具，不是用来开机的部件，“请按这个灯开机”不合句意。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子是盛装液体的器皿，不是可按下去开机的部件。"}, {"text": "盖子", "is_correct": false, "explanation": "语义：盖子是遮盖物，不是可以按下去开机的部件。"}], "explanations": {"键": "语义相合：按这个键才能开机，符合句意。", "灯": "语义：灯是照明用具，不是用来开机的部件，“请按这个灯开机”不合句意。", "杯子": "语义：杯子是盛装液体的器皿，不是可按下去开机的部件。", "盖子": "语义：盖子是遮盖物，不是可以按下去开机的部件。"}, "sentence_index": 0, "correct_answer": "键"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把键插进插座里。", "explanation": "这里应该用〈插头〉。键是按下去的部件，不能插进插座；要插进插座的是插头。"}, {"text": "他拉了一下那个键，抽屉就开了。", "explanation": "这里应该用〈拉手〉。键是按下去的，不能拉；抽屉要用拉手拉开。"}, {"text": "我拧了一下那个键，屏幕就亮了。", "explanation": "这里应该用〈旋钮〉。键是按下去的，要拧的是旋钮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96907, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "键", "is_correct": true, "explanation": "键（jiàn）：按一下就能打字或开机的小块，即本词。"}, {"text": "将", "is_correct": false, "explanation": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是将要、将军。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。"}, {"text": "简", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是简单。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖端、尖锐。"}], "explanations": {"键": "键（jiàn）：按一下就能打字或开机的小块，即本词。", "将": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是将要、将军。", "现": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。", "简": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是简单。", "尖": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖端、尖锐。"}, "sentence_index": null, "correct_answer": "键"}, "level_3": {"options": [{"text": "键", "is_correct": true, "explanation": "语义相合：这个键太硬，要用力按，符合句意。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不是可以用手按下去的部件，“用力按墙”不合常理。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是可按的部件，句子意思不通。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子是盛水的器皿，不是要用力按下去的部件，句子意思不通。"}], "explanations": {"键": "语义相合：这个键太硬，要用力按，符合句意。", "墙": "语义：墙不是可以用手按下去的部件，“用力按墙”不合常理。", "桌子": "语义：桌子不是可按的部件，句子意思不通。", "杯子": "语义：杯子是盛水的器皿，不是要用力按下去的部件，句子意思不通。"}, "sentence_index": 6, "correct_answer": "键"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用键把纸剪开了。", "explanation": "这里应该用〈剪刀〉。键是按下去的部件，不能用来剪纸；剪纸要用剪刀。"}, {"text": "门口的键响了，他就去开门。", "explanation": "这里应该用〈门铃〉。键不会响，门口响的是门铃。"}, {"text": "他转动那个键，门就开了。", "explanation": "这里应该用〈钥匙〉。键要按下去，不能转动开门，开门要用钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只能按这只键来删除错字。", "corrected_sentence": "我只能按这个键来删除错字。", "error_description": "键的量词是“个”，不能用“只”，应说“这个键”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下按这个键，屏幕就亮了。", "corrected_sentence": "他按下这个键，屏幕就亮了。", "error_description": "结果补语“下”应放在动词“按”之后，说“按下这个键”；“下按”的语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
