INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钢琴等乐器上可按的部分。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这架钢琴有八十八个键。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手指轻轻按着琴上的键。", "target_word": "键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴上有一个键弹不响。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子喜欢按钢琴的键。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她弹琴的时候，手指在键上跳来跳去。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架旧钢琴的键已经发黄了。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，每个键的声音都不一样。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手风琴的键很小，我的手指按不准。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一按下这个键，琴就发出了清脆的声音。", "target_word": "键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只会按黑色的键，不会弹整首曲子。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "琴键", "label": "复合"}, {"form": "鍵", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钢琴等乐器上可按的琴键", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "键", "is_correct": true, "explanation": "键（jiàn）：钢琴等乐器上可按的部分，即本词。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是下降。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是剪刀、剪断。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是中间、间隔。"}], "explanations": {"键": "键（jiàn）：钢琴等乐器上可按的部分，即本词。", "降": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是下降。", "现": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。", "剪": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是剪刀、剪断。", "间": "jiān（第一声）与 jiàn（第四声）声调不同，意思是中间、间隔。"}, "sentence_index": null, "correct_answer": "键"}, "level_3": {"options": [{"text": "键", "is_correct": true, "explanation": "语义相合：钢琴上有八十八个键，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：钢琴不会有八十八个椅子，句中指的是可按的琴键。"}, {"text": "踏板", "is_correct": false, "explanation": "语义：钢琴的踏板只有三个，不可能有八十八个。"}, {"text": "琴弦", "is_correct": false, "explanation": "搭配：琴弦应用“根”计量，不能说“八十八个琴弦”。"}], "explanations": {"键": "语义相合：钢琴上有八十八个键，符合句意。", "椅子": "语义：钢琴不会有八十八个椅子，句中指的是可按的琴键。", "踏板": "语义：钢琴的踏板只有三个，不可能有八十八个。", "琴弦": "搭配：琴弦应用“根”计量，不能说“八十八个琴弦”。"}, "sentence_index": 0, "correct_answer": "键"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用键打开了门。", "explanation": "这里应该用〈钥匙〉。键是按下去的部件，不能用来开门，开门要用钥匙。"}, {"text": "他拧了一下那个键，收音机就响了。", "explanation": "这里应该用〈旋钮〉。键是按下去的部件，不能拧；要拧的是旋钮。"}, {"text": "这把吉他的键断了。", "explanation": "这里应该用〈琴弦〉。吉他上断裂的是琴弦，吉他没有琴键。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96908, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "键", "is_correct": true, "explanation": "键（jiàn）：钢琴等乐器上可按的部分，即本词。"}, {"text": "将", "is_correct": false, "explanation": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是将要、将军。"}, {"text": "线", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是线条、线路。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖端、尖锐。"}], "explanations": {"键": "键（jiàn）：钢琴等乐器上可按的部分，即本词。", "将": "jiàng 与 jiàn 韵尾不同（ng 与 n），意思是将要、将军。", "线": "xiàn 与 jiàn 声母不同（x 与 j），意思是线条、线路。", "减": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。", "尖": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖端、尖锐。"}, "sentence_index": null, "correct_answer": "键"}, "level_3": {"options": [{"text": "键", "is_correct": true, "explanation": "语义相合：每个键都能发出不同的音，符合句意。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯一般不发出可比较的声音，“每个灯的声音”不合常理。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是能发出不同声音的东西，句意说不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：书应用“本”计量，不能说“每个书”。"}], "explanations": {"键": "语义相合：每个键都能发出不同的音，符合句意。", "灯": "语义：灯一般不发出可比较的声音，“每个灯的声音”不合常理。", "书包": "语义：书包不是能发出不同声音的东西，句意说不通。", "书": "搭配：书应用“本”计量，不能说“每个书”。"}, "sentence_index": 6, "correct_answer": "键"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面鼓的键破了，得换一张新的。", "explanation": "这里应该用〈鼓面〉。键是按动的部件，破的是鼓面，鼓没有键。"}, {"text": "门口的键响了，有人来了。", "explanation": "这里应该用〈门铃〉。键不会响，门口响的是门铃。"}, {"text": "路灯的键亮了。", "explanation": "这里应该用〈灯泡〉。键是按下去的部件，路灯亮的是灯泡，不能说“键亮了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_ver