INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96909, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说话让人觉得好笑，又很有趣。", "primary_collocate": null, "pronunciation": "yōu mò", "ipa": "joʊ˥ mwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "我的同桌说话很幽默，总是逗大家笑。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲笑话的方式特别幽默。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸很幽默，每天都让全家人笑。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个主持人说话幽默，观众很喜欢他。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回答得太幽默了，我们笑个不停。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和幽默的人聊天，心情会变好。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个幽默的人，朋友都愿意和他玩。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不但漂亮，而且很幽默。", "target_word": "幽默", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想用一句幽默的话让气氛轻松一点。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢幽默的男朋友，因为他让我开心。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幽默感", "label": "复合"}, {"form": "幽默地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "人说话风趣好笑，能逗人开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幽默", "is_correct": true, "explanation": "正确：说话有趣好笑，总能逗大家笑，符合句意。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”与“总是逗大家笑”矛盾。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”与“总是逗大家笑”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材，不能用来形容说话。"}], "explanations": {"幽默": "正确：说话有趣好笑，总能逗大家笑，符合句意。", "严肃": "语义：“严肃”与“总是逗大家笑”矛盾。", "冷淡": "语义：“冷淡”与“总是逗大家笑”矛盾。", "高大": "体貌：“高大”形容人的身材，不能用来形容说话。"}, "sentence_index": 0, "correct_answer": "幽默"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走路很幽默，一步一步很慢。", "explanation": "这里应该用〈稳重〉。“幽默”形容说话风趣，不形容走路的样子。"}, {"text": "这位老师写字很幽默，同学们都看不清。", "explanation": "这里应该用〈潦草〉。“幽默”形容言谈风趣，不用来形容字迹，字写得乱、看不清要用“潦草”。"}, {"text": "这个房间很幽默，墙上挂满了画。", "explanation": "这里应该用〈雅致〉。“幽默”只用于人的言谈或作品，不用来形容房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幽默", "is_correct": true, "explanation": "正确：这个人风趣好笑，朋友都愿意和他玩，符合句意。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：冷漠的人不容易交朋友，与“朋友都愿意和他玩”矛盾。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”描述味道，不能用来形容一个人的性格。"}, {"text": "孤僻", "is_correct": false, "explanation": "语义：孤僻的人不爱与人来往，与“朋友都愿意和他玩”矛盾。"}], "explanations": {"幽默": "正确：这个人风趣好笑，朋友都愿意和他玩，符合句意。", "冷漠": "语义：冷漠的人不容易交朋友，与“朋友都愿意和他玩”矛盾。", "咸": "搭配：“咸”描述味道，不能用来形容一个人的性格。", "孤僻": "语义：孤僻的人不爱与人来往，与“朋友都愿意和他玩”矛盾。"}, "sentence_index": 6, "correct_answer": "幽默"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喜欢幽默的花瓶，因为它很漂亮。", "explanation": "这里应该用〈好看〉。“幽默”只形容人的言谈或性格风趣，不能形容花瓶。"}, {"text": "他幽默地擦着眼泪，不说话。", "explanation": "这里应该用〈难过〉。“幽默”修饰的是言谈或表达，不能修饰伤心的动作。"}, {"text": "这个灯泡很幽默，每天都很亮。", "explanation": "这里应该用〈明亮〉。“幽默”只形容人的言谈或作品，不能形容灯泡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他讲笑话讲很幽默，大家都笑了。", "corrected_sentence": "他讲笑话讲得很幽默，大家都笑了。", "error_description": "补语结构错误：动词“讲”后带程度补语须用“得”，应写作“讲得很幽默”，此处漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说话得很幽默，常让身边的人笑出声。", "corrected_sentence": "她说话很幽默，常让身边的人笑出声。", "error_description": "多余的“得”：“说话”是动宾式离合词，后面不能直接加“得”，应写作“她说话很幽默”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
