INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96910, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有趣而意味深长，使人发笑的。", "primary_collocate": null, "pronunciation": "yōu mò", "ipa": "joʊ˥ mwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他的演讲很幽默，大家听了都笑了。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家写的文章幽默又有深意。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲课很幽默，同学们都爱听。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影很幽默，看完让人想了很久。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用幽默的话说出了一个道理。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "卓别林的表演既幽默又深刻。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事听起来幽默，想想却有点苦。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话幽默，常用笑话讲大道理。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他幽默地回答了记者的问题。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "相声演员的语言幽默而有味道。", "target_word": "幽默", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幽默感", "label": "复合"}, {"form": "幽默地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "言语、文章或表演有趣又含深意，让人发笑并有所思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幽默", "is_correct": true, "explanation": "正确：演讲有趣又有深意，让人发笑，符合句意。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”与后半句“大家听了都笑了”矛盾。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”使人乏味，与“大家听了都笑了”相反。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或物的个头，不能用来形容演讲。"}], "explanations": {"幽默": "正确：演讲有趣又有深意，让人发笑，符合句意。", "严肃": "语义：“严肃”与后半句“大家听了都笑了”矛盾。", "枯燥": "语义：“枯燥”使人乏味，与“大家听了都笑了”相反。", "矮小": "体貌：“矮小”形容人或物的个头，不能用来形容演讲。"}, "sentence_index": 0, "correct_answer": "幽默"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很幽默，坐上去不会晃。", "explanation": "这里应该用〈结实〉。“幽默”形容言谈、作品有趣，不能用来形容椅子。"}, {"text": "她长得很幽默，大家都夸她漂亮。", "explanation": "这里应该用〈好看〉。“幽默”形容人的言行有趣，不形容相貌，说外貌要用“好看”。"}, {"text": "今天的天气很幽默，适合去公园玩。", "explanation": "这里应该用〈晴朗〉。“幽默”只用于言谈、作品，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幽默", "is_correct": true, "explanation": "正确：故事有趣又有深意，符合“听起来幽默，想想却有点苦”的句意。"}, {"text": "英俊", "is_correct": false, "explanation": "体貌：“英俊”形容人的相貌，不能用来形容故事。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味道，故事不能有咸味，句子不通。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”形容人的体格，不能用来形容故事。"}], "explanations": {"幽默": "正确：故事有趣又有深意，符合“听起来幽默，想想却有点苦”的句意。", "英俊": "体貌：“英俊”形容人的相貌，不能用来形容故事。", "咸": "语义：“咸”是味道，故事不能有咸味，句子不通。", "粗壮": "体貌：“粗壮”形容人的体格，不能用来形容故事。"}, "sentence_index": 6, "correct_answer": "幽默"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他幽默地哭了，眼泪一直往下流。", "explanation": "这里应该用〈伤心〉。“幽默”形容言行有趣，不能用来形容哭泣的情绪。"}, {"text": "他的手很幽默，握得很有力。", "explanation": "这里应该用〈有力〉。“幽默”只形容言谈或作品有趣，不形容手，说手的力量要用“有力”。"}, {"text": "这盘菜很幽默，我一口也吃不下。", "explanation": "这里应该用〈难吃〉。“幽默”形容言谈或作品有趣，不能用来形容菜，说菜不好吃要用“难吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很有幽默的感，大家都喜欢和她聊天。", "corrected_sentence": "她很有幽默感，大家都喜欢和她聊天。", "error_description": "词内插入错误：“幽默感”是一个复合词，中间不能插入“的”，应写作“幽默感”，不能拆成“幽默的感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被很幽默，大家都喜欢和他聊天。", "corrected_sentence": "他变得很幽默，大家都喜欢和他聊天。", "error_description": "被动结构误用：“幽默”是形容词，不能用“被”构成被动句，表示变化应用“变得”，应写作“他变得很幽默”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
