INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在门的前面。", "primary_collocate": null, "pronunciation": "mén qián", "ipa": "mən˧˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我家门前有一棵大树。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一辆红色的车停在门前。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在门前玩球。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在门前，不知道该不该进去。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在门前晒太阳。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在门前等着主人回来。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门前有人在卖水果。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在学校门前见面吧。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在商店门前看了很久。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，他走到门前，看见一只小猫。", "target_word": "门前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "門前", "label": "繁体"}], "register": "中性", "sense_fingerprint": "门外正对着门的位置，常作处所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d88c77-461f-4c74-96b2-9f5f37a1c376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门前", "is_correct": true, "explanation": "门前指门外正对着门的位置，房前可以长一棵大树，句子通顺。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是室内做饭的房间，不能说有一棵大树长在里面。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，上面不可能有一棵大树。"}, {"text": "脸", "is_correct": false, "explanation": "配价：“有”后面引出的是可以放置事物的处所，“脸”不能充当这样的处所。"}], "explanations": {"门前": "门前指门外正对着门的位置，房前可以长一棵大树，句子通顺。", "厨房": "语义：厨房是室内做饭的房间，不能说有一棵大树长在里面。", "桌子": "语义：桌子是家具，上面不可能有一棵大树。", "脸": "配价：“有”后面引出的是可以放置事物的处所，“脸”不能充当这样的处所。"}, "sentence_index": 0, "correct_answer": "门前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把门前搬到了屋里。", "explanation": "这里应该用〈桌子〉。门前是处所，不是可以搬动的东西；“搬”的宾语应是桌子、箱子这类可以移动的物体。"}, {"text": "他用门前写了一封信。", "explanation": "这里应该用〈纸〉。门前是处所，不能作书写的材料；“用”的宾语应是纸、笔这类物品。"}, {"text": "我把门前关上了，然后去睡觉。", "explanation": "这里应该用〈房门〉。门前指门外的位置，不是门本身，不能被关上；“关”的对象应是门本身，要说关房门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门前", "is_correct": true, "explanation": "门前指门外正对着门的地方，有人在那里卖水果符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以供人摆摊卖水果的场所。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不能是有人卖东西的地方。"}, {"text": "脑袋", "is_correct": false, "explanation": "配价：“有人在卖水果”需要一个处所作主语，“脑袋”不能充当处所。"}], "explanations": {"门前": "门前指门外正对着门的地方，有人在那里卖水果符合句意。", "冰箱": "语义：冰箱是家电，不是可以供人摆摊卖水果的场所。", "书包": "语义：书包是装东西的袋子，不能是有人卖东西的地方。", "脑袋": "配价：“有人在卖水果”需要一个处所作主语，“脑袋”不能充当处所。"}, "sentence_index": 6, "correct_answer": "门前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门前打了我一拳，我很生气。", "explanation": "这里应该用〈他〉作主语。门前是处所，不能施动“打”，动手的应是人。"}, {"text": "我对门前说了一声谢谢，然后走了。", "explanation": "这里应该用〈老师〉。门前是处所，不能作道谢的对象，“说谢谢”要对人说。"}, {"text": "我把门前借给了朋友。", "explanation": "这里应该用〈书〉。门前是处所，不能作借出的物品，“借”的宾语应是可以拿在手里的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在门前里等了十分钟。", "corrected_sentence": "我在门前等了十分钟。", "error_description": "错误形式：“门前里”；正确形式：“门前”。“门前”本身已含方位词“前”，后面不能再加“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他走进门前，停了下来。", "corrected_sentence": "他走到门前，停了下来。", "error_description": "错误形式：“走进门前”；正确形式：“走到门前”。“进”要求后面是可以进入的场所，门前是门外的位置，应用“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
