INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体下方；某事物的下面。", "primary_collocate": null, "pronunciation": "dǐ xia", "ipa": "ti˨˩ ɕja", "syllable_count": 2, "sentences": [{"text": "猫躲在桌子底下睡觉。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的鞋在床底下。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗趴在椅子底下。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球滚到了车底下。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙放在书底下了。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树底下有很多落叶。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥底下的水很清。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把箱子搬到桌子底下。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在大树底下玩游戏。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发底下有一只小球。", "target_word": "底下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "物体下方的位置，常接在桌子、床、树等名词后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400b5293-dbe8-4b37-a144-768922327a84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "底下", "is_correct": true, "explanation": "正确：“底下”指物体的下方，是本题要听的词。"}, {"text": "地下", "is_correct": false, "explanation": "声调不同：“地下”第一音节为第四声，意思是地面以下，与“底下”（第三声）不同。"}, {"text": "低下", "is_correct": false, "explanation": "声调不同：“低下”第一音节为第一声，意思是位置低，或水平、品质差，与“底下”不同。"}, {"text": "滴下", "is_correct": false, "explanation": "声调不同：“滴下”第一音节为第一声，与“底下”的第三声不同，意思是液体一滴一滴地落下。"}], "explanations": {"底下": "正确：“底下”指物体的下方，是本题要听的词。", "地下": "声调不同：“地下”第一音节为第四声，意思是地面以下，与“底下”（第三声）不同。", "低下": "声调不同：“低下”第一音节为第一声，意思是位置低，或水平、品质差，与“底下”不同。", "滴下": "声调不同：“滴下”第一音节为第一声，与“底下”的第三声不同，意思是液体一滴一滴地落下。"}, "sentence_index": null, "correct_answer": "底下"}, "level_3": {"options": [{"text": "底下", "is_correct": true, "explanation": "正确：“桌子底下”指桌子的下方，与“躲”和“睡觉”所表示的隐蔽位置相符。"}, {"text": "上面", "is_correct": false, "explanation": "语义：躲藏需要隐蔽，桌面上显眼，与“躲”矛盾。"}, {"text": "中间", "is_correct": false, "explanation": "搭配：桌子是平面家具，不能说躲在它的中间。"}, {"text": "里面", "is_correct": false, "explanation": "搭配：桌子没有可以容身的内部空间，不说躲在桌子里面。"}], "explanations": {"底下": "正确：“桌子底下”指桌子的下方，与“躲”和“睡觉”所表示的隐蔽位置相符。", "上面": "语义：躲藏需要隐蔽，桌面上显眼，与“躲”矛盾。", "中间": "搭配：桌子是平面家具，不能说躲在它的中间。", "里面": "搭配：桌子没有可以容身的内部空间，不说躲在桌子里面。"}, "sentence_index": 0, "correct_answer": "底下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的水平很底下。", "explanation": "这里应该用〈低下〉。“底下”指位置，不能形容水平的高低。"}, {"text": "他的英语底下很好。", "explanation": "这里应该用〈底子〉。“底下”指位置，不能指基础或功底。"}, {"text": "他做事没有底下。", "explanation": "这里应该用〈底线〉。“底下”指位置，不能指做事的界限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96914, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "底下", "is_correct": true, "explanation": "正确：“底下”指物体的下方，是本题要听的词。"}, {"text": "笔下", "is_correct": false, "explanation": "声母不同：「笔下」第一音节为 bǐ，声母 b 与「底下」的 d 不同，意思是在笔端、由笔写出，如「笔下人物」。"}, {"text": "挤下", "is_correct": false, "explanation": "声母不同：「挤下」第一音节为 jǐ，声母 j 与「底下」的 d 不同，意思是用力把人或物挤到下面，如「挤下车」。"}, {"text": "底线", "is_correct": false, "explanation": "读音不同：“底线”的第二音节比“下”多一个韵尾 n（xiàn），意思是最低限度。"}], "explanations": {"底下": "正确：“底下”指物体的下方，是本题要听的词。", "笔下": "声母不同：「笔下」第一音节为 bǐ，声母 b 与「底下」的 d 不同，意思是在笔端、由笔写出，如「笔下人物」。", "挤下": "声母不同：「挤下」第一音节为 jǐ，声母 j 与「底下」的 d 不同，意思是用力把人或物挤到下面，如「挤下车」。", "底线": "读音不同：“底线”的第二音节比“下”多一个韵尾 n（xiàn），意思是最低限度。"}, "sentence_index": null, "correct_answer": "底下"}, "level_3": {"options": [{"text": "底下", "is_correct": true, "explanation": "正确：“桥底下”指桥的下方，河水在桥下，与句意相符。"}, {"text": "上边", "is_correct": false, "explanation": "语义：水在桥的上方，与“水很清”所描述的桥下水面不符。"}, {"text": "里边", "is_correct": false, "explanation": "搭配：桥不是能容纳水的容器，不说“桥里边的水”。"}, {"text": "顶上", "is_correct": false, "explanation": "语义：桥顶上不会有河水，与句意不符。"}], "explanations": {"底下": "正确：“桥底下”指桥的下方，河水在桥下，与句意相符。", "上边": "语义：水在桥的上方，与“水很清”所描述的桥下水面不符。", "里边": "搭配：桥不是能容纳水的容器，不说“桥里边的水”。", "顶上": "语义：桥顶上不会有河水，与句意不符。"}, "sentence_index": 6, "correct_answer": "底下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话很有底下。", "explanation": "这里应该用〈底气〉。“底气”指说话做事的信心，“底下”只表示位置。"}, {"text": "我已经摸清了他的底下。", "explanation": "这里应该用〈底细〉。“底下”指位置，不能指隐情或内情。"}, {"text": "这次考试我心里没有底下。", "explanation": "这里应该用〈底〉。“心里没底”指没有把握，“底下”只表示位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的书柜子底下。", "corrected_sentence": "我的书在柜子底下。", "error_description": "漏用介词：“底下”表示位置，前面要用介词“在”引出处所，应说“在柜子底下”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的猫躲从沙发底下。", "corrected_sentence": "我的猫躲在沙发底下。", "error_description": "介词错误：表示躲藏的处所要用“在”，不能用“从”。“从”表示起点，应说“躲在沙发底下”，不能说“躲从沙发底下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
