INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情做好以后，还留下来的办法。", "primary_collocate": null, "pronunciation": "hòu shǒu", "ipa": "xoʊ˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "事情办好了，他还留着一个后手。", "target_word": "后手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同签好了，我们还有后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计划成功了，可是他还是留了后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事做完以后，你还有什么后手？", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方案定好以后，经理还留着一个后手。", "target_word": "后手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目验收通过后，团队还留着一个后手。", "target_word": "后手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赢了比赛，但没有忘记准备后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，教练还藏着一个后手。", "target_word": "后手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情都安排好了，我们还留有后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司做完这个项目，仍然有后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "後手", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情办完之后仍然留着的备用办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后手", "is_correct": true, "explanation": "正确。“留着一个后手”指事情办完后仍保留的备用办法，与“事情办好了”相符。"}, {"text": "噩梦", "is_correct": false, "explanation": "语义：“噩梦”不是可以留着备用的办法，与“事情办好了”的语境不合。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“留着”不搭配“性格”，应说“保持性格”。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”是人，不能作为留着的东西，这句话的语境说不通。"}], "explanations": {"后手": "正确。“留着一个后手”指事情办完后仍保留的备用办法，与“事情办好了”相符。", "噩梦": "语义：“噩梦”不是可以留着备用的办法，与“事情办好了”的语境不合。", "性格": "搭配：“留着”不搭配“性格”，应说“保持性格”。", "同学": "语义：“同学”是人，不能作为留着的东西，这句话的语境说不通。"}, "sentence_index": 0, "correct_answer": "后手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事做完以后，他送给了朋友一个后手。", "explanation": "这里应该用〈礼物〉。“后手”指留作后用的办法，不是可以送给别人的东西。"}, {"text": "这件事做完以后，两家公司爆发了后手。", "explanation": "这里应该用〈纠纷〉。“后手”指事情做完以后留下的办法，不指双方的争执。"}, {"text": "这件事做完以后，他赢得了很高的后手。", "explanation": "这里应该用〈赞誉〉。“后手”指事情做完以后留下的办法，不是可以赢得的荣誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后手", "is_correct": true, "explanation": "正确。“没有忘记准备后手”指事情办完后仍留作后用的办法，与“赢了比赛”的语境相符。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“准备”不搭配“冠军”，“冠军”是已取得的名次，不能预先准备。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：赢了比赛的语境中“准备眼泪”与事实和语义都不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不能被准备，放在这里语义说不通。"}], "explanations": {"后手": "正确。“没有忘记准备后手”指事情办完后仍留作后用的办法，与“赢了比赛”的语境相符。", "冠军": "搭配：“准备”不搭配“冠军”，“冠军”是已取得的名次，不能预先准备。", "眼泪": "语义：赢了比赛的语境中“准备眼泪”与事实和语义都不合。", "月亮": "语义：“月亮”不能被准备，放在这里语义说不通。"}, "sentence_index": 6, "correct_answer": "后手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "项目做完后，公司收获了很多后手。", "explanation": "这里应该用〈成果〉。“后手”指留作后用的办法，不能被“收获”。"}, {"text": "项目做完后，公司举行了一个后手。", "explanation": "这里应该用〈庆典〉。“后手”指留作后用的办法，不是可以举行的活动。"}, {"text": "项目做完后，公司陷入了财务后手。", "explanation": "这里应该用〈危机〉。“后手”指事情做完后留下的办法，不指困境或危险的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作结束后，他还留着个一后手。", "corrected_sentence": "工作结束后，他还留着一个后手。", "error_description": "数量短语语序颠倒：“一个”应放在名词“后手”前面，不能写成“个一”。错误形式：留着个一后手；正确形式：留着一个后手。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "项目结束后，经理还留着一颗后手，以防万一。", "corrected_sentence": "项目结束后，经理还留着一个后手，以防万一。", "error_description": "“后手”的量词应用“个”，不能用“颗”（“颗”用于粒状的小东西）。错误形式：一颗后手；正确形式：一个后手。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96919, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96919, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96919, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人做事很不容易，心里感谢。", "primary_collocate": null, "pronunciation": "nán wei", "ipa": "nan˧˥ weɪ", "syllable_count": 2, "sentences": [{"text": "这么多菜都是你做的？难为你了！", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你照顾了我一整天，真难为你了。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难为你跑这么远来看我。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么冷，还让你送来，难为你了。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难为你们等了这么久。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个人带三个孩子，真难为你了。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难为你想得这么周到，谢谢！", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚还帮我修电脑，难为你了。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：难为你把房间收拾得这么干净。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你陪我找了一下午，难为你了，我请你吃饭。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "难为了", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "难为：感谢别人辛苦，常说“难为你了”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8adc1b-9d40-4b43-9a93-25a8a9f56bae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96919, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难为", "is_correct": true, "explanation": "“难为你了”是感谢对方为自己辛苦，与句中“这么多菜都是你做的”的赞叹相符。"}, {"text": "吓唬", "is_correct": false, "explanation": "语义：“吓唬你了”与“这么多菜都是你做的”的赞叹语境不合，句子不通。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促你了”与“这么多菜都是你做的”的语境无关，句子不通。"}, {"text": "惩罚", "is_correct": false, "explanation": "搭配：“惩罚”通常用于犯错的人，不能用来对帮忙做菜的人表示感谢。"}], "explanations": {"难为": "“难为你了”是感谢对方为自己辛苦，与句中“这么多菜都是你做的”的赞叹相符。", "吓唬": "语义：“吓唬你了”与“这么多菜都是你做的”的赞叹语境不合，句子不通。", "催促": "语义：“催促你了”与“这么多菜都是你做的”的语境无关，句子不通。", "惩罚": "搭配：“惩罚”通常用于犯错的人，不能用来对帮忙做菜的人表示感谢。"}, "sentence_index": 0, "correct_answer": "难为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你别难为他了，他真的不会唱歌。", "explanation": "这里是「使人为难」的意思，与「感谢别人辛苦」不是同一个义项，句中并不是在表示感谢。"}, {"text": "老板总是故意难为新人，大家都不愿意去。", "explanation": "这里的“难为”是故意刁难别人的意思，与句中表示感谢对方辛苦的意思不同。"}, {"text": "明知她不会跳舞，还让她上台，这不是难为人吗？", "explanation": "这里是「使人为难」的意思，指有意让人处境困难，不是感谢对方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难为", "is_correct": true, "explanation": "“难为你想得这么周到，谢谢”是感谢对方想得周到，与后面的“谢谢”相符。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：“打扰你想得这么周到”与后面的“谢谢”的感激语境不合，句子不通。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促你想得这么周到”与感谢语境不合，句子不通。"}, {"text": "忽视", "is_correct": false, "explanation": "配价：“忽视”后面要带名词性的宾语，“忽视你想得这么周到”结构不通。"}], "explanations": {"难为": "“难为你想得这么周到，谢谢”是感谢对方想得周到，与后面的“谢谢”相符。", "打扰": "语义：“打扰你想得这么周到”与后面的“谢谢”的感激语境不合，句子不通。", "催促": "语义：“催促你想得这么周到”与感谢语境不合，句子不通。", "忽视": "配价：“忽视”后面要带名词性的宾语，“忽视你想得这么周到”结构不通。"}, "sentence_index": 6, "correct_answer": "难为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题太难，你这是难为孩子。", "explanation": "这里是「使人为难」的意思，指让人处境艰难，不是感谢对方辛苦。"}, {"text": "要他一天写完一本书，不是难为他吗？", "explanation": "这里是「使人为难」的意思，指给别人出难题，与感谢无关。"}, {"text": "我不会难为你，你不想说就不说。", "explanation": "这里是「使人为难」的意思，表示不会刁难对方，不是感谢的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么晚还来接我，真难为你着。", "corrected_sentence": "这么晚还来接我，真难为你了。", "error_description": "表示感谢的“难为”指对方已经完成的辛苦，句末应用“了”，不能用“着”表示持续，应说“真难为你了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么热的天你还来帮忙，真难为着你了。", "corrected_sentence": "这么热的天你还来帮忙，真难为你了。", "error_description": "表示感谢的“难为”是一次性的，不能加“着”表示持续，应说“难为你了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
