INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96920, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人为难，故意让人处境困难。", "primary_collocate": null, "pronunciation": "nán wei", "ipa": "nan˧˥ weɪ", "syllable_count": 2, "sentences": [{"text": "你别难为他了，他真的不会唱歌。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有难为我，只问了一个问题。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题太难，你这是难为孩子。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想难为朋友，所以没开口借钱。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们别难为新来的同事了。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明知她不会跳舞，还让她上台，这不是难为人吗？", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察没有难为那位老人，只是看了看证件。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要他一天写完一本书，不是难为他吗？", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会难为你，你不想说就不说。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板总是故意难为新人，大家都不愿意去。", "target_word": "难为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "难为了", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "难为：故意让人处境为难，如“别难为他”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8adc1b-9d40-4b43-9a93-25a8a9f56bae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难为", "is_correct": true, "explanation": "“你别难为他了”是别再让他为难，与“他真的不会唱歌”的语境相符。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“别认识他了”不成立，“认识”不能用来表示让对方停止，与语境不合。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”是感知动作，“别看见他了”与“他真的不会唱歌”的语境无关。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是东西，不能是人，“别修理他了”在这里不通。"}], "explanations": {"难为": "“你别难为他了”是别再让他为难，与“他真的不会唱歌”的语境相符。", "认识": "语义：“别认识他了”不成立，“认识”不能用来表示让对方停止，与语境不合。", "看见": "语义：“看见”是感知动作，“别看见他了”与“他真的不会唱歌”的语境无关。", "修理": "语义：“修理”的对象是东西，不能是人，“别修理他了”在这里不通。"}, "sentence_index": 0, "correct_answer": "难为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这么多菜都是你做的？难为你了！", "explanation": "这里是感谢对方辛苦的意思，并不是「使人为难」，句中没有刁难之意。"}, {"text": "你照顾了我一整天，真难为你了。", "explanation": "这里是感谢对方辛苦的意思，与句中“不想为难朋友”的意思不同。"}, {"text": "难为你跑这么远来看我。", "explanation": "这里是感谢对方辛苦的意思，不是使人为难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难为", "is_correct": true, "explanation": "“没有难为那位老人”是没有刁难对方，与“只是看了看证件”的语境相符。"}, {"text": "救", "is_correct": false, "explanation": "语义：“救”表示使人脱离危险，与“只是看了看证件”的平和语境不合。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”的对象不能是人，“没有修那位老人”不通。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给人或动物吃东西，与警察查看证件的语境无关。"}], "explanations": {"难为": "“没有难为那位老人”是没有刁难对方，与“只是看了看证件”的语境相符。", "救": "语义：“救”表示使人脱离危险，与“只是看了看证件”的平和语境不合。", "修": "语义：“修”的对象不能是人，“没有修那位老人”不通。", "喂": "语义：“喂”是给人或动物吃东西，与警察查看证件的语境无关。"}, "sentence_index": 6, "correct_answer": "难为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天这么冷，还让你送来，难为你了。", "explanation": "这里是感谢对方辛苦的意思，不是「使人为难」，句中没有刁难之意。"}, {"text": "难为你们等了这么久。", "explanation": "这里是感谢对方等待辛苦的意思，与“故意让人为难”不同。"}, {"text": "你一个人带三个孩子，真难为你了。", "explanation": "这里是感谢对方辛苦的意思，并不是使人为难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你别难为他着，他不会唱歌。", "corrected_sentence": "你别难为他了，他不会唱歌。", "error_description": "体标误用：劝人停止“难为”某人时，句末应用“了”，说“别难为他了”；“别难为他着”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察只问了几句，没有难为了那位老人。", "corrected_sentence": "警察只问了几句，没有难为那位老人。", "error_description": "“没有”否定句中，“难为”后面不能加“了”，应说“没有难为那位老人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96921, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96921, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96921, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "靠着某个东西来做成一件事。", "primary_collocate": null, "pronunciation": "píng jiè", "ipa": "pʰiŋ˧˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他凭借努力考上了大学。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她凭借好成绩得到了奖学金。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明凭借着聪明的头脑赢了比赛。", "target_word": "凭借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司凭借好产品赢得了很多客人。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们凭借地图找到了那个小村子。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他凭借多年的经验，很快修好了车。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国队凭借最后一分赢得了比赛。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她凭借自己的声音，成了有名的歌手。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李凭借着一张旧照片，找到了失去联系的朋友。", "target_word": "凭借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老师凭借耐心，让每个学生都爱上了学习。", "target_word": "凭借", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凭借着", "label": "体标"}], "register": "书面", "sense_fingerprint": "介词：凭借＋条件／能力＋动作，表示靠它做成事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96921, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凭借", "is_correct": true, "explanation": "正确：凭借（píng jiè），意思是靠着某个东西来做成一件事。"}, {"text": "评价", "is_correct": false, "explanation": "评价（píng jià）与凭借（píng jiè）第二个音节的韵母不同（ià 与 iè），意思是评论、衡量。"}, {"text": "凭据", "is_correct": false, "explanation": "凭据（píng jù）与凭借（píng jiè）第二个音节的韵母不同（ù 与 iè），意思是作为依据的证明。"}, {"text": "平列", "is_correct": false, "explanation": "平列（píng liè）与凭借（píng jiè）第二个音节的声母不同（l 与 j），意思是并排列出。"}], "explanations": {"凭借": "正确：凭借（píng jiè），意思是靠着某个东西来做成一件事。", "评价": "评价（píng jià）与凭借（píng jiè）第二个音节的韵母不同（ià 与 iè），意思是评论、衡量。", "凭据": "凭据（píng jù）与凭借（píng jiè）第二个音节的韵母不同（ù 与 iè），意思是作为依据的证明。", "平列": "平列（píng liè）与凭借（píng jiè）第二个音节的声母不同（l 与 j），意思是并排列出。"}, "sentence_index": null, "correct_answer": "凭借"}, "level_3": {"options": [{"text": "凭借", "is_correct": true, "explanation": "正确：“凭借”表示靠努力做成事，与句中“努力”搭配自然，句意通顺。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后面要接规定或标准，“按照努力”不能表示凭什么考上大学。"}, {"text": "随着", "is_correct": false, "explanation": "语义：“随着”表示伴随某种变化，与“努力考上大学”的因果关系不符。"}, {"text": "根据", "is_correct": false, "explanation": "搭配：“根据”要接依据、事实，“根据努力”不能说明靠什么做成事。"}], "explanations": {"凭借": "正确：“凭借”表示靠努力做成事，与句中“努力”搭配自然，句意通顺。", "按照": "搭配：“按照”后面要接规定或标准，“按照努力”不能表示凭什么考上大学。", "随着": "语义：“随着”表示伴随某种变化，与“努力考上大学”的因果关系不符。", "根据": "搭配：“根据”要接依据、事实，“根据努力”不能说明靠什么做成事。"}, "sentence_index": 0, "correct_answer": "凭借"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他凭借生病请了假。", "explanation": "这里应该用〈因为〉。“凭借”表示靠某种有利的条件或能力做成事，生病不是可以依靠的条件，应该用“因为”。"}, {"text": "她凭借铅笔写完了作业。", "explanation": "这里应该用〈用〉。“凭借”强调依靠有利的条件或能力，只是使用工具时要用“用”，如“她用铅笔写完了作业”。"}, {"text": "凭借两个小时，她背完了整篇课文。", "explanation": "这里应该用〈花〉。“凭借”表示依靠有利的条件或能力，两个小时是所花的时间，不是可以依靠的条件，应说“花两个小时背完了整篇课文”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凭借", "is_correct": true, "explanation": "正确：“凭借”表示靠某个有利条件做成事，“最后一分”正是取胜的条件。"}, {"text": "通过", "is_correct": false, "explanation": "搭配：“通过”要接方法或途径，“通过最后一分”不能表示靠它取胜。"}, {"text": "用", "is_correct": false, "explanation": "搭配：“用”后面接的是可以使用的手段或工具，“用最后一分”不成立。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“为了最后一分赢得比赛”的目的关系说不通。"}], "explanations": {"凭借": "正确：“凭借”表示靠某个有利条件做成事，“最后一分”正是取胜的条件。", "通过": "搭配：“通过”要接方法或途径，“通过最后一分”不能表示靠它取胜。", "用": "搭配：“用”后面接的是可以使用的手段或工具，“用最后一分”不成立。", "为了": "语义：“为了”表示目的，“为了最后一分赢得比赛”的目的关系说不通。"}, "sentence_index": 6, "correct_answer": "凭借"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "凭借天气不好，我们取消了去郊游的计划。", "explanation": "这里应该用〈因为〉。“凭借”表示依靠有利的条件或能力做成事，“天气不好”是原因，不是可以依靠的条件，应该用“因为”。"}, {"text": "凭借大雨，比赛推迟了。", "explanation": "这里应该用〈由于〉。“由于”表示原因，“凭借”不能表示原因，大雨不是可以依靠的条件。"}, {"text": "凭借省钱，他骑车上班。", "explanation": "这里应该用〈为了〉。“为了”表示目的，“凭借”表示依靠的条件，不能用来引出目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她凭借了耐心和努力，终于学会了游泳。", "corrected_sentence": "她凭借耐心和努力，终于学会了游泳。", "error_description": "“凭借”是介词，后面不能直接加“了”。应说“她凭借耐心和努力，……”，“了”要用在动词后面，如“学会了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很凭借一把旧钥匙打开了那扇门。", "corrected_sentence": "他凭借一把旧钥匙打开了那扇门。", "error_description": "“凭借”是介词，前面不能加程度副词“很”。应去掉“很”，说“他凭借一把旧钥匙打开了那扇门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96922, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确：“独立”与“依靠、依仗”意思相反，指自己做主，不靠别人或外物。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细地看，与“凭借”既不是近义也不是反义。"}, {"text": "欢迎", "is_correct": false, "explanation": "“欢迎”指以热情接待某人，与“凭借”不构成反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修补损坏的东西，与“凭借”不构成反义关系。"}], "correct_answer": "独立", "explanations": {"独立": "正确：“独立”与“依靠、依仗”意思相反，指自己做主，不靠别人或外物。", "观察": "“观察”指仔细地看，与“凭借”既不是近义也不是反义。", "欢迎": "“欢迎”指以热情接待某人，与“凭借”不构成反义关系。", "修理": "“修理”指修补损坏的东西，与“凭借”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96922, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确：“独立”与“依靠、依仗”意思相反，指自己做主，不靠别人或外物。"}, {"text": "检查", "is_correct": false, "explanation": "“检查”指仔细查看，与“凭借”不构成反义关系。"}, {"text": "祝福", "is_correct": false, "explanation": "“祝福”指表达美好的祝愿，与“凭借”不构成反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "“购买”指用钱买东西，与“凭借”不构成反义关系。"}], "correct_answer": "独立", "explanations": {"独立": "正确：“独立”与“依靠、依仗”意思相反，指自己做主，不靠别人或外物。", "检查": "“检查”指仔细查看，与“凭借”不构成反义关系。", "祝福": "“祝福”指表达美好的祝愿，与“凭借”不构成反义关系。", "购买": "“购买”指用钱买东西，与“凭借”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96922, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依靠；依仗。", "primary_collocate": null, "pronunciation": "píng jiè", "ipa": "pʰiŋ˧˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他凭借的只是一点好运气。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次成功，你凭借的是什么？", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有可以凭借的东西，我们只好走路回家。", "target_word": "凭借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她凭借的是十年的经验，不是书本。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小国凭借的只是地理位置。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "穷人没有可以凭借的资本。", "target_word": "凭借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板凭借的是关系，不是能力。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支队伍凭借的不是名气，而是团结。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想想看，自己到底凭借的是什么？", "target_word": "凭借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凭借的是家里的钱，不是自己的努力。", "target_word": "凭借", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "凭借着", "label": "体标"}], "register": "书面", "sense_fingerprint": "动词：依靠、依仗某种东西，常说“凭借的是……”“可凭借的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96922, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凭借", "is_correct": true, "explanation": "正确：凭借（píng jiè），意思是依靠、依仗某种东西。"}, {"text": "评级", "is_correct": false, "explanation": "评级（píng jí）与凭借（píng jiè）第二个音节的韵母不同（í 与 iè），意思是评定等级。"}, {"text": "平价", "is_correct": false, "explanation": "平价（píng jià）与凭借（píng jiè）第二个音节的韵母不同（ià 与 iè），意思是价格合理或低。"}, {"text": "凭据", "is_correct": false, "explanation": "凭据（píng jù）与凭借（píng jiè）第二个音节的韵母不同（ù 与 iè），意思是作为依据的证明。"}], "explanations": {"凭借": "正确：凭借（píng jiè），意思是依靠、依仗某种东西。", "评级": "评级（píng jí）与凭借（píng jiè）第二个音节的韵母不同（í 与 iè），意思是评定等级。", "平价": "平价（píng jià）与凭借（píng jiè）第二个音节的韵母不同（ià 与 iè），意思是价格合理或低。", "凭据": "凭据（píng jù）与凭借（píng jiè）第二个音节的韵母不同（ù 与 iè），意思是作为依据的证明。"}, "sentence_index": null, "correct_answer": "凭借"}, "level_3": {"options": [{"text": "凭借", "is_correct": true, "explanation": "正确：“凭借的只是……”指依靠、依仗的东西，“一点好运气”正是他依靠的东西。"}, {"text": "摆脱", "is_correct": false, "explanation": "搭配：“摆脱”要接困境或束缚，“摆脱的只是好运气”搭配不当。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”的对象是文章、计划等，不能说修改“好运气”。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌恶，与句中“只是一点好运气”表示依靠的语境不符，句意不通。"}], "explanations": {"凭借": "正确：“凭借的只是……”指依靠、依仗的东西，“一点好运气”正是他依靠的东西。", "摆脱": "搭配：“摆脱”要接困境或束缚，“摆脱的只是好运气”搭配不当。", "修改": "搭配：“修改”的对象是文章、计划等，不能说修改“好运气”。", "嫌弃": "语义：“嫌弃”表示厌恶，与句中“只是一点好运气”表示依靠的语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "凭借"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她凭借生病，没有来上班。", "explanation": "这里应该用〈因为〉。“凭借”指依靠有利的条件或能力，生病不是可以依靠的条件，应该用“因为”。"}, {"text": "凭借连日下雨，河水涨了。", "explanation": "这里应该用〈由于〉。“凭借”不能表示原因，连日下雨不是可以依靠的条件。"}, {"text": "凭借赶时间，他打了车。", "explanation": "这里应该用〈为了〉。“凭借”表示依靠某种条件，“赶时间”表示目的，应该用“为了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凭借", "is_correct": true, "explanation": "正确：“凭借的是……”指依靠的东西，“关系”正是老板依靠的东西。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能说“烹饪的是关系”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”指修补损坏的器物，“修理的是关系”不能这样搭配。"}, {"text": "倾听", "is_correct": false, "explanation": "语义：“倾听”的对象是声音或意见，与“关系、能力”的语境不符，句意不通。"}], "explanations": {"凭借": "正确：“凭借的是……”指依靠的东西，“关系”正是老板依靠的东西。", "烹饪": "搭配：“烹饪”的对象是食物，不能说“烹饪的是关系”。", "修理": "搭配：“修理”指修补损坏的器物，“修理的是关系”不能这样搭配。", "倾听": "语义：“倾听”的对象是声音或意见，与“关系、能力”的语境不符，句意不通。"}, "sentence_index": 6, "correct_answer": "凭借"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "凭借天气，我们取消了郊游。", "explanation": "这里应该用〈根据〉。“根据”表示以某种情况为依据，天气不是可以依靠的条件。"}, {"text": "她凭借铅笔写字。", "explanation": "这里应该用〈用〉。“凭借”强调依靠有利的条件或能力，只是使用工具时要用“用”，如“她用铅笔写字”。"}, {"text": "凭借很累，他还是坚持练琴。", "explanation": "这里应该用〈尽管〉。“凭借”不能表示让步，“很累”不是可以依靠的条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他能走到今天，凭借是多年的坚持。", "corrected_sentence": "他能走到今天，凭借的是多年的坚持。", "error_description": "“凭借的是……”中的“的”不能省。应说“凭借的是多年的坚持”，直接说“凭借是”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支队伍凭借是团结，不是名气。", "corrected_sentence": "这支队伍凭借的是团结，不是名气。", "error_description": "“凭借的是……”中的“的”不能省。应说“凭借的是团结”，直接说“凭借是”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
