INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里有机器部分的人，故事里才有。", "primary_collocate": null, "pronunciation": "diàn zǐ rén", "ipa": "tjɛn˥˩ tsɨ˨˩˦ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "这部电影里的电子人在城市里追捕坏人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子人的手臂是机器做的。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候最喜欢看电子人的故事。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现实生活里没有真正的电子人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书写了一个电子人的生活。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子人身体里有很多小机器。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想画一个会飞的电子人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子人在电影里常常帮助别人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电子人的眼睛可以看得很远。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次晚会上，他装扮成电子人，大家都很惊讶。", "target_word": "电子人", "complexity_tier": "T3", "furigana": "zhè cì wǎn huì shàng, tā zhuāng bàn chéng diàn zǐ rén, dà jiā dōu hěn jīng yà.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "電子人", "label": "繁体"}], "register": "通用", "sense_fingerprint": "名词，指故事、电影里身体里装有机器部分的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电子人", "is_correct": true, "explanation": "正确：“电子人”指故事、电影里身体有机器部分的人，与“在城市里追捕坏人”的情节相符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”不会追捕坏人，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是学习用书，不能去城市里追捕坏人，句意不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”没有行动能力，不能追捕坏人，句意不通。"}], "explanations": {"电子人": "正确：“电子人”指故事、电影里身体有机器部分的人，与“在城市里追捕坏人”的情节相符。", "蔬菜": "语义：“蔬菜”不会追捕坏人，句意不通。", "课本": "语义：“课本”是学习用书，不能去城市里追捕坏人，句意不通。", "饮料": "语义：“饮料”没有行动能力，不能追捕坏人，句意不通。"}, "sentence_index": 0, "correct_answer": "电子人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂里新装了很多电子人，专门用来洗衣服。", "explanation": "这里应该用〈机器人〉或〈机器〉。“电子人”指身体部分被机械替代的人，不指用来洗衣服的整台机器。"}, {"text": "我每天早上用电子人煮咖啡。", "explanation": "这里误把“电子人”当成“咖啡机”之类的电器。“电子人”指身体有机器部分的人，不是厨房用具。"}, {"text": "这个电子人是我每天早上做的早饭。", "explanation": "这里误把“电子人”当成“食物”的意思。“电子人”指身体有机械部分的人，不能是做出来的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子人", "is_correct": true, "explanation": "正确：“电子人”可以是想象中会飞的人形角色，与“我想画一个会飞的”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是抽象的气象状况，不能画成会飞的形象，句意不通。"}, {"text": "道理", "is_correct": false, "explanation": "语义：“道理”是抽象的观念，无法被画成会飞的形象，句意不通。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”是液体，不能作为“会飞的”形象来画，句意不通。"}], "explanations": {"电子人": "正确：“电子人”可以是想象中会飞的人形角色，与“我想画一个会飞的”相符。", "天气": "语义：“天气”是抽象的气象状况，不能画成会飞的形象，句意不通。", "道理": "语义：“道理”是抽象的观念，无法被画成会飞的形象，句意不通。", "墨水": "语义：“墨水”是液体，不能作为“会飞的”形象来画，句意不通。"}, "sentence_index": 6, "correct_answer": "电子人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天用电子人写作业。", "explanation": "这里误把“电子人”当成“机器”的意思，用来当作写作业的工具。“电子人”指身体有机械部分的人，不能当作工具使用。"}, {"text": "这个电子人是我昨天买的电脑。", "explanation": "这里误把“电子人”当成“电子设备”的意思，用来指电脑。“电子人”指身体有机械部分的人，不能用来指一台设备。"}, {"text": "这块电子人的面包很好吃。", "explanation": "这里误把“电子人”当成“电子产品”的意思，用来修饰面包。“电子人”指人，不能用来形容食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班来了一只电子人。", "corrected_sentence": "我们班来了一个电子人。", "error_description": "错误在量词“只”。“电子人”指人，应用“个”或“位”，说“一个电子人”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏里来了三台电子人。", "corrected_sentence": "这个游戏里来了三个电子人。", "error_description": "错误在量词“台”。“台”用于机器，“电子人”是人，应用“个”或“位”，说“三个电子人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
