INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体部分由机械替代的人，多见于科幻作品。", "primary_collocate": null, "pronunciation": "diàn zǐ rén", "ipa": "tjɛn˥˩ tsɨ˨˩˦ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "科幻小说里常常有电子人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子人的腿坏了，可以换一条新的。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那部科幻电影的主角是电子人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说，将来会出现很多电子人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子人的心脏是机器，不会累。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里可以选电子人当队友。", "target_word": "电子人", "complexity_tier": "T3", "furigana": "zhè ge yóu xì lǐ kě yǐ xuǎn diàn zǐ rén dāng duì yǒu.", "sentence_source": "generated"}, {"text": "她写了一本科幻书，书里的电子人身体一半是机器。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子人和普通人一起生活在城市里。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子人受伤后，医生用机器修好了他。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想当会打坏人的电子人。", "target_word": "电子人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "電子人", "label": "繁体"}], "register": "通用", "sense_fingerprint": "名词，指科幻作品中身体部分被机械替换的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电子人", "is_correct": true, "explanation": "正确：“电子人”指科幻作品中身体部分被机械替换的人，与“科幻小说里常常有”的语境相符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”不是科幻小说里的角色，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能像角色一样“有”在小说里，搭配不当。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”不是小说里的人物，句意不通。"}], "explanations": {"电子人": "正确：“电子人”指科幻作品中身体部分被机械替换的人，与“科幻小说里常常有”的语境相符。", "蔬菜": "语义：“蔬菜”不是科幻小说里的角色，句意不通。", "天气": "语义：“天气”不能像角色一样“有”在小说里，搭配不当。", "墨水": "语义：“墨水”不是小说里的人物，句意不通。"}, "sentence_index": 0, "correct_answer": "电子人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂里新装了很多电子人，专门用来搬货。", "explanation": "这里应该用〈机器人〉。“电子人”指身体部分被机械替代的人，不指用来搬货的整台机器。"}, {"text": "今天的电子人很好，阳光很温暖。", "explanation": "这里误把“电子人”当成“天气”的意思。“电子人”指身体部分被机械替代的人，不能用来描述天气。"}, {"text": "这个电子人是我昨天吃的面包。", "explanation": "这里误把“电子人”当成“食物”的意思。“电子人”指身体部分被机械替代的人，不能是吃的面包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子人", "is_correct": true, "explanation": "正确：“电子人”是科幻书里身体一半由机器构成的人物，与“身体一半是机器”的描写相符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”没有身体，不能一半是机器，句意不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是器皿，不能说身体一半是机器，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是学习用书，不会有一半由机器构成的身体，句意不通。"}], "explanations": {"电子人": "正确：“电子人”是科幻书里身体一半由机器构成的人物，与“身体一半是机器”的描写相符。", "饮料": "语义：“饮料”没有身体，不能一半是机器，句意不通。", "花瓶": "语义：“花瓶”是器皿，不能说身体一半是机器，句意不通。", "课本": "语义：“课本”是学习用书，不会有一半由机器构成的身体，句意不通。"}, "sentence_index": 6, "correct_answer": "电子人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家面包店的电子人很新鲜。", "explanation": "这里误把“电子人”当成“商品”的意思，用来形容面包店里的东西。“电子人”指人物，不能作商品描述。"}, {"text": "这台电脑是电子人。", "explanation": "这里误把“电子人”当成“电子设备”的意思，用来指电脑。“电子人”指身体部分被机械替代的人，不能用来指电脑。"}, {"text": "妈妈用电子人洗衣服。", "explanation": "这里误把“电子人”当成“机器”的意思，用来指洗衣的工具。“电子人”指身体部分被机械替代的人，不能当作洗衣机使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那部科幻电影里出现了一本电子人。", "corrected_sentence": "那部科幻电影里出现了一个电子人。", "error_description": "错误在量词“本”。“本”用于书籍等，“电子人”指人，应用“个”或“位”，说“一个电子人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏里有一只电子人很厉害。", "corrected_sentence": "这个游戏里有一个电子人很厉害。", "error_description": "错误在量词“只”。“只”不用于指人，“电子人”应用“个”或“位”，说“一个电子人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
