INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "让机器有电、能开动的地方。", "primary_collocate": null, "pronunciation": "diàn yuán", "ipa": "tjɛn˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "房间里的电源在床边。", "target_word": "电源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里有电源，你可以给手机充电。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡馆里每张桌子旁都有电源。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我找不到电源，手机快没电了。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把机器接到电源上。", "target_word": "电源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上座位旁有电源，可以充电。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电源在墙上，很不好找。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里没有电源，机器开不了。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会前，请先找好电源。", "target_word": "电源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电源在左边，你把线插上去。", "target_word": "电源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "电源线", "label": "复合"}, {"form": "电源开关", "label": "复合"}, {"form": "个", "label": "量词"}, {"form": "電源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "墙上或座位旁可以接电的地方，如插座", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96925, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不在房间里，与“房间里的……在床边”不合。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不可能在房间里，句子不成立。"}, {"text": "电源", "is_correct": true, "explanation": "正确：“电源”指床边墙上可以接电的地方，与句意相符。"}, {"text": "王朝", "is_correct": false, "explanation": "语域：王朝是历史用语，用在描述房间位置的口语句子里很突兀。"}], "explanations": {"天空": "语义：天空不在房间里，与“房间里的……在床边”不合。", "大海": "语义：大海不可能在房间里，句子不成立。", "电源": "正确：“电源”指床边墙上可以接电的地方，与句意相符。", "王朝": "语域：王朝是历史用语，用在描述房间位置的口语句子里很突兀。"}, "sentence_index": 0, "correct_answer": "电源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上在电源上刷牙。", "explanation": "这里应该用〈洗手台〉。电源是供电的地方，不能用来刷牙；刷牙要在洗手台。"}, {"text": "我们坐电源上楼。", "explanation": "这里应该用〈电梯〉。电源是供电的地方，不能乘坐；上楼乘坐的是电梯。"}, {"text": "我们去电源野餐。", "explanation": "这里应该用〈公园〉。电源是供电的地方，不能用来野餐；野餐要去公园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不可能挂在墙上，与句意不合。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是声音，不能在墙上被找到。"}, {"text": "电源", "is_correct": true, "explanation": "正确：“电源”指墙上可以接电的地方，句中说它在墙上、很难找，相符。"}, {"text": "乐章", "is_correct": false, "explanation": "语域：乐章是音乐术语，用来描述墙上的位置很突兀，且句意不通。"}], "explanations": {"月亮": "语义：月亮在天上，不可能挂在墙上，与句意不合。", "雷声": "语义：雷声是声音，不能在墙上被找到。", "电源": "正确：“电源”指墙上可以接电的地方，句中说它在墙上、很难找，相符。", "乐章": "语域：乐章是音乐术语，用来描述墙上的位置很突兀，且句意不通。"}, "sentence_index": 6, "correct_answer": "电源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去电源买了一本书。", "explanation": "这里应该用〈书店〉。电源是供电的地方，不是卖书的地方；买书要去书店。"}, {"text": "我在电源学习英语。", "explanation": "这里应该用〈学校〉。电源是供电的地方，不是学习的地方；学英语要去学校。"}, {"text": "我去电源看病。", "explanation": "这里应该用〈医院〉。电源是供电的地方，不能看病；看病要去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把电源坏掉了，手机插不上。", "corrected_sentence": "这个电源坏掉了，手机插不上。", "error_description": "量词错误：电源用“个”，“把”用于有柄的器具，不能用于电源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前用过这把电源。", "corrected_sentence": "我以前用过这个电源。", "error_description": "量词错误：电源用“个”，“把”用于有柄的器具，不能用于电源。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
