INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供给电力的装置或来源。", "primary_collocate": null, "pronunciation": "diàn yuán", "ipa": "tjɛn˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "请先关掉电源，再修电脑。", "target_word": "电源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器没有电源，打不开。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前别忘了关电源。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的电源坏了，灯不亮。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电源功率不够，机器一开就自动关机。", "target_word": "电源", "complexity_tier": "T3", "furigana": "zhè gè diàn yuán gōng lǜ bú gòu jī qì yī kāi jiù zì dòng guān jī", "sentence_source": "generated"}, {"text": "这个电源能给三台机器供电。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野外没有电源，我们带了电池。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电源出了问题，整个房间都黑了。", "target_word": "电源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员正在检查电源。", "target_word": "电源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小电源重量很轻，出门带着很方便。", "target_word": "电源", "complexity_tier": "T3", "furigana": "zhè gè xiǎo diàn yuán zhòng liàng hěn qīng chū mén dài zhe hěn fāng biàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "电源线", "label": "复合"}, {"form": "电源开关", "label": "复合"}, {"form": "个", "label": "量词"}, {"form": "電源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "给机器供电的装置，如电池、电源盒等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“关掉”用于电器、灯具等开关装置，不能用于作业。"}, {"text": "电源", "is_correct": true, "explanation": "正确：“关掉电源”指切断供电，与后半句“再修电脑”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是能开关的东西，与“关掉”的对象不符。"}, {"text": "作文", "is_correct": false, "explanation": "搭配：作文是写出来的，不能说“关掉”。"}], "explanations": {"作业": "搭配：“关掉”用于电器、灯具等开关装置，不能用于作业。", "电源": "正确：“关掉电源”指切断供电，与后半句“再修电脑”相符。", "颜色": "语义：颜色不是能开关的东西，与“关掉”的对象不符。", "作文": "搭配：作文是写出来的，不能说“关掉”。"}, "sentence_index": 0, "correct_answer": "电源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想给妈妈打个电源。", "explanation": "这里应该用〈电话〉。打电话是给人通话，电源是供电装置，不能用来通话。"}, {"text": "晚上我坐在电源上看书。", "explanation": "这里应该用〈沙发〉。电源是供电装置，不能当座位；坐着看书要用沙发或椅子。"}, {"text": "我们坐电源去机场。", "explanation": "这里应该用〈汽车〉。电源是供电装置，不能乘坐；去机场乘坐的是汽车或出租车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食品", "is_correct": false, "explanation": "语义：食品不能供电，“没有食品，所以带了电池”因果不通。"}, {"text": "电源", "is_correct": true, "explanation": "正确：“野外没有电源”指没有可供电的地方，所以带了电池。"}, {"text": "甘霖", "is_correct": false, "explanation": "语域：甘霖是书面雅语，放在这样的口语叙述里很突兀，且与带电池无关。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图与带电池无关，句子因果不通。"}], "explanations": {"食品": "语义：食品不能供电，“没有食品，所以带了电池”因果不通。", "电源": "正确：“野外没有电源”指没有可供电的地方，所以带了电池。", "甘霖": "语域：甘霖是书面雅语，放在这样的口语叙述里很突兀，且与带电池无关。", "地图": "语义：地图与带电池无关，句子因果不通。"}, "sentence_index": 6, "correct_answer": "电源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的电源是LED。", "explanation": "这里应该用〈光源〉。电源是供电装置，本身不发光；发光的部件要说光源。"}, {"text": "这台机器消耗的电源很多。", "explanation": "这里应该用〈电能〉。电源是供电装置，不会被消耗；机器耗用的是电能。"}, {"text": "这台电源很快，运行很流畅。", "explanation": "这里应该用〈电脑〉。电源只负责供电，不负责运行程序；运行快、流畅的是电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这把电源关掉了。", "corrected_sentence": "我把这个电源关掉了。", "error_description": "量词错误：电源用“个”，“把”用于有柄的器具，不能用于电源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买过这把小电源。", "corrected_sentence": "我买过这个小电源。", "error_description": "量词错误：电源用“个”，“把”用于有柄的器具，不能用于电源。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
