INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96927, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写着朋友电话号码的小本子。", "primary_collocate": null, "pronunciation": "diàn huà běn", "ipa": "tjɛn˥˩ xwa˥˩ pən˨˩˦", "syllable_count": 3, "sentences": [{"text": "我的电话本里有很多朋友的号码。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的电话本放在桌子上。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电话本上写了他的号码。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他翻开电话本找老王的电话。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本电话本是朋友送给我的。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话本里写着我所有朋友的名字。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的电话本已经很旧了。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的电话本带来。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到电话本了，你看见了吗？", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话本最后一页写了地址。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "電話本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写着朋友电话号码的小本子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物园", "is_correct": false, "explanation": "语义：动物园里装的是动物，不会存放朋友的电话号码，句子说不通。"}, {"text": "电话本", "is_correct": true, "explanation": "正确：电话本指写着朋友电话号码的小本子，填入后与“里有很多朋友的号码”相符。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：书架上放的是书，“书架里有朋友的号码”不是常见说法，“书架”与“号码”搭配不当。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，里面不会存着朋友的电话号码。"}], "explanations": {"动物园": "语义：动物园里装的是动物，不会存放朋友的电话号码，句子说不通。", "电话本": "正确：电话本指写着朋友电话号码的小本子，填入后与“里有很多朋友的号码”相符。", "书架": "搭配：书架上放的是书，“书架里有朋友的号码”不是常见说法，“书架”与“号码”搭配不当。", "西瓜": "语义：西瓜是水果，里面不会存着朋友的电话号码。"}, "sentence_index": 0, "correct_answer": "电话本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次开会的重点，我都用电话本记下来了。", "explanation": "这里应该用〈笔记本〉。电话本只用来记电话号码，记会议重点要用笔记本。"}, {"text": "我每天晚上都在电话本上写日记。", "explanation": "这里应该用〈日记本〉。电话本只记电话号码，写日记要用日记本。"}, {"text": "我每天在电话本上查生词。", "explanation": "这里应该用〈词典〉。电话本只记电话号码，查生词要用词典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不会因为放久而“很旧”，句子说的是妈妈的一件物品。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“很旧”形容有形的物品，不能说时间“很旧”。"}, {"text": "电话本", "is_correct": true, "explanation": "正确：电话本是实物，用久了会旧，填入后与“妈妈的……已经很旧了”相符。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：形容人的外貌要用“老”或“苍老”，不用“旧”来说脸的状态。"}], "explanations": {"西瓜": "语义：西瓜是水果，不会因为放久而“很旧”，句子说的是妈妈的一件物品。", "时间": "搭配：“很旧”形容有形的物品，不能说时间“很旧”。", "电话本": "正确：电话本是实物，用久了会旧，填入后与“妈妈的……已经很旧了”相符。", "脸": "体貌：形容人的外貌要用“老”或“苍老”，不用“旧”来说脸的状态。"}, "sentence_index": 6, "correct_answer": "电话本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都在电话本上记收支。", "explanation": "这里应该用〈账本〉。电话本只记电话号码，记收支要用账本。"}, {"text": "老师要求我们每天在电话本上写作业。", "explanation": "这里应该用〈作业本〉。电话本是记号码的，写作业要用作业本。"}, {"text": "孩子把画好的画都贴进了电话本里。", "explanation": "这里应该用〈画册〉。电话本只记号码，收集和贴存图画要用画册。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我终于找了到电话本。", "corrected_sentence": "我终于找到了电话本。", "error_description": "补语错误：结果补语“到”应紧跟在“找”后，说“找到了”，不能说“找了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我用过这张电话本。", "corrected_sentence": "我用过这本电话本。", "error_description": "量词错误：电话本是册子，应用量词“本”，不能用“张”，应说“这本电话本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
