INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记录电话号码的本子。", "primary_collocate": null, "pronunciation": "diàn huà běn", "ipa": "tjɛn˥˩ xwa˥˩ pən˨˩˦", "syllable_count": 3, "sentences": [{"text": "现在很多人不用电话本了。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一个红色的电话本。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话本是用来记号码的。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把新同学的号码记进电话本。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的桌上有一本电话本。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我常常看爸爸的电话本。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话本太小，我写不下这么多号码。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从包里拿出电话本，开始打电话。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话本的纸很好。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话本掉在地上了。", "target_word": "电话本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "電話本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来记录电话号码的本子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：人们不可能“不用”空气，句子说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：句子说的是人们不再使用某种记号码的工具，“石头”与句意无关。"}, {"text": "电话本", "is_correct": true, "explanation": "正确：现在不少人不再用纸本记号码，填入电话本后句意完整。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，人们不会“不用”太阳，与句意无关。"}], "explanations": {"空气": "语义：人们不可能“不用”空气，句子说不通。", "石头": "语义：句子说的是人们不再使用某种记号码的工具，“石头”与句意无关。", "电话本": "正确：现在不少人不再用纸本记号码，填入电话本后句意完整。", "太阳": "语义：太阳是天体，人们不会“不用”太阳，与句意无关。"}, "sentence_index": 0, "correct_answer": "电话本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上课时，我把老师讲的重点都记进了电话本。", "explanation": "这里应该用〈笔记本〉。电话本只用来记电话号码，记课堂重点要用笔记本。"}, {"text": "我把下周的日程安排写在电话本上。", "explanation": "这里应该用〈日程本〉。电话本只记电话号码，安排日程要用日程本。"}, {"text": "这学期的作文我都写在电话本上。", "explanation": "这里应该用〈作文本〉。电话本只记电话号码，写作文要用作文本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大海", "is_correct": false, "explanation": "语义：大海不会因为“太小”而写不下号码，句子不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“太小”描述的是眼睛的外形，与“写不下号码”无关。"}, {"text": "电话本", "is_correct": true, "explanation": "正确：说的是记号码的本子太小、写不下，填入电话本后与句意相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能拿来写号码，句子说不通。"}], "explanations": {"大海": "语义：大海不会因为“太小”而写不下号码，句子不通。", "眼睛": "体貌：“太小”描述的是眼睛的外形，与“写不下号码”无关。", "电话本": "正确：说的是记号码的本子太小、写不下，填入电话本后与句意相符。", "月亮": "语义：月亮是天体，不能拿来写号码，句子说不通。"}, "sentence_index": 6, "correct_answer": "电话本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全家旅游回来，我把照片都放进了电话本。", "explanation": "这里应该用〈相册〉。电话本只记号码，存放照片要用相册。"}, {"text": "老师让我们在电话本上做练习。", "explanation": "这里应该用〈练习册〉。电话本只记号码，做练习要用练习册。"}, {"text": "我把不会的生词记在电话本上。", "explanation": "这里应该用〈生词本〉。电话本只记电话号码，记生词要用生词本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把电话本了丢。", "corrected_sentence": "他把电话本丢了。", "error_description": "“了”位置错误：完成的“了”应紧跟动词，说“丢了”，不能说“了丢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了一只新电话本。", "corrected_sentence": "她买了一本新电话本。", "error_description": "量词错误：“电话本”的量词是“本”，“只”用于动物等，不能说“一只电话本”，应说“一本新电话本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96930, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本分", "is_correct": true, "explanation": "反义：“本分”指分内应有的，与“非分”意思相对。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：“勇敢”指不怕困难，与“非分”无关。"}, {"text": "冷静", "is_correct": false, "explanation": "无反义关系：“冷静”指情绪稳定，与“非分”无关。"}, {"text": "富有", "is_correct": false, "explanation": "无反义关系：“富有”指财产多，与“非分”的“不应得”无关。"}], "correct_answer": "本分", "explanations": {"本分": "反义：“本分”指分内应有的，与“非分”意思相对。", "勇敢": "无反义关系：“勇敢”指不怕困难，与“非分”无关。", "冷静": "无反义关系：“冷静”指情绪稳定，与“非分”无关。", "富有": "无反义关系：“富有”指财产多，与“非分”的“不应得”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96930, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本分", "is_correct": true, "explanation": "反义：“本分”指分内应有的，与“非分”意思相对。"}, {"text": "大方", "is_correct": false, "explanation": "无反义关系：“大方”指不拘小节，与“非分”无关。"}, {"text": "严肃", "is_correct": false, "explanation": "无反义关系：“严肃”指态度庄重，与“非分”无关。"}, {"text": "活泼", "is_correct": false, "explanation": "无反义关系：“活泼”指性情开朗，与“非分”无关。"}], "correct_answer": "本分", "explanations": {"本分": "反义：“本分”指分内应有的，与“非分”意思相对。", "大方": "无反义关系：“大方”指不拘小节，与“非分”无关。", "严肃": "无反义关系：“严肃”指态度庄重，与“非分”无关。", "活泼": "无反义关系：“活泼”指性情开朗，与“非分”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96930, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超出本分的；不应得的。", "primary_collocate": null, "pronunciation": "fēi fèn", "ipa": "fei˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "小职员却想管经理的事，这是非分的要求。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做好了本分的事，从不提非分的要求。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生对老师提非分的要求，是不对的。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道自己的身份，从不做非分的事。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新人要老板的位置，这是非分的想法。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿的钱都是工资，没有一分是非分之财。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别对朋友有非分的期待。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有非分的野心，想一个人管整个公司。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己不敢有非分之想，只想把工作做好。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种非分的要求，老板当然不会同意。", "target_word": "非分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非分之想", "label": "复合"}, {"form": "非分之财", "label": "复合"}], "register": "书面", "sense_fingerprint": "非分：超出本分、不应得的，如非分的要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8adc1b-9d40-4b43-9a93-25a8a9f56bae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非分", "is_correct": true, "explanation": "正确：“非分”指超出本分的要求，与“小职员却想管经理的事”相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能修饰“要求”。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：“清淡”形容味道或色调，不能修饰“要求”。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”指光线充足，与“要求”的意思不合。"}], "explanations": {"非分": "正确：“非分”指超出本分的要求，与“小职员却想管经理的事”相符。", "高大": "体貌：“高大”形容身材，不能修饰“要求”。", "清淡": "搭配：“清淡”形容味道或色调，不能修饰“要求”。", "明亮": "语义：“明亮”指光线充足，与“要求”的意思不合。"}, "sentence_index": 0, "correct_answer": "非分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试非分地好，连老师都没想到。", "explanation": "这里应该用〈出色〉。非分指超出本分、不应得，形容成绩好不能用“非分”。"}, {"text": "他每天按时上班，这是非分的事。", "explanation": "这里应该用〈分内〉。按时上班是分内之事，不能说“非分”。"}, {"text": "他工作努力，拿到了非分的回报。", "explanation": "这里应该用〈应得〉。努力工作后的回报是他应得的，不能说“非分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“期待”。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不能修饰“期待”。"}, {"text": "非分", "is_correct": true, "explanation": "正确：“非分的期待”指不应有的过高期待，与“别对朋友”相符。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”指空间窄小，与“期待”的意思不合。"}], "explanations": {"清脆": "搭配：“清脆”形容声音，不能修饰“期待”。", "矮小": "体貌：“矮小”形容身材，不能修饰“期待”。", "非分": "正确：“非分的期待”指不应有的过高期待，与“别对朋友”相符。", "狭窄": "语义：“狭窄”指空间窄小，与“期待”的意思不合。"}, "sentence_index": 6, "correct_answer": "非分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每个人都享有非分的生存权利。", "explanation": "这里应该用〈基本〉。生存权利是人人应有的，不能说“非分”。"}, {"text": "学生尊重老师，这是非分的事。", "explanation": "这里应该用〈理所当然〉。学生尊重老师是分内之事，不能说“非分”。"}, {"text": "他每天非分地早起，比谁都勤奋。", "explanation": "这里应该用〈格外〉。非分指超出本分、不应得，早起勤奋不是不应得的，不能用“非分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从不贪图非分得财，只靠劳动吃饭。", "corrected_sentence": "他从不贪图非分之财，只靠劳动吃饭。", "error_description": "错误：“非分得财”；正确：“非分之财”。“得”不能修饰名词“财”，“非分之财”是固定的书面搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他提出了非分得条件，大家都不同意。", "corrected_sentence": "他提出了非分的条件，大家都不同意。", "error_description": "错误：“非分得条件”；正确：“非分的条件”。“得”用于补语，修饰名词“条件”时要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
