INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "带领他人的才能。", "primary_collocate": null, "pronunciation": "lǐng dǎo néng lì", "ipa": "liŋ˨˩ tau˨˩ nɤŋ˧˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "做班长需要很强的领导能力。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的领导能力得到了大家的认可。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司很看重领导能力。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就表现出领导能力。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的领导能力比小王强。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师也要有领导能力。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动能提高你的领导能力。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理最重要的是领导能力。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有领导能力，大家不服他。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在比赛中练习领导能力。", "target_word": "领导能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "带领、组织他人的才能，常与班长、经理、队长等角色相关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400b5293-dbe8-4b37-a144-768922327a84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领导能力", "is_correct": true, "explanation": "正确：“很强的领导能力”指带领他人的才能，与班长的要求相符。"}, {"text": "美貌", "is_correct": false, "explanation": "语义：“很强”说能力，不说外貌。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很强”不修饰身高。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“很强的体温”不成搭配。"}], "explanations": {"领导能力": "正确：“很强的领导能力”指带领他人的才能，与班长的要求相符。", "美貌": "语义：“很强”说能力，不说外貌。", "身高": "搭配：“很强”不修饰身高。", "体温": "搭配：“很强的体温”不成搭配。"}, "sentence_index": 0, "correct_answer": "领导能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班的领导能力。", "explanation": "这里应该用〈领导人〉。“领导能力”指能力本身，不指担任领导的人。"}, {"text": "请领导能力在这份文件上签字。", "explanation": "这里应该用〈领导〉。签字的是人，“领导能力”只指能力。"}, {"text": "公司的领导能力今天都去开会了。", "explanation": "这里应该用〈领导〉。去开会的是人，“领导能力”只指才能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领导能力", "is_correct": true, "explanation": "正确：“提高你的领导能力”与活动的作用相符。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“提高”用于水平、能力，不说提高脾气。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄只会增长，不能说“提高年龄”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是可以提高的水平或质量，与句意不符。"}], "explanations": {"领导能力": "正确：“提高你的领导能力”与活动的作用相符。", "脾气": "搭配：“提高”用于水平、能力，不说提高脾气。", "年龄": "搭配：年龄只会增长，不能说“提高年龄”。", "名字": "语义：名字不是可以提高的水平或质量，与句意不符。"}, "sentence_index": 6, "correct_answer": "领导能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司来了一位新的领导能力。", "explanation": "这里应该用〈领导〉。“一位”用于人，“领导能力”指才能，不指人。"}, {"text": "我们班的领导能力今天生病请假了。", "explanation": "这里应该用〈班长〉。请假的是人，“领导能力”只指才能。"}, {"text": "我想当一个领导能力，去管大家。", "explanation": "这里应该用〈领导人〉。“领导能力”指能力本身，不指担任领导的人，不能说“当一个领导能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一块很强的领导能力。", "corrected_sentence": "她有一种很强的领导能力。", "error_description": "“领导能力”是抽象名词，量词应用“种”。“块”用于块状的物体，不能修饰能力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一张很强的领导能力。", "corrected_sentence": "他有一项很强的领导能力。", "error_description": "“领导能力”是抽象能力，量词应用“项”。“张”只用于纸片等平面物，不能修饰能力。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
