INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海上刮来，特别大的风。", "primary_collocate": null, "pronunciation": "jù fēng", "ipa": "tɕy˥˩ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "海上刮起了飓风，船不能出海。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飓风刮了一夜，窗户都响了。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民看见天边有飓风要来了。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飓风吹断了海边的大树。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的飓风让海浪特别高。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边遇到了飓风。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飓风来时，天空变得很暗。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飓风吹得帆船摇来摇去。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说飓风明天会到这座岛。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岛上的人怕飓风，窗户都钉好了。", "target_word": "飓风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}], "register": "通用", "sense_fingerprint": "从海上刮来的特别大的风，强调风大、海浪高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400b5293-dbe8-4b37-a144-768922327a84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飓风", "is_correct": true, "explanation": "飓风是从海上刮来的特别大的风，风大、海浪高，船不能出海，符合句意。"}, {"text": "春雨", "is_correct": false, "explanation": "搭配：「刮起」用于风、尘土等，不能说「刮起春雨」。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：「刮起」只用于风或尘土，不能用于阳光。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是建筑内的空间，不会被风刮起。"}], "explanations": {"飓风": "飓风是从海上刮来的特别大的风，风大、海浪高，船不能出海，符合句意。", "春雨": "搭配：「刮起」用于风、尘土等，不能说「刮起春雨」。", "阳光": "搭配：「刮起」只用于风或尘土，不能用于阳光。", "教室": "语义：教室是建筑内的空间，不会被风刮起。"}, "sentence_index": 0, "correct_answer": "飓风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海上吹来一阵飓风，船帆轻轻地动了起来。", "explanation": "这里应该用〈微风〉。飓风风力极大，不能用来形容轻轻吹动船帆的风。"}, {"text": "傍晚的飓风很凉爽，海边的人都坐在沙滩上聊天。", "explanation": "这里应该用〈海风〉。飓风风力极大，不能用来形容凉爽宜人的傍晚海风。"}, {"text": "海上突然出现的飓风只有几米宽，几分钟就散了。", "explanation": "这里应该用〈龙卷风〉。飓风范围很大、持续时间长，不会只有几米宽、几分钟就散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飓风", "is_correct": true, "explanation": "飓风是从海上刮来的大风，来时天空会变暗，符合句意。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨天色渐亮，与「天空变得很暗」的描述相反。"}, {"text": "烟花", "is_correct": false, "explanation": "语义：烟花会让天空变亮，不会使天空变暗。"}, {"text": "汗水", "is_correct": false, "explanation": "搭配：「来时」多用于天气或事件，不能说「汗水来时」，也与天空无关。"}], "explanations": {"飓风": "飓风是从海上刮来的大风，来时天空会变暗，符合句意。", "清晨": "语义：清晨天色渐亮，与「天空变得很暗」的描述相反。", "烟花": "语义：烟花会让天空变亮，不会使天空变暗。", "汗水": "搭配：「来时」多用于天气或事件，不能说「汗水来时」，也与天空无关。"}, "sentence_index": 6, "correct_answer": "飓风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外面的飓风很小，连树叶都吹不动。", "explanation": "这里应该用〈微风〉。飓风是特别大的风，不会小到吹不动树叶。"}, {"text": "冬天北方常刮飓风，天气很冷。", "explanation": "这里应该用〈寒风〉。飓风从海上刮来，不是北方冬天常见的冷风。"}, {"text": "电风扇吹出的飓风让人很舒服。", "explanation": "这里应该用〈凉风〉。飓风是海上的特大风，电风扇吹不出飓风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只飓风刮得特别猛，海上的船都回港了。", "corrected_sentence": "这场飓风刮得特别猛，海上的船都回港了。", "error_description": "量词错误：飓风应该用量词「场」，不能用「只」。正确的说法是「这场飓风」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场飓风刮了断很多渔船的缆绳。", "corrected_sentence": "这场飓风刮断了很多渔船的缆绳。", "error_description": "补语与“了”的位置错误：结果补语「断」应紧跟动词「刮」，「了」放在「断」之后，应说「刮断了很多渔船的缆绳」，不能说「刮了断」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
