INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手把物体取起。", "primary_collocate": null, "pronunciation": "ná qǐ", "ipa": "na˧˥ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他拿起桌上的书。", "target_word": "拿起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我拿起笔写下了名字。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈拿起杯子喝了一口水。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你拿起那本红色的书。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从地上拿起一张纸。", "target_word": "拿起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师拿起粉笔写了一个字。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿起钥匙，打开了门。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子拿起勺子，开始吃饭。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿起地图看了很久，还是不懂。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拿起行李，走出了车站。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿起了", "label": "体标"}, {"form": "拿起过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手把桌上、地上的物体取起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba7539fe-b5aa-4d48-a3b7-ff2bf389d79f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拿起", "is_correct": true, "explanation": "正确：“拿起”指用手把桌上的书取起来，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：书不能吃，“吃”的对象应是食物。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指动笔写出文字，桌上已经印好的书不能用“写”。"}, {"text": "端起", "is_correct": false, "explanation": "搭配：“端”多用于托着碗盘，不说端书。"}], "explanations": {"拿起": "正确：“拿起”指用手把桌上的书取起来，与句意相符。", "吃": "语义：书不能吃，“吃”的对象应是食物。", "写": "语义：“写”指动笔写出文字，桌上已经印好的书不能用“写”。", "端起": "搭配：“端”多用于托着碗盘，不说端书。"}, "sentence_index": 0, "correct_answer": "拿起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿起右手，向大家打了个招呼。", "explanation": "这里应该用〈举起〉。“拿起”是用手握住物体取起来，手本身不能被拿起；举手打招呼要说“举起右手”。"}, {"text": "一阵风拿起了路上的落叶。", "explanation": "这里应该用〈卷起〉。“拿起”需要有人用手握住物体，风把落叶卷上半空要说“卷起”。"}, {"text": "她拿起脚，轻轻走进了房间。", "explanation": "这里应该用〈抬起〉。脚不能用手拿，抬起脚要用“抬起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿起", "is_correct": true, "explanation": "正确：“拿起”指用手握住钥匙取起来，与句意相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：钥匙不能咬，“咬”的对象一般是食物。"}, {"text": "亲", "is_correct": false, "explanation": "搭配：“亲”指亲吻或贴近，不说亲钥匙。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：钥匙不能嚼，“嚼”只用于食物。"}], "explanations": {"拿起": "正确：“拿起”指用手握住钥匙取起来，与句意相符。", "咬": "语义：钥匙不能咬，“咬”的对象一般是食物。", "亲": "搭配：“亲”指亲吻或贴近，不说亲钥匙。", "嚼": "语义：钥匙不能嚼，“嚼”只用于食物。"}, "sentence_index": 6, "correct_answer": "拿起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿起拳头，冲向对手。", "explanation": "这里应该用〈挥起〉。拳头不能被拿起取走，挥动拳头要用“挥起”。"}, {"text": "这本书拿起了我的注意。", "explanation": "这里应该用〈引起〉。“拿起”用于握住有形的东西，注意力不能被拿起，应说“引起注意”。"}, {"text": "台风拿起了屋顶的瓦片。", "explanation": "这里应该用〈掀起〉。台风把瓦片揭起来要说“掀起”，“拿起”需要有人用手握住物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把拿起一支笔，在纸上画了一个圈。", "corrected_sentence": "她拿起一支笔，在纸上画了一个圈。", "error_description": "“把”字句中“把”后应接名词性宾语，而“拿起”是动词，不能充当“把”的宾语；“拿起”本身可以直接带宾语，应说“她拿起一支笔”，错误在多出“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈拿起着一部手机，给爸爸打了个电话。", "corrected_sentence": "妈妈拿起了一部手机，给爸爸打了个电话。", "error_description": "“拿起”表示一次性的取物动作，完成后应接“了”；“着”表示持续状态，与“拿起”搭配不自然。正确说法是“拿起了一部手机”，错误在把“了”换成了“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96941, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "归还", "is_correct": true, "explanation": "“归还”指把拿走的东西还回去，与“掠夺”相反。"}, {"text": "挖掘", "is_correct": false, "explanation": "“挖掘”指向下掘取，与“掠夺”没有对立关系。"}, {"text": "栽培", "is_correct": false, "explanation": "“栽培”指培育植物或人才，与“掠夺”无关。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子考虑问题，与“掠夺”无关。"}], "correct_answer": "归还", "explanations": {"归还": "“归还”指把拿走的东西还回去，与“掠夺”相反。", "挖掘": "“挖掘”指向下掘取，与“掠夺”没有对立关系。", "栽培": "“栽培”指培育植物或人才，与“掠夺”无关。", "思考": "“思考”指用脑子考虑问题，与“掠夺”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96941, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退还", "is_correct": true, "explanation": "“退还”指把钱或物品退回原主，与“掠夺”相反。"}, {"text": "种植", "is_correct": false, "explanation": "“种植”指栽种农作物或树木，与“掠夺”没有对立关系。"}, {"text": "歌唱", "is_correct": false, "explanation": "“歌唱”指唱歌，与“掠夺”无关。"}, {"text": "审核", "is_correct": false, "explanation": "“审核”指检查核实，与“掠夺”无关。"}], "correct_answer": "退还", "explanations": {"退还": "“退还”指把钱或物品退回原主，与“掠夺”相反。", "种植": "“种植”指栽种农作物或树木，与“掠夺”没有对立关系。", "歌唱": "“歌唱”指唱歌，与“掠夺”无关。", "审核": "“审核”指检查核实，与“掠夺”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力气抢走别人的东西。", "primary_collocate": null, "pronunciation": "lüè duó", "ipa": "lɥe˥˩ two˧˥", "syllable_count": 2, "sentences": [{"text": "强盗掠夺了村子里的粮食。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们掠夺了商人的财物。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土匪闯进村子，掠夺了村民的东西。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土匪常常掠夺路过的商队。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人掠夺了这座城里的钱。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们掠夺过很多小村子。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗掠夺着来往的船只。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能掠夺别人辛苦得来的东西。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那群强盗掠夺了过路人的财物。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上写着，军队掠夺了农民的牛羊。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掠夺了", "label": "体标"}, {"form": "掠夺过", "label": "体标"}, {"form": "掠夺着", "label": "体标"}, {"form": "掠奪", "label": "繁体"}], "register": "书面", "sense_fingerprint": "掠夺：用力气抢走别人的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400b5293-dbe8-4b37-a144-768922327a84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96941, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掠夺", "is_correct": true, "explanation": "正确：“掠夺”指用暴力抢夺，与“强盗”的身份和句意相合。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”是用钱换取，与强盗用暴力夺取的行为不符。"}, {"text": "捐", "is_correct": false, "explanation": "语义：“捐”是自愿赠送，强盗不会这样做。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是把东西给人，与强盗夺取粮食的行为不符。"}], "explanations": {"掠夺": "正确：“掠夺”指用暴力抢夺，与“强盗”的身份和句意相合。", "买": "语义：“买”是用钱换取，与强盗用暴力夺取的行为不符。", "捐": "语义：“捐”是自愿赠送，强盗不会这样做。", "送": "语义：“送”是把东西给人，与强盗夺取粮食的行为不符。"}, "sentence_index": 0, "correct_answer": "掠夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小偷掠夺了我的钱包。", "explanation": "这里应该用〈偷〉。“掠夺”指用暴力公开抢夺，偷是暗中拿走，不用“掠夺”。"}, {"text": "消防员冲进火场，掠夺了那个孩子。", "explanation": "这里应该用〈救〉。“掠夺”指用暴力抢走别人的东西，救人不能用“掠夺”。"}, {"text": "老师掠夺了他的漫画书。", "explanation": "这里应该用〈没收〉。“掠夺”含有非法抢夺之意，老师依规收走物品不用“掠夺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掠夺", "is_correct": true, "explanation": "正确：“掠夺”指用暴力抢夺，与“海盗”的行为相合，可以带“着”。"}, {"text": "点名", "is_correct": false, "explanation": "搭配：“点名”用于叫人的名字，不能用于来往的船只。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”是对人表达美好的愿望，海盗不会这样对待来往的船只。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指把损坏的东西修好，与海盗的行为不符。"}], "explanations": {"掠夺": "正确：“掠夺”指用暴力抢夺，与“海盗”的行为相合，可以带“着”。", "点名": "搭配：“点名”用于叫人的名字，不能用于来往的船只。", "祝福": "语义：“祝福”是对人表达美好的愿望，海盗不会这样对待来往的船只。", "修理": "语义：“修理”指把损坏的东西修好，与海盗的行为不符。"}, "sentence_index": 6, "correct_answer": "掠夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向同学掠夺了一支笔，用完就还。", "explanation": "这里应该用〈借〉。“掠夺”含有强行夺取的意思，向同学借东西不能用“掠夺”。"}, {"text": "我在超市掠夺了一瓶水。", "explanation": "这里应该用〈买〉。“掠夺”指强行夺取，在超市付钱购买不能用“掠夺”。"}, {"text": "他掠夺了这次比赛的奖金。", "explanation": "这里应该用〈领〉。“掠夺”是强行夺取，正常领取奖金不能用“掠夺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海盗把过往商船的货物掠夺。", "corrected_sentence": "海盗把过往商船的货物掠夺了。", "error_description": "“把”字句错误：“把”字句的动词后要有补语或“了”等成分，不能只说“把……掠夺”。正确的说法是“海盗把过往商船的货物掠夺了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌军掠夺着了城里的粮仓。", "corrected_sentence": "敌军掠夺了城里的粮仓。", "error_description": "“着”与“了”不能同时用在同一个动词后面。应只保留“了”，说“掠夺了”，不能说“掠夺着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96942, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "给予", "is_correct": true, "explanation": "“给予”指送给别人，与“掠夺”（夺取）意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指深入探讨，与“掠夺”没有对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细察看，与“掠夺”无关。"}, {"text": "调节", "is_correct": false, "explanation": "“调节”指使之适当变化，与“掠夺”无关。"}], "correct_answer": "给予", "explanations": {"给予": "“给予”指送给别人，与“掠夺”（夺取）意思相反。", "研究": "“研究”指深入探讨，与“掠夺”没有对立关系。", "观察": "“观察”指仔细察看，与“掠夺”无关。", "调节": "“调节”指使之适当变化，与“掠夺”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96942, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赠送", "is_correct": true, "explanation": "“赠送”指无偿送给别人，与“掠夺”（夺取）相反。"}, {"text": "咨询", "is_correct": false, "explanation": "“咨询”指向人询问、请教，与“掠夺”无关。"}, {"text": "组装", "is_correct": false, "explanation": "“组装”指把零件装成整体，与“掠夺”无关。"}, {"text": "停留", "is_correct": false, "explanation": "“停留”指暂时停下或住下，与“掠夺”无关。"}], "correct_answer": "赠送", "explanations": {"赠送": "“赠送”指无偿送给别人，与“掠夺”（夺取）相反。", "咨询": "“咨询”指向人询问、请教，与“掠夺”无关。", "组装": "“组装”指把零件装成整体，与“掠夺”无关。", "停留": "“停留”指暂时停下或住下，与“掠夺”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用暴力抢夺（财物、资源）。", "primary_collocate": null, "pronunciation": "lüè duó", "ipa": "lɥe˥˩ two˧˥", "syllable_count": 2, "sentences": [{"text": "殖民者掠夺了当地的资源。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们掠夺这个国家的石油和黄金。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，军队掠夺了许多财物。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去，有些国家掠夺别国的资源。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侵略者掠夺了这片土地上的矿产。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战乱年代，他们掠夺了村民的全部财产。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国公司掠夺过这里的矿产。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家不允许任何人掠夺自然资源。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侵略军掠夺了博物馆里的宝物。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殖民者一边掠夺财富，一边压迫百姓。", "target_word": "掠夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掠夺了", "label": "体标"}, {"form": "掠夺过", "label": "体标"}, {"form": "掠夺着", "label": "体标"}, {"form": "掠奪", "label": "繁体"}], "register": "书面", "sense_fingerprint": "掠夺：用暴力抢夺财物、资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400b5293-dbe8-4b37-a144-768922327a84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掠夺", "is_correct": true, "explanation": "正确：“掠夺”指用暴力夺取资源，与“殖民者”的行为相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫、维护，与殖民者掠取资源的行为相反。"}, {"text": "赠予", "is_correct": false, "explanation": "语义：“赠予”是无偿给予，与殖民者夺取资源的行为不符。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：“修复”多用于损坏的东西，资源一般不说修复。"}], "explanations": {"掠夺": "正确：“掠夺”指用暴力夺取资源，与“殖民者”的行为相合。", "保护": "语义：“保护”是护卫、维护，与殖民者掠取资源的行为相反。", "赠予": "语义：“赠予”是无偿给予，与殖民者夺取资源的行为不符。", "修复": "搭配：“修复”多用于损坏的东西，资源一般不说修复。"}, "sentence_index": 0, "correct_answer": "掠夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山里掠夺了一株草药。", "explanation": "这里应该用〈采〉。“掠夺”指用暴力夺取，在山里采草药不能用“掠夺”。"}, {"text": "两国用粮食掠夺了石油。", "explanation": "这里应该用〈交换〉。“掠夺”只指用暴力夺取，不表示双方自愿的交换。"}, {"text": "他在新学校里掠夺了几个新朋友。", "explanation": "这里应该用〈结交〉。“掠夺”指用暴力夺取财物或资源，不能用于交朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掠夺", "is_correct": true, "explanation": "正确：“掠夺”指用暴力夺取，与“外国公司”的行为相合，可以带“过”。"}, {"text": "养殖", "is_correct": false, "explanation": "搭配：“养殖”的对象是动植物，矿产不能用“养殖”。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于农作物、树木，不能用于矿产。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指给动物或幼儿吃东西，与矿产无关。"}], "explanations": {"掠夺": "正确：“掠夺”指用暴力夺取，与“外国公司”的行为相合，可以带“过”。", "养殖": "搭配：“养殖”的对象是动植物，矿产不能用“养殖”。", "种植": "搭配：“种植”用于农作物、树木，不能用于矿产。", "喂养": "语义：“喂养”指给动物或幼儿吃东西，与矿产无关。"}, "sentence_index": 6, "correct_answer": "掠夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他通过努力工作，掠夺了一笔钱。", "explanation": "这里应该用〈挣〉。“掠夺”指用暴力夺取，凭劳动得到钱不能用“掠夺”。"}, {"text": "工人掠夺了那台坏掉的电脑。", "explanation": "这里应该用〈修〉。“掠夺”指用暴力夺取，修理坏电脑不能用“掠夺”。"}, {"text": "他在银行掠夺了自己存的钱。", "explanation": "这里应该用〈取〉。「掠夺」指用暴力夺取别人的财物，取自己的存款不能用「掠夺」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "侵略者把这座城市的古董掠夺。", "corrected_sentence": "侵略者把这座城市的古董掠夺了。", "error_description": "“把”字句错误：“把”字句的动词后要有补语或“了”等成分，不能只说“把……掠夺”。正确的说法是“侵略者把这座城市的古董掠夺了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌人掠夺着了大量的粮食。", "corrected_sentence": "敌人掠夺了大量的粮食。", "error_description": "“着”与“了”不能同时用在同一个动词后面。应只保留“了”，说“掠夺了”，不能说“掠夺着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
