INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96943, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看到一些线索后，想一想后面会怎么样。", "primary_collocate": null, "pronunciation": "tuī cè", "ipa": "tʰweɪ˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "看天上的云，我推测今天会下雨。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从他的话里，我推测他明天会来。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家推测比赛明天会推迟。", "target_word": "推测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能推测故事后面会怎么样吗？", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我推测爸爸马上会回家。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看了我的计划，推测我会成功。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生推测病人明天就能醒来。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上车很多，我推测会堵车。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推测老板下个月会来。", "target_word": "推测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们推测这家店很快会关门。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推测了", "label": "体标"}, {"form": "推测过", "label": "体标"}, {"form": "推測", "label": "繁体"}], "register": "中性", "sense_fingerprint": "推测：动词，根据眼前线索猜想接下来会发生什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推测", "is_correct": true, "explanation": "正确：推测（tuī cè）指看到线索后猜想后面会怎么样。"}, {"text": "推迟", "is_correct": false, "explanation": "推迟（tuī chí）：cè 换成 chí，意思是把时间往后改。"}, {"text": "推辞", "is_correct": false, "explanation": "推辞（tuī cí）：cè 的韵母 è 换成 í，声调也不同，意思是拒绝接受。"}, {"text": "推车", "is_correct": false, "explanation": "推车（tuī chē）：cè 的声母 c 换成 ch，声调改为第一声，意思是用手推的车子。"}], "explanations": {"推测": "正确：推测（tuī cè）指看到线索后猜想后面会怎么样。", "推迟": "推迟（tuī chí）：cè 换成 chí，意思是把时间往后改。", "推辞": "推辞（tuī cí）：cè 的韵母 è 换成 í，声调也不同，意思是拒绝接受。", "推车": "推车（tuī chē）：cè 的声母 c 换成 ch，声调改为第一声，意思是用手推的车子。"}, "sentence_index": null, "correct_answer": "推测"}, "level_3": {"options": [{"text": "推测", "is_correct": true, "explanation": "正确：推测表示根据眼前的云这类线索猜想将来，与句子相符。"}, {"text": "决定", "is_correct": false, "explanation": "语义：“决定”是人对自己的行动作出选择，天气的变化无法由人决定。"}, {"text": "计算", "is_correct": false, "explanation": "搭配：“计算”的对象是数字或数量，不能接“今天会下雨”这样的小句。"}, {"text": "观察", "is_correct": false, "explanation": "配价：“观察”要带具体的事物作宾语，不能接“今天会下雨”这样的小句。"}], "explanations": {"推测": "正确：推测表示根据眼前的云这类线索猜想将来，与句子相符。", "决定": "语义：“决定”是人对自己的行动作出选择，天气的变化无法由人决定。", "计算": "搭配：“计算”的对象是数字或数量，不能接“今天会下雨”这样的小句。", "观察": "配价：“观察”要带具体的事物作宾语，不能接“今天会下雨”这样的小句。"}, "sentence_index": 0, "correct_answer": "推测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用卷尺推测桌子的长度。", "explanation": "这里应该用〈测量〉。推测是根据线索做猜想，量桌子的长度要用〈测量〉。"}, {"text": "爱迪生推测出了电灯。", "explanation": "这里应该用〈发明〉。推测只用于对情况的猜想，说人创造出电灯要用〈发明〉。"}, {"text": "理发师推测了他的头发。", "explanation": "这里应该用〈剪〉。推测是猜想，不能用于对头发进行修剪，应该用〈剪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推测", "is_correct": true, "explanation": "正确：推测表示根据病情这类线索判断病人将来的状况，与句子相符。"}, {"text": "命令", "is_correct": false, "explanation": "语义：醒来不是医生能下令让病人做的事，“命令”与句子的意思不符。"}, {"text": "检查", "is_correct": false, "explanation": "配价：“检查”的宾语是具体的人或物，不能接“病人明天就能醒来”这样的小句。"}, {"text": "责备", "is_correct": false, "explanation": "搭配：“责备”要说明被责备的人或行为，不能接“病人明天就能醒来”这样的小句。"}], "explanations": {"推测": "正确：推测表示根据病情这类线索判断病人将来的状况，与句子相符。", "命令": "语义：醒来不是医生能下令让病人做的事，“命令”与句子的意思不符。", "检查": "配价：“检查”的宾语是具体的人或物，不能接“病人明天就能醒来”这样的小句。", "责备": "搭配：“责备”要说明被责备的人或行为，不能接“病人明天就能醒来”这样的小句。"}, "sentence_index": 6, "correct_answer": "推测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她推测了一首歌。", "explanation": "这里应该用〈唱〉。推测是对情况的猜想，不能用来表示唱歌这种表演。"}, {"text": "工人推测了那台电脑。", "explanation": "这里应该用〈修理〉。推测只用于判断情况，不能用来描述修理机器的动作。"}, {"text": "妈妈推测了一锅粥。", "explanation": "这里应该用〈煮〉。推测不能用于做饭这类实际动作，应该用〈煮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我推测了对，今天果然下雨。", "corrected_sentence": "我推测对了，今天果然下雨。", "error_description": "错误：“推测了对”；正确：“推测对了”。结果补语“对”应紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我推测得了出结果。", "corrected_sentence": "我推测得出结果。", "error_description": "错误：“推测得了出结果”；正确：“推测得出结果”。可能补语“得出”之间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
