INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96944, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据已知情况，推断眼下或过去某件尚不清楚的事实。", "primary_collocate": null, "pronunciation": "tuī cè", "ipa": "tʰweɪ˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "科学家根据化石推测恐龙的大小。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察根据脚印推测小偷的身高。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这些数据可以推测，人口在增加。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以推测，这座桥已经很老了。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他根据树的年轮推测它的年龄。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古学家推测这个房子住过一位官员。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从信上的字，我推测写信的人是女的。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生根据检查结果推测病因。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师根据成绩推测哪个学生没复习。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家推测这幅画有三百年的历史。", "target_word": "推测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推测了", "label": "体标"}, {"form": "推测过", "label": "体标"}, {"form": "推測", "label": "繁体"}], "register": "中性", "sense_fingerprint": "推测：动词，依据已知的事实或数据推断现在或过去的未知情况，不指将来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推测", "is_correct": true, "explanation": "正确：推测（tuī cè）指根据已知情况推断未知的事情。"}, {"text": "推迟", "is_correct": false, "explanation": "推迟（tuī chí）：cè 换成 chí，意思是把时间往后改。"}, {"text": "推辞", "is_correct": false, "explanation": "推辞（tuī cí）：cè 的韵母 è 换成 í，声调也不同，意思是拒绝接受。"}, {"text": "推车", "is_correct": false, "explanation": "推车（tuī chē）：cè 的声母 c 换成 ch，声调改为第一声，意思是用手推的车子。"}], "explanations": {"推测": "正确：推测（tuī cè）指根据已知情况推断未知的事情。", "推迟": "推迟（tuī chí）：cè 换成 chí，意思是把时间往后改。", "推辞": "推辞（tuī cí）：cè 的韵母 è 换成 í，声调也不同，意思是拒绝接受。", "推车": "推车（tuī chē）：cè 的声母 c 换成 ch，声调改为第一声，意思是用手推的车子。"}, "sentence_index": null, "correct_answer": "推测"}, "level_3": {"options": [{"text": "推测", "is_correct": true, "explanation": "正确：推测用于根据化石这类证据推断恐龙的大小，与句子相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：祝贺是对喜事表示庆贺，不能用于“恐龙的大小”这样的量度。"}, {"text": "数", "is_correct": false, "explanation": "配价：“数”要接可以逐个计数的对象，不能接“恐龙的大小”这种抽象的量度。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能接“恐龙的大小”。"}], "explanations": {"推测": "正确：推测用于根据化石这类证据推断恐龙的大小，与句子相符。", "祝贺": "语义：祝贺是对喜事表示庆贺，不能用于“恐龙的大小”这样的量度。", "数": "配价：“数”要接可以逐个计数的对象，不能接“恐龙的大小”这种抽象的量度。", "批评": "搭配：“批评”的对象是人或行为，不能接“恐龙的大小”。"}, "sentence_index": 0, "correct_answer": "推测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用卷尺推测房间的宽度。", "explanation": "这里应该用〈测量〉。推测是根据已知情况做推断，量房间的宽度要用〈测量〉。"}, {"text": "他用力推测了门。", "explanation": "这里应该用〈推开〉。推测不能用于用力推动门这样的动作，应该用〈推开〉。"}, {"text": "他推测了一台新电脑。", "explanation": "这里应该用〈推销〉。推测不能用于卖东西，推销一台电脑要用〈推销〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推测", "is_correct": true, "explanation": "正确：推测表示根据字迹这类线索作出判断，与句子相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "配价：“欣赏”的宾语是作品或人的优点，不能接“写信的人是女的”这样的判断。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能用于“写信的人是女的”这样的事实。"}, {"text": "复印", "is_correct": false, "explanation": "语义：复印是复制文件，不能用来判断写信人的性别。"}], "explanations": {"推测": "正确：推测表示根据字迹这类线索作出判断，与句子相符。", "欣赏": "配价：“欣赏”的宾语是作品或人的优点，不能接“写信的人是女的”这样的判断。", "翻译": "搭配：“翻译”的对象是语言或文字，不能用于“写信的人是女的”这样的事实。", "复印": "语义：复印是复制文件，不能用来判断写信人的性别。"}, "sentence_index": 6, "correct_answer": "推测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推测了桌子。", "explanation": "这里应该用〈擦〉。推测是对情况的猜想，不能用于擦拭桌子这种实际动作。"}, {"text": "工人推测了那台洗衣机。", "explanation": "这里应该用〈修理〉。推测不能用于对机器进行实际修理，应该用〈修理〉。"}, {"text": "乐队推测了一首新曲子。", "explanation": "这里应该用〈演奏〉。推测是猜想，不能用于乐队演奏曲子这种表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们从这些数据推测了出了结论。", "corrected_sentence": "我们从这些数据推测出了结论。", "error_description": "错误：“推测了出了结论”；正确：“推测出了结论”。结果补语“出”必须紧跟动词，“了”应放在“出”之后，动词后不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你能推测来他的想法吗？", "corrected_sentence": "你能推测出他的想法吗？", "error_description": "补语错误：“推测”后接结果补语“出”（推测出），不能用“来”。正确说法是“你能推测出他的想法吗？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
