INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96945, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理城市和国家的办公地方。", "primary_collocate": null, "pronunciation": "zhèng fǔ jī guān", "ipa": "tʂɤŋ˥˩ fu˨˩˦ tɕi˥ kwan˥", "syllable_count": 4, "sentences": [{"text": "政府机关就在市中心，离火车站很近。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天要去政府机关办身份证。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机关门口站着两个保安。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上八点到政府机关上班。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座政府机关的大楼很高。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机关的院子里种着很多树。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿走到政府机关要二十分钟。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末政府机关不开门，明天再去吧。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机关里的办公室都很干净。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去政府机关怎么走？", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "政府机关：管理城市和国家的办公地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政府机关", "is_correct": true, "explanation": "“政府机关”是有固定位置的办公场所，可以“就在市中心”，离火车站近。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能说“就在市中心，离火车站很近”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气弥漫各处，不能用来说明离火车站的远近。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“就在市中心”说的是位置，时间不能有方位，不能这样描述。"}], "explanations": {"政府机关": "“政府机关”是有固定位置的办公场所，可以“就在市中心”，离火车站近。", "老虎": "语义：老虎是动物，不能说“就在市中心，离火车站很近”。", "空气": "语义：空气弥漫各处，不能用来说明离火车站的远近。", "时间": "搭配：“就在市中心”说的是位置，时间不能有方位，不能这样描述。"}, "sentence_index": 0, "correct_answer": "政府机关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座政府机关每天有几百吨钢铁从这里运出。", "explanation": "这里应该用〈钢铁厂〉。政府机关是办公场所，不生产钢铁；生产并运出几百吨钢铁的是〈钢铁厂〉。"}, {"text": "这家政府机关的急诊室昨晚接收了很多病人。", "explanation": "这里应该用〈医院〉。政府机关是办公场所，不设急诊室；接收病人的地方要用〈医院〉。"}, {"text": "我昨天在这家政府机关买了一本小说。", "explanation": "这里应该用〈书店〉。政府机关是办公场所，不卖书；买书要去〈书店〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政府机关", "is_correct": true, "explanation": "“政府机关”是可以到达的地点，“走到政府机关要二十分钟”说得通。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想是抽象概念，没有空间位置，不能作为步行的终点。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“走到……”要求一个地点，星期是时间，不能作终点。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是地点，走不到名字那里。"}], "explanations": {"政府机关": "“政府机关”是可以到达的地点，“走到政府机关要二十分钟”说得通。", "思想": "语义：思想是抽象概念，没有空间位置，不能作为步行的终点。", "星期": "搭配：“走到……”要求一个地点，星期是时间，不能作终点。", "名字": "语义：名字不是地点，走不到名字那里。"}, "sentence_index": 6, "correct_answer": "政府机关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家政府机关的车间每天生产一千台机器。", "explanation": "这里应该用〈工厂〉。政府机关不设生产车间，生产机器的地方要用〈工厂〉。"}, {"text": "这个政府机关每天都有很多孩子来玩过山车。", "explanation": "这里应该用〈游乐场〉。政府机关是办公场所，没有过山车；供孩子玩过山车的是〈游乐场〉。"}, {"text": "这家政府机关里养着几十只老虎，游客可以买票进去参观。", "explanation": "这里应该用〈动物园〉。政府机关不养动物，也不卖门票；供游客买票参观动物的是〈动物园〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只政府机关的大楼是去年建的。", "corrected_sentence": "那座政府机关的大楼是去年建的。", "error_description": "错误在量词：“政府机关”作为建筑时应用“座”，不能用“只”。正确形式为“那座政府机关的大楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天向政府机关上班。", "corrected_sentence": "我每天到政府机关上班。", "error_description": "介词错误：表示到达某处要用“到”，不能用“向”。“向”表示动作的方向，不能与“上班”搭配说成“向政府机关上班”。正确形式为“到政府机关上班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
