INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行使国家行政权力的机构。", "primary_collocate": null, "pronunciation": "zhèng fǔ jī guān", "ipa": "tʂɤŋ˥˩ fu˨˩˦ tɕi˥ kwan˥", "syllable_count": 4, "sentences": [{"text": "政府机关要依法办事，不能乱做决定。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政府机关负责管理全市的交通。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机关的工作人员要为人民服务。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个政府机关工作了十年。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个政府机关都要公开自己的预算。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机关做出的决定，大家都要遵守。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些政府机关一起发出了通知。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机关应该听取老百姓的意见。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里的几个政府机关合作解决了问题。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机关不能随便收老百姓的钱。", "target_word": "政府机关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "政府机关：行使国家行政权力的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政府机关", "is_correct": true, "explanation": "“政府机关”是能依法办事、做决定的国家机构，符合句中的主语。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“依法办事”“做决定”要求有行为能力的主体，石头不能充当主语。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是自然现象，既不能依法办事，也不会做决定。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水没有主观意志，无法依法办事，句子说不通。"}], "explanations": {"政府机关": "“政府机关”是能依法办事、做决定的国家机构，符合句中的主语。", "石头": "配价：“依法办事”“做决定”要求有行为能力的主体，石头不能充当主语。", "彩虹": "语义：彩虹是自然现象，既不能依法办事，也不会做决定。", "雨水": "语义：雨水没有主观意志，无法依法办事，句子说不通。"}, "sentence_index": 0, "correct_answer": "政府机关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家政府机关每天接诊三百多名病人。", "explanation": "这里应该用〈医院〉。政府机关是行使国家行政权力的机构，不接诊病人；接诊病人的是〈医院〉。"}, {"text": "这所政府机关每年招收三千名新生。", "explanation": "这里应该用〈学校〉。政府机关是行使国家行政权力的机构，不招收新生；招收新生是〈学校〉的职能，“政府机关”不能用来指学校。"}, {"text": "这家政府机关每天卖出几百张电影票。", "explanation": "这里应该用〈电影院〉。政府机关是行使国家行政权力的机构，不卖电影票；卖电影票的是〈电影院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政府机关", "is_correct": true, "explanation": "“政府机关”能发布通知，符合句中“一起发出了通知”的主语。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不会发出通知，这里需要有发布权的机构。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，无法发出通知。"}, {"text": "墙壁", "is_correct": false, "explanation": "配价：“发出通知”要求有发布权的主体，墙壁不能充当发布者。"}], "explanations": {"政府机关": "“政府机关”能发布通知，符合句中“一起发出了通知”的主语。", "花朵": "语义：花朵不会发出通知，这里需要有发布权的机构。", "雨伞": "语义：雨伞是日用品，无法发出通知。", "墙壁": "配价：“发出通知”要求有发布权的主体，墙壁不能充当发布者。"}, "sentence_index": 6, "correct_answer": "政府机关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家政府机关去年的利润翻了一番。", "explanation": "这里应该用〈企业〉。政府机关不以营利为目的，不能用来说利润增长；盈利的经营单位要用〈企业〉。"}, {"text": "这家政府机关每年都向股东分红。", "explanation": "这里应该用〈公司〉。政府机关没有股东，也不分红；向股东分红是〈公司〉的事。"}, {"text": "这家政府机关每天生产一万件衣服。", "explanation": "这里应该用〈工厂〉。政府机关是办公机构，不进行生产；生产产品的地方要用〈工厂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只政府机关负责管理全市的税收。", "corrected_sentence": "一个政府机关负责管理全市的税收。", "error_description": "错误在量词：“政府机关”指机构，应用“个”，不能用“只”（“只”多用于动物）。正确形式为“一个政府机关”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她政府机关工作过五年。", "corrected_sentence": "她在政府机关工作过五年。", "error_description": "错误在介词：表示在某处工作，“政府机关”前需要加“在”，应说“在政府机关工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
