INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96947, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96947, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门负责告诉大家新消息的办公室。", "primary_collocate": null, "pronunciation": "xīn wén chù", "ipa": "ɕin˥ wən˧˥ tʂʰu˥˩", "syllable_count": 3, "sentences": [{"text": "新闻处在三楼，你去那里问吧。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去新闻处拿今天的消息。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻处的人每天都很忙。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在新闻处门口等了一个小时。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻处的电话一直在响。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的新闻处今天发了一条消息。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些照片交给新闻处。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻处的房间很小，但是人很多。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想知道比赛结果，可以问新闻处。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻处的老王给大家讲了这件事。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "专门向大家发布新消息的办公室", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新闻处", "is_correct": true, "explanation": "“新闻处”是专门负责发布消息的办公室，可以作为去问信息的地方，符合句意。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”不是可以去问信息的机构，“鸡蛋在三楼，你去那里问吧”句意不通。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能在三楼，也不能去那里问。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“去那里问”问的应是信息或事务，不说“问咖啡”。"}], "explanations": {"新闻处": "“新闻处”是专门负责发布消息的办公室，可以作为去问信息的地方，符合句意。", "鸡蛋": "语义：“鸡蛋”不是可以去问信息的机构，“鸡蛋在三楼，你去那里问吧”句意不通。", "春天": "语义：“春天”是季节，不能在三楼，也不能去那里问。", "咖啡": "搭配：“去那里问”问的应是信息或事务，不说“问咖啡”。"}, "sentence_index": 0, "correct_answer": "新闻处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天在新闻处里上数学课。", "explanation": "这里应该用〈教室〉。新闻处是发布消息的办公室，不是上课的地方；上课应在教室。"}, {"text": "学生不舒服可以去新闻处看病。", "explanation": "这里应该用〈医务室〉。新闻处是发布消息的部门，不负责看病；学生不舒服应去医务室。"}, {"text": "他是一个新闻处，负责采访。", "explanation": "这里应该用〈记者〉。新闻处是机构，不是人；说“他是一个……”后应接人，如记者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新闻处", "is_correct": true, "explanation": "“新闻处”是机关里负责发布消息的部门，可以接收照片，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是自然景象，不能接收照片，句意不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”是家具，不能接收照片，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“交给”后的接收者须是人或机构，“空气”无法接收照片。"}], "explanations": {"新闻处": "“新闻处”是机关里负责发布消息的部门，可以接收照片，符合句意。", "天空": "语义：“天空”是自然景象，不能接收照片，句意不通。", "沙发": "语义：“沙发”是家具，不能接收照片，句意不通。", "空气": "搭配：“交给”后的接收者须是人或机构，“空气”无法接收照片。"}, "sentence_index": 6, "correct_answer": "新闻处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条新闻处很有意思，大家都在看。", "explanation": "这里应该用〈消息〉。“新闻处”是机构，不是一条消息；“这条消息”才指消息本身。"}, {"text": "这家新闻处每天接待几千名病人。", "explanation": "这里应该用〈医院〉。新闻处是发布消息的部门，不接待病人，接待病人是医院的工作。"}, {"text": "我每天早上都看新闻处。", "explanation": "这里应该用〈报纸〉。“看”的对象应是报纸之类的读物，新闻处是机构，不能被看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多学生新闻处门口排队。", "corrected_sentence": "很多学生在新闻处门口排队。", "error_description": "“新闻处”作地点时前面要加介词“在”，应说“在新闻处门口排队”，句中漏了“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新闻处们的几位工作人员正在准备发布会。", "corrected_sentence": "新闻处的几位工作人员正在准备发布会。", "error_description": "“新闻处”是机构名词，一般不加“们”表复数；应说“新闻处的几位工作人员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96948, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
