INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关内专门负责新闻发布和宣传的部门。", "primary_collocate": null, "pronunciation": "xīn wén chù", "ipa": "ɕin˥ wən˧˥ tʂʰu˥˩", "syllable_count": 3, "sentences": [{"text": "市政府新闻处今天发布了通知。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在外交部新闻处做宣传工作。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻处负责向记者发布政府的消息。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使馆的新闻处请记者来开会。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻处的工作是发布消息和做宣传。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后进了省政府新闻处。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门的新闻处写了一份宣传材料。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻处的同事正在准备明天的发布会。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局新闻处告诉大家，案子已经破了。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的新闻处会把重要的消息发给报社。", "target_word": "新闻处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "机关里负责发布新闻和做宣传的部门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新闻处", "is_correct": true, "explanation": "“新闻处”是机关内负责发布消息的部门，市政府的这个部门发布通知，符合句意。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“公园”是场所，不会发布通知，“市政府公园今天发布了通知”句意不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然景物，不能发布通知，句意不通。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“发布通知”的主语应是机关单位，不能说花朵发布通知。"}], "explanations": {"新闻处": "“新闻处”是机关内负责发布消息的部门，市政府的这个部门发布通知，符合句意。", "公园": "语义：“公园”是场所，不会发布通知，“市政府公园今天发布了通知”句意不通。", "河流": "语义：“河流”是自然景物，不能发布通知，句意不通。", "花朵": "搭配：“发布通知”的主语应是机关单位，不能说花朵发布通知。"}, "sentence_index": 0, "correct_answer": "新闻处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新闻处负责发工资和报销。", "explanation": "这里应该用〈财务处〉。新闻处负责发布消息和宣传，发工资和报销是财务处的工作。"}, {"text": "她是我们学校的新闻处。", "explanation": "这里应该用〈记者〉。新闻处是机构，不能说“她是……新闻处”，指人要说记者。"}, {"text": "学生中午可以去新闻处吃饭。", "explanation": "这里应该用〈食堂〉。新闻处是机关部门，不供应饭菜；学生吃饭应去食堂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新闻处", "is_correct": true, "explanation": "“新闻处”是机关里负责发布消息和宣传的部门，能写宣传材料，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“写宣传材料”的主体应是能执笔的机构或人，不能说花园写材料。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：“厕所”是场所，不能写宣传材料，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能写宣传材料，句意不通。"}], "explanations": {"新闻处": "“新闻处”是机关里负责发布消息和宣传的部门，能写宣传材料，符合句意。", "花园": "搭配：“写宣传材料”的主体应是能执笔的机构或人，不能说花园写材料。", "厕所": "语义：“厕所”是场所，不能写宣传材料，句意不通。", "天气": "语义：“天气”是自然现象，不能写宣传材料，句意不通。"}, "sentence_index": 6, "correct_answer": "新闻处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条新闻处很重要，要马上发给报社。", "explanation": "这里应该用〈消息〉。“新闻处”是部门，不能当作一条消息；“这条消息”才指一条新闻，可以发给报社。"}, {"text": "这家新闻处每天接待几百名病人。", "explanation": "这里应该用〈医院〉。新闻处是机关部门，不接待病人，接待病人是医院的工作。"}, {"text": "这家新闻处每天营业到晚上十点。", "explanation": "这里应该用〈商店〉。“营业”用于商店等经营场所，新闻处是机关部门，不说营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新闻处们的工作人员都很认真负责。", "corrected_sentence": "新闻处的工作人员都很认真负责。", "error_description": "“新闻处”是机构名词，一般不加“们”表复数；应说“新闻处的工作人员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她省政府新闻处工作了三年。", "corrected_sentence": "她在省政府新闻处工作了三年。", "error_description": "表示地点的“在”不能省，应说“在省政府新闻处工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，都表示对事物产生的影响方向。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”表示互相交换意见，与“有利于”的好处或坏处没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”表示深入探讨，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，都表示对事物产生的影响方向。", "参加": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。", "讨论": "“讨论”表示互相交换意见，与“有利于”的好处或坏处没有反义关系。", "研究": "“研究”表示深入探讨，与“有利于”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，表示对事物产生坏的影响。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”表示仔细看，与“有利于”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，表示对事物产生坏的影响。", "散步": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。", "观察": "“观察”表示仔细看，与“有利于”没有反义关系。", "旅行": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对某件事有好处。", "primary_collocate": null, "pronunciation": "yǒu lì yú", "ipa": "joʊ˨˩˦ li˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "早睡早起有利于身体健康。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多喝水有利于皮肤。", "target_word": "有利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "运动有利于我们的身体。", "target_word": "有利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多读书有利于提高写作水平。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的睡眠有利于学习。", "target_word": "有利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃早饭有利于一天的工作。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "安静的环境有利于孩子写作业。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多笑笑有利于身体和心情。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天散步有利于睡个好觉。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跟朋友聊天有利于放松心情。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对身体、学习、生活等某方面有好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“有利于身体健康”是常用搭配，表示对身体有好处。"}, {"text": "有害于", "is_correct": false, "explanation": "语义：“有害”与“有利”意思相反，句子会变成早睡早起对身体有害，与句意相悖。"}, {"text": "损害", "is_correct": false, "explanation": "语义：“损害”指使受到损伤，与“早睡早起”这一好习惯的语境相反，不合句意。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量，不能说“增加身体健康”。"}], "explanations": {"有利于": "正确。“有利于身体健康”是常用搭配，表示对身体有好处。", "有害于": "语义：“有害”与“有利”意思相反，句子会变成早睡早起对身体有害，与句意相悖。", "损害": "语义：“损害”指使受到损伤，与“早睡早起”这一好习惯的语境相反，不合句意。", "增加": "搭配：“增加”说的是数量，不能说“增加身体健康”。"}, "sentence_index": 0, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有利于这个方案。", "explanation": "这里应该用〈赞成〉。“有利于”表示对事情有好处，不表示同意或支持某个方案；表示同意要说“赞成”。"}, {"text": "我们要有利于这次机会。", "explanation": "这里应该用〈利用〉。“有利于”表示对事物有好处，不能表示把机会用来做事；把机会用上要说“利用”。"}, {"text": "我很有利于你的帮助。", "explanation": "这里应该用〈感谢〉。“有利于”表示对事情有好处，主语不能是表达谢意的人；表示谢意要说“感谢你的帮助”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“安静的环境有利于孩子写作业”表示安静对写作业有好处。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”表示妨碍，与“安静的环境”这一有利条件相反，句子会显得矛盾。"}, {"text": "增添", "is_correct": false, "explanation": "搭配：“增添”后面接的是乐趣、色彩等，不能直接接“孩子写作业”。"}, {"text": "拖累", "is_correct": false, "explanation": "语义：“拖累”指使人受牵累，与“安静”这一有利条件相反，不合句意。"}], "explanations": {"有利于": "正确。“安静的环境有利于孩子写作业”表示安静对写作业有好处。", "阻碍": "语义：“阻碍”表示妨碍，与“安静的环境”这一有利条件相反，句子会显得矛盾。", "增添": "搭配：“增添”后面接的是乐趣、色彩等，不能直接接“孩子写作业”。", "拖累": "语义：“拖累”指使人受牵累，与“安静”这一有利条件相反，不合句意。"}, "sentence_index": 6, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在有利于一张地图。", "explanation": "这里应该用〈画〉。“有利于”表示对事物有好处，不能表示动手绘制；画地图要说“画”。"}, {"text": "我正在有利于答案。", "explanation": "这里应该用〈寻找〉。“有利于”表示对事情有好处，不能表示去找东西；“寻找答案”才是这里要表达的意思。"}, {"text": "这家工厂有利于大量废气。", "explanation": "这里应该用〈产生〉。“有利于”表示对事情有好处，不能表示产生某种东西；“产生大量废气”才是这里要表达的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样锻炼有利于了健康。", "corrected_sentence": "这样锻炼有利于健康。", "error_description": "错误：“有利于”和宾语“健康”之间多了“了”。正确形式是“这样锻炼有利于健康。”“了”不能插在“有利于”与宾语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "安静的书房有利于对孩子专心学习。", "corrected_sentence": "安静的书房有利于孩子专心学习。", "error_description": "错误：“有利于”后面多加了介词“对”。正确形式是“有利于孩子专心学习”，“有利于”后直接接宾语，不需要“对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，表示对事物的发展起阻碍作用。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”表示互相交换意见，与“有利于”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”表示深入探讨，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，表示对事物的发展起阻碍作用。", "参加": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。", "讨论": "“讨论”表示互相交换意见，与“有利于”没有反义关系。", "研究": "“研究”表示深入探讨，与“有利于”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，表示对事物产生阻碍作用。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”表示仔细看，与“有利于”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，表示对事物产生阻碍作用。", "散步": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。", "观察": "“观察”表示仔细看，与“有利于”没有反义关系。", "旅行": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对某事物有好处，起促进作用。", "primary_collocate": null, "pronunciation": "yǒu lì yú", "ipa": "joʊ˨˩˦ li˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "这项政策有利于经济发展。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的交通规划有利于城市发展。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和平有利于各国的合作。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "减少污染有利于保护环境。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公平的竞争有利于市场发展。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做有利于团队合作。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "良好的教育有利于社会进步。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开放的政策有利于吸引更多游客。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多种树有利于改善空气质量。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "互相理解有利于解决问题。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对发展、进步等事物起促进作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“有利于经济发展”表示对经济的发展起促进作用。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量，不能说“增加经济发展”。"}, {"text": "休息", "is_correct": false, "explanation": "语法：“休息”是不及物动词，后面不能带宾语，不能说“休息经济发展”。"}, {"text": "毕业", "is_correct": false, "explanation": "语法：“毕业”不带宾语，主语也应该是人，“政策毕业经济发展”不成立。"}], "explanations": {"有利于": "正确。“有利于经济发展”表示对经济的发展起促进作用。", "增加": "搭配：“增加”说的是数量，不能说“增加经济发展”。", "休息": "语法：“休息”是不及物动词，后面不能带宾语，不能说“休息经济发展”。", "毕业": "语法：“毕业”不带宾语，主语也应该是人，“政策毕业经济发展”不成立。"}, "sentence_index": 0, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有利于这项政策。", "explanation": "这里应该用〈赞成〉。“有利于”表示对事情有好处，不表示同意或支持某项政策；表示同意要说“赞成”。"}, {"text": "我们要有利于这些资源。", "explanation": "这里应该用〈利用〉。“有利于”表示对事物有好处，不能表示把资源用起来；这里应说“利用”。"}, {"text": "孩子们在有利于房间。", "explanation": "这里应该用〈打扫〉。“有利于”表示对事情有好处，不能表示动手清理房间；这里应说“打扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“良好的教育有利于社会进步”表示教育对社会的进步起促进作用。"}, {"text": "增添", "is_correct": false, "explanation": "搭配：“增添”后面接的是乐趣、色彩等，不能说“增添社会进步”。"}, {"text": "出发", "is_correct": false, "explanation": "语法：“出发”是不及物动词，不能说“出发社会进步”。"}, {"text": "削弱", "is_correct": false, "explanation": "语义：“削弱”表示使力量变弱，与“良好的教育”促进进步的作用相反，句子矛盾。"}], "explanations": {"有利于": "正确。“良好的教育有利于社会进步”表示教育对社会的进步起促进作用。", "增添": "搭配：“增添”后面接的是乐趣、色彩等，不能说“增添社会进步”。", "出发": "语法：“出发”是不及物动词，不能说“出发社会进步”。", "削弱": "语义：“削弱”表示使力量变弱，与“良好的教育”促进进步的作用相反，句子矛盾。"}, "sentence_index": 6, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "互相理解之后，我们有利于一顿晚饭。", "explanation": "这里应该用〈做〉。“有利于”表示对事物有好处，不能表示动手做饭；做饭要说“做”。"}, {"text": "互相理解之后，我们有利于一首歌。", "explanation": "这里应该用〈唱〉。“有利于”表示对事物有好处，不能表示演唱；唱歌要说“唱”。"}, {"text": "互相理解之后，我们有利于一封信。", "explanation": "这里应该用〈写〉。“有利于”表示对事物有好处，不能表示动笔；写信要说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项政策有利于了经济增长。", "corrected_sentence": "这项政策有利于经济增长。", "error_description": "错误：“有利于”和宾语“经济增长”之间多了“了”。正确形式是“这项政策有利于经济增长。”“了”不能插在“有利于”与宾语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "良好的教育有利于的人才培养。", "corrected_sentence": "良好的教育有利于人才培养。", "error_description": "错误：“有利于”和宾语“人才培养”之间多了“的”。“有利于”是动词，后面直接接宾语，应说“良好的教育有利于人才培养。”“的”不能插在它和宾语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
