INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96951, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "样子很好看、很有风格。", "primary_collocate": null, "pronunciation": "yǒu xíng", "ipa": "joʊ̯²¹⁴ ɕiŋ³⁵", "syllable_count": 2, "sentences": [{"text": "他今天穿得很有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件黑外套真有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你剪了新发型，看起来很有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男生走路的样子很有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她戴着帽子，显得特别有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双皮鞋又好看又有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天的衣服很有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这辆红色的车很有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上西服以后更有型了。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的衣服都很有型。", "target_word": "有型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很有型", "label": "程度搭配"}, {"form": "有型的", "label": "的字结构"}], "register": "口语", "sense_fingerprint": "穿着打扮好看、有个人风格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有型", "is_correct": true, "explanation": "正确。“有型”形容穿着好看、有风格，与句意相符。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”形容情绪，不能用来形容穿着。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指身体需要吃东西，与穿着无关。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容头脑，不说“穿得很聪明”。"}], "explanations": {"有型": "正确。“有型”形容穿着好看、有风格，与句意相符。", "生气": "语义：“生气”形容情绪，不能用来形容穿着。", "饿": "语义：“饿”指身体需要吃东西，与穿着无关。", "聪明": "搭配：“聪明”形容头脑，不说“穿得很聪明”。"}, "sentence_index": 0, "correct_answer": "有型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次数学考试他考得很有型。", "explanation": "这里应用〈好〉。〈有型〉形容外形或风格，不用来评价考试成绩。"}, {"text": "这道菜的味道很有型。", "explanation": "这里应用〈好吃〉。〈有型〉指外观和风格，不指味道。"}, {"text": "他总是很有型地迟到。", "explanation": "这里误把〈有型〉当成修饰行为的状语。〈有型〉只形容外形或风格，不能修饰迟到这类行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有型", "is_correct": true, "explanation": "正确。“有型”形容衣服样式好看、有风格，与句意相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，不能用来形容衣服。"}, {"text": "难过", "is_correct": false, "explanation": "语义：“难过”形容心情，与衣服无关。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”形容人的性格或状态，不能用来形容衣服。"}], "explanations": {"有型": "正确。“有型”形容衣服样式好看、有风格，与句意相符。", "高兴": "语义：“高兴”形容人的心情，不能用来形容衣服。", "难过": "语义：“难过”形容心情，与衣服无关。", "懒": "语义：“懒”形容人的性格或状态，不能用来形容衣服。"}, "sentence_index": 6, "correct_answer": "有型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次搬家很有型。", "explanation": "这里应用〈顺利〉。〈有型〉不用来形容事情的过程。"}, {"text": "这个城市的天气很有型。", "explanation": "这里应用〈好〉。〈有型〉不用来描述天气。"}, {"text": "这道题他答得很有型。", "explanation": "这里应用〈对〉。〈有型〉不用来评价解题的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的发型很的有型。", "corrected_sentence": "她的发型很有型。", "error_description": "错误：“很”后面多加了“的”。“很”修饰形容词“有型”时直接放在前面，不加“的”，正确形式是“很有型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条裙子很很有型。", "corrected_sentence": "这条裙子很有型。", "error_description": "错误：程度副词“很”重复使用。“很有型”只需一个“很”，正确形式是“这条裙子很有型”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
