INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96953, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "穿在身上的衣服和戴的东西。", "primary_collocate": null, "pronunciation": "fú shì", "ipa": "fu˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "她今天的服饰很得体，大家都夸她。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员的服饰要和角色的身份一致。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的服饰很简单，只有白衬衫和牛仔裤。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加面试时，服饰要干净整齐。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们换上了新服饰，高兴地跳起来。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的服饰要轻薄凉快。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的服饰很特别，围巾和帽子都是自己做的。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求学生的服饰简单大方。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个节日里，人们穿着漂亮的服饰去游行。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出时，每个人的服饰都不一样。", "target_word": "服饰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服飾", "label": "繁体"}, {"form": "服饰店", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人身上穿戴的衣服和饰物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b8aedc-5ff5-4137-89ea-9c5261b723e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96953, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "服饰", "is_correct": true, "explanation": "正确：服饰（fú shì）指穿在身上的衣服和戴的东西。"}, {"text": "佛事", "is_correct": false, "explanation": "fó（第二声）与 fú（第二声）韵母不同（o 与 u），意思是佛教的仪式活动。"}, {"text": "复式", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是复合、多层的形式。"}, {"text": "辅食", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）、shí（第二声）与 shì（第四声）声调都不同，意思是辅助性的食物。"}], "explanations": {"服饰": "正确：服饰（fú shì）指穿在身上的衣服和戴的东西。", "佛事": "fó（第二声）与 fú（第二声）韵母不同（o 与 u），意思是佛教的仪式活动。", "复式": "fù（第四声）与 fú（第二声）声调不同，意思是复合、多层的形式。", "辅食": "fǔ（第三声）与 fú（第二声）、shí（第二声）与 shì（第四声）声调都不同，意思是辅助性的食物。"}, "sentence_index": null, "correct_answer": "服饰"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“得体”形容人的穿着或言行，不能用来形容天气。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“得体”形容穿着或举止，与成绩的好坏不相关。"}, {"text": "服饰", "is_correct": true, "explanation": "正确：“服饰很得体”指穿着得体，与“大家都夸她”相符。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“得体”不能形容饭菜，饭菜通常说“可口”。"}], "explanations": {"天气": "搭配：“得体”形容人的穿着或言行，不能用来形容天气。", "成绩": "语义：“得体”形容穿着或举止，与成绩的好坏不相关。", "服饰": "正确：“服饰很得体”指穿着得体，与“大家都夸她”相符。", "饭菜": "搭配：“得体”不能形容饭菜，饭菜通常说“可口”。"}, "sentence_index": 0, "correct_answer": "服饰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演员换了一条服饰，准备上台。", "explanation": "这里应该用〈套〉。“条”用于裤子、项链等单件物品，“服饰”是总称，不能用“条”计量。"}, {"text": "参加面试前，我先去服饰买了一件衬衫。", "explanation": "这里应该用〈服饰店〉。“服饰”指衣饰，不指商店。"}, {"text": "参加面试前，他把服饰擦得很亮。", "explanation": "这里应该用〈皮鞋〉。“擦得很亮”用于鞋子，“服饰”是衣饰，不能擦得发亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发动机", "is_correct": false, "explanation": "语义：发动机与“围巾和帽子都是自己做的”这一说法没有联系。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是穿戴的物品，与后文围巾、帽子的语境不符。"}, {"text": "服饰", "is_correct": true, "explanation": "正确：“服饰很特别”，后文的围巾和帽子与穿着相符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“很特别”一般不用来形容工资，这里也与后文的穿戴无关。"}], "explanations": {"发动机": "语义：发动机与“围巾和帽子都是自己做的”这一说法没有联系。", "乐器": "语义：乐器不是穿戴的物品，与后文围巾、帽子的语境不符。", "服饰": "正确：“服饰很特别”，后文的围巾和帽子与穿着相符。", "工资": "搭配：“很特别”一般不用来形容工资，这里也与后文的穿戴无关。"}, "sentence_index": 6, "correct_answer": "服饰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演出时，每个人的服饰都在大声唱歌。", "explanation": "这里应该用〈演员〉。“服饰”是穿戴的东西，不会唱歌。"}, {"text": "演出时，大家的服饰都很好吃。", "explanation": "这里误把“服饰”当成食物。服饰是衣饰，应说〈好看〉，不能用“好吃”形容。"}, {"text": "演出时，他的服饰很准确。", "explanation": "这里误把“服饰”当成报道或信息。“准确”用于信息、数据，服饰是衣饰，应说〈得体〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这次换了一条新服饰。", "corrected_sentence": "他这次换了一套新服饰。", "error_description": "“服饰”前的量词应用“套”，“条”用于裤子、项链等单件物品，这里误用，应改为“一套新服饰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演出时，大家的服饰们都很漂亮。", "corrected_sentence": "演出时，大家的服饰都很漂亮。", "error_description": "“服饰”是不可数的总称，不能加后缀“们”。应去掉“们”，写成“演出时，大家的服饰都很漂亮。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
