INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96955, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在做完自己的工作以后，空闲的时候做的。", "primary_collocate": null, "pronunciation": "yè yú", "ipa": "jɛ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "我的业余时间都用来看书。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的业余爱好是打篮球。", "target_word": "业余", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "业余时间，我喜欢去公园跑步。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下班以后，她在业余时间学画画。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他利用业余时间学会了做饭。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很珍惜自己的业余生活。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸业余时间常常陪我下棋。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末是我最重要的业余时间，因为不用上班。", "target_word": "业余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的业余生活很丰富，常常爬山、游泳。", "target_word": "业余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了多陪孩子，他把业余时间都留给了家人。", "target_word": "业余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "业余时间", "label": "复合"}, {"form": "业余爱好", "label": "复合"}, {"form": "業餘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作之外的空闲时间里做的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96955, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "业余", "is_correct": true, "explanation": "正确：业余，yè yú，指工作之外的空闲时间。"}, {"text": "鳄鱼", "is_correct": false, "explanation": "è yú，第一个音节没有 y 声母（è 与 yè 相近），yú 相同，意思是一种爬行动物。"}, {"text": "夜雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是夜里下的雨。"}, {"text": "月余", "is_correct": false, "explanation": "yuè 比 yè 多一个 u 介音，yú 相同，意思是一个多月。"}], "explanations": {"业余": "正确：业余，yè yú，指工作之外的空闲时间。", "鳄鱼": "è yú，第一个音节没有 y 声母（è 与 yè 相近），yú 相同，意思是一种爬行动物。", "夜雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是夜里下的雨。", "月余": "yuè 比 yè 多一个 u 介音，yú 相同，意思是一个多月。"}, "sentence_index": null, "correct_answer": "业余"}, "level_3": {"options": [{"text": "业余", "is_correct": true, "explanation": "正确：业余时间指工作之外的空闲时间，与“都用来看书”相符。"}, {"text": "专业", "is_correct": false, "explanation": "搭配：“专业时间”不成搭配，专业指职业领域。"}, {"text": "正式", "is_correct": false, "explanation": "语义：“正式时间”指规定的办公时段，与自由读书的句意不符。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”描述状态，与“都用来看书”的悠闲语境矛盾。"}], "explanations": {"业余": "正确：业余时间指工作之外的空闲时间，与“都用来看书”相符。", "专业": "搭配：“专业时间”不成搭配，专业指职业领域。", "正式": "语义：“正式时间”指规定的办公时段，与自由读书的句意不符。", "紧张": "语义：“紧张”描述状态，与“都用来看书”的悠闲语境矛盾。"}, "sentence_index": 0, "correct_answer": "业余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天的业余时间都在医院坐班，负责门诊。", "explanation": "〈业余〉指工作之外的空闲时间，坐班、负责门诊属于工作，与“业余”的空闲义矛盾。"}, {"text": "下班以后，她在业余时间上班。", "explanation": "〈业余〉指工作之外的空闲时间，上班属于工作时间，“在业余时间上班”自相矛盾。"}, {"text": "她的业余生活是在公司开会。", "explanation": "〈业余〉指工作之外的时间，在公司开会属于工作，不能算作业余生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "业余", "is_correct": true, "explanation": "正确：业余时间指工作之外的空闲时间，与“常常陪我下棋”相符。"}, {"text": "繁忙", "is_correct": false, "explanation": "语义：繁忙的时间与“常常陪我下棋”的句意相矛盾。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容人的态度或气氛，不能修饰“时间”，“严肃时间”不成话。"}, {"text": "专职", "is_correct": false, "explanation": "搭配：“专职时间”不成搭配，专职指固定的工作岗位。"}], "explanations": {"业余": "正确：业余时间指工作之外的空闲时间，与“常常陪我下棋”相符。", "繁忙": "语义：繁忙的时间与“常常陪我下棋”的句意相矛盾。", "严肃": "语义：“严肃”形容人的态度或气氛，不能修饰“时间”，“严肃时间”不成话。", "专职": "搭配：“专职时间”不成搭配，专职指固定的工作岗位。"}, "sentence_index": 6, "correct_answer": "业余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周一到周五的业余时间是早上八点到下午五点，必须准时到岗。", "explanation": "〈业余〉指工作之外的空闲时间，八点到五点、必须到岗的时段是工作时间，与“业余”矛盾。"}, {"text": "他把业余时间都留给了单位，每天晚上都不回家。", "explanation": "〈业余〉指工作之外的时间，留给单位的时间属于工作，与“业余”矛盾。"}, {"text": "他的业余时间都在工厂车间加班。", "explanation": "〈业余〉指工作之外的时间，车间加班属于工作时间，句意自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总把业余时间练习书法。", "corrected_sentence": "他总在业余时间练习书法。", "error_description": "“把”字句的动词须能处置宾语（如“用”），“练习”不能直接带“把”宾语；应说“他总在业余时间练习书法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被业余时间留给了孩子。", "corrected_sentence": "她把业余时间留给了孩子。", "error_description": "“被”字句中“业余时间”不能作施事，“她”也不能被“业余时间”留给；应改用“把”字句：“她把业余时间留给了孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96956, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专业", "is_correct": true, "explanation": "正确：“业余”在“不是专业的”义项下与“专业”互为反义。"}, {"text": "明亮", "is_correct": false, "explanation": "与“业余”无反义关系，“明亮”形容光线或颜色。"}, {"text": "柔软", "is_correct": false, "explanation": "与“业余”无反义关系，“柔软”形容质地。"}, {"text": "清楚", "is_correct": false, "explanation": "与“业余”无反义关系，“清楚”形容清晰程度。"}], "correct_answer": "专业", "explanations": {"专业": "正确：“业余”在“不是专业的”义项下与“专业”互为反义。", "明亮": "与“业余”无反义关系，“明亮”形容光线或颜色。", "柔软": "与“业余”无反义关系，“柔软”形容质地。", "清楚": "与“业余”无反义关系，“清楚”形容清晰程度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
