INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96956, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非专业的，只是爱好者水平的。", "primary_collocate": null, "pronunciation": "yè yú", "ipa": "jɛ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "他是业余歌手，不是专业的。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支业余足球队常常赢专业球队。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她只是业余画家，平时在银行工作。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的钢琴弹得很业余，没有专业老师教过。", "target_word": "业余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一场业余比赛，选手都不是职业运动员。", "target_word": "业余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是业余爱好者，不敢说很懂。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的摄影水平是业余的，但是照片很好看。", "target_word": "业余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业余选手也可以参加这次比赛。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他虽然是业余演员，演得却像专业的一样。", "target_word": "业余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个业余乐队的成员都没受过专业训练，只给朋友们演出。", "target_word": "业余", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "业余选手", "label": "复合"}, {"form": "业余爱好者", "label": "复合"}, {"form": "業餘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不是专业的，只是爱好者水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96956, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "业余", "is_correct": true, "explanation": "正确：业余，yè yú，指非专业的、水平只是爱好者的。"}, {"text": "鳄鱼", "is_correct": false, "explanation": "è yú，第一个音节没有 y 声母（è 与 yè 相近），yú 相同，意思是一种爬行动物。"}, {"text": "夜雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是夜里下的雨。"}, {"text": "月余", "is_correct": false, "explanation": "yuè 比 yè 多一个 u 介音，yú 相同，意思是一个多月。"}], "explanations": {"业余": "正确：业余，yè yú，指非专业的、水平只是爱好者的。", "鳄鱼": "è yú，第一个音节没有 y 声母（è 与 yè 相近），yú 相同，意思是一种爬行动物。", "夜雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是夜里下的雨。", "月余": "yuè 比 yè 多一个 u 介音，yú 相同，意思是一个多月。"}, "sentence_index": null, "correct_answer": "业余"}, "level_3": {"options": [{"text": "业余", "is_correct": true, "explanation": "正确：业余歌手指非专业水平，与“不是专业的”一致。"}, {"text": "正式", "is_correct": false, "explanation": "语义：“正式”不表示非专业水平，与后文“不是专业的”不相呼应。"}, {"text": "资深", "is_correct": false, "explanation": "语义：“资深”指经验丰富的专业人士，与“不是专业的”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述外形，不用来修饰职业身份，句意不通。"}], "explanations": {"业余": "正确：业余歌手指非专业水平，与“不是专业的”一致。", "正式": "语义：“正式”不表示非专业水平，与后文“不是专业的”不相呼应。", "资深": "语义：“资深”指经验丰富的专业人士，与“不是专业的”矛盾。", "高大": "体貌：“高大”描述外形，不用来修饰职业身份，句意不通。"}, "sentence_index": 0, "correct_answer": "业余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位业余医生持有执业资格证，每天都在医院全职主刀。", "explanation": "〈业余〉指非专业，持证、全职主刀的医生属于专业从业，与“业余”矛盾。"}, {"text": "这位业余法官每天都在法庭上主持庭审，已经有二十年的执业经验。", "explanation": "〈业余〉指非专业，主持庭审、有二十年执业经验属于专业，与“业余”矛盾。"}, {"text": "我的钢琴老师是业余的，他从小就在音乐学院教书。", "explanation": "〈业余〉指非职业，在音乐学院教书属于职业，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "业余", "is_correct": true, "explanation": "正确：“业余”表示非专业水平，与“照片很好看”的转折相符。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：“水平”不能用“幸福”来形容，不成搭配。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”描述地形，与摄影水平无关。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”不用来形容水平，句意不通。"}], "explanations": {"业余": "正确：“业余”表示非专业水平，与“照片很好看”的转折相符。", "幸福": "搭配：“水平”不能用“幸福”来形容，不成搭配。", "陡峭": "语义：“陡峭”描述地形，与摄影水平无关。", "透明": "语义：“透明”不用来形容水平，句意不通。"}, "sentence_index": 6, "correct_answer": "业余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支业余足球队的队员全部签有职业合同，每周领取高额年薪。", "explanation": "〈业余〉指非职业，签有职业合同、领取年薪的队员属于职业球员，与“业余”矛盾。"}, {"text": "这位业余教练带领全队拿了世界冠军，每天都要全职训练。", "explanation": "〈业余〉指非职业，全职训练的教练与此矛盾。"}, {"text": "这位业余律师每天都在律所全职工作。", "explanation": "〈业余〉指非专业，在律所全职工作属于专业，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛只有业余地选手参加。", "corrected_sentence": "这次比赛只有业余选手参加。", "error_description": "“地”是状语的标志，不能用来修饰名词“选手”。“业余”修饰“选手”时直接说“业余选手”，中间不加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支乐队很最业余，不过挺有趣。", "corrected_sentence": "这支乐队很业余，不过挺有趣。", "error_description": "程度副词“很”与“最”不能同时修饰同一形容词，只能用其一；应说“这支乐队很业余，不过挺有趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
