INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "动漫、故事里想象出来的另一个世界。", "primary_collocate": null, "pronunciation": "cì yuán", "ipa": "tsʰɨ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他在动画里看到了一个奇妙的次元。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个漫画里的次元非常奇妙。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总想去另一个次元生活。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动漫里的次元和现实不一样。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事发生在一个奇怪的次元里。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他梦见自己进入了另一个次元。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，动漫里的次元都是想象出来的。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明喜欢动漫，常常想象别的次元。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影带我们进入了新的次元。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个次元里，时间可以倒着走。", "target_word": "次元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "二次元", "label": "复合词"}, {"form": "三次元", "label": "复合词"}], "register": "中性", "sense_fingerprint": "次元：动漫、小说等作品中虚构的世界，如「二次元」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400b5293-dbe8-4b37-a144-768922327a84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96957, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次元", "is_correct": true, "explanation": "次元读作 cì yuán，指空间的方向，或动漫里想象出来的世界，是本词的正确答案。"}, {"text": "词源", "is_correct": false, "explanation": "「cí」与「cì」声调不同（第二声与第四声），意思是词语的来源。"}, {"text": "纪元", "is_correct": false, "explanation": "「jì」与「cì」声母不同（j 与 c），声调相同，意思是年代的起点、时代。"}, {"text": "辞源", "is_correct": false, "explanation": "「cí」与「cì」声调不同（第二声与第四声），意思是词语的来源，也是一部词典的名字。"}], "explanations": {"次元": "次元读作 cì yuán，指空间的方向，或动漫里想象出来的世界，是本词的正确答案。", "词源": "「cí」与「cì」声调不同（第二声与第四声），意思是词语的来源。", "纪元": "「jì」与「cì」声母不同（j 与 c），声调相同，意思是年代的起点、时代。", "辞源": "「cí」与「cì」声调不同（第二声与第四声），意思是词语的来源，也是一部词典的名字。"}, "sentence_index": null, "correct_answer": "次元"}, "level_3": {"options": [{"text": "次元", "is_correct": true, "explanation": "次元指动漫里想象出来的世界，可以看到，并且可以用「奇妙的」来形容，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「奇妙的」多修饰事物或景象，不能说「奇妙的价格」。"}, {"text": "税收", "is_correct": false, "explanation": "语义：税收是国家向民众征收的费用，不是能在动画里看到的奇妙事物。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温是人身的生理数值，不能说「一个奇妙的体温」。"}], "explanations": {"次元": "次元指动漫里想象出来的世界，可以看到，并且可以用「奇妙的」来形容，符合句意。", "价格": "搭配：「奇妙的」多修饰事物或景象，不能说「奇妙的价格」。", "税收": "语义：税收是国家向民众征收的费用，不是能在动画里看到的奇妙事物。", "体温": "搭配：体温是人身的生理数值，不能说「一个奇妙的体温」。"}, "sentence_index": 0, "correct_answer": "次元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用次元买了一瓶水。", "explanation": "这里应该用〈钱〉。次元是想象出来的世界，不能用来买东西。"}, {"text": "妈妈把次元放进了冰箱里。", "explanation": "这里应该用〈牛奶〉等食物。次元是虚构的世界，不是能放进冰箱的东西。"}, {"text": "我的次元今年八岁，在上小学。", "explanation": "这里应该用〈弟弟〉等称呼。次元是想象出来的世界，不是人，没有年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96957, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "次元", "is_correct": true, "explanation": "次元读作 cì yuán，指空间的方向，或动漫里想象出来的世界，是本词的正确答案。"}, {"text": "资源", "is_correct": false, "explanation": "「zī」与「cì」声母不同（z 与 c），声调也不同（第一声与第四声），意思是可以利用的物资、人力等。"}, {"text": "四元", "is_correct": false, "explanation": "「sì」与「cì」声母不同（s 与 c），声调相同，意思是四块钱。"}, {"text": "自愿", "is_correct": false, "explanation": "「zì yuàn」与「cì yuán」声母不同（z 与 c），第二音节声调也不同，意思是自己愿意。"}], "explanations": {"次元": "次元读作 cì yuán，指空间的方向，或动漫里想象出来的世界，是本词的正确答案。", "资源": "「zī」与「cì」声母不同（z 与 c），声调也不同（第一声与第四声），意思是可以利用的物资、人力等。", "四元": "「sì」与「cì」声母不同（s 与 c），声调相同，意思是四块钱。", "自愿": "「zì yuàn」与「cì yuán」声母不同（z 与 c），第二音节声调也不同，意思是自己愿意。"}, "sentence_index": null, "correct_answer": "次元"}, "level_3": {"options": [{"text": "次元", "is_correct": true, "explanation": "次元指动漫里想象出来的世界，可以是虚构的，符合句意。"}, {"text": "电费", "is_correct": false, "explanation": "语义：「电费」是用电所付的费用，是现实中的开支，不是想象出来的东西，与句意不符。"}, {"text": "存款", "is_correct": false, "explanation": "语义：「存款」是存放在银行里的实际钱款，不是想象出来的东西，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」是人或动物的实际重量，不是想象出来的东西，与句意不符。"}], "explanations": {"次元": "次元指动漫里想象出来的世界，可以是虚构的，符合句意。", "电费": "语义：「电费」是用电所付的费用，是现实中的开支，不是想象出来的东西，与句意不符。", "存款": "语义：「存款」是存放在银行里的实际钱款，不是想象出来的东西，与句意不符。", "体重": "语义：「体重」是人或动物的实际重量，不是想象出来的东西，与句意不符。"}, "sentence_index": 6, "correct_answer": "次元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "次元是我们生活的星球，上面有七大洲。", "explanation": "次元指空间的方向，或动漫里想象出来的世界，不是星球，不能说它上面有七大洲。"}, {"text": "次元是地球的卫星，每天绕着地球转。", "explanation": "次元不是天体，不能做地球的卫星，也不会绕着地球转。"}, {"text": "这杯水是次元煮的，还很烫。", "explanation": "次元不是人，也不能做饭煮水，不能说它煮了水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影带我们走进了一座神奇的次元。", "corrected_sentence": "这部电影带我们走进了一个神奇的次元。", "error_description": "量词错误：次元应该用量词「个」，「座」用于山、房屋等大型固定的东西，不能用于次元。正确的说法是「一个神奇的次元」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只次元的规则和我们的世界很不一样。", "corrected_sentence": "这个次元的规则和我们的世界很不一样。", "error_description": "量词错误：次元应该用量词「个」，「只」多用于动物等单个的东西，不能用于次元。正确的说法是「这个次元」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
