INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96961, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写好的、真的那一份文件。", "primary_collocate": null, "pronunciation": "zhèng běn", "ipa": "ʈʂɤŋ˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把合同正本交给老板。", "target_word": "正本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是证书的正本，不是复印件。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "正本在我这里，副本在他那里。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办手续时，要带身份证和合同正本。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把毕业证书的正本放在抽屉里了。", "target_word": "正本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你给我一份正本，复印件不行。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行要看这份文件的正本。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份正本很重要，请你好好保管。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "正本丢了，他只好去重新办一份。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院只接受正本，不接受复印件。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "书面", "sense_fingerprint": "办手续时要用的、真的那一份文件，不是复印件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96961, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正本", "is_correct": true, "explanation": "正确：听到的是 zhèng běn（正本），指办手续用的真的那一份文件。"}, {"text": "整本", "is_correct": false, "explanation": "zhěng běn（第三声）与 zhèng běn（第四声）声调不同，意思是整本（一整册书）。"}, {"text": "正版", "is_correct": false, "explanation": "zhèng bǎn 与 zhèng běn 第二音节韵母不同（an 与 en），意思是正版（合法版本）。"}, {"text": "账本", "is_correct": false, "explanation": "zhàng běn 与 zhèng běn 第一音节韵母不同（a 与 e），意思是账本。"}], "explanations": {"正本": "正确：听到的是 zhèng běn（正本），指办手续用的真的那一份文件。", "整本": "zhěng běn（第三声）与 zhèng běn（第四声）声调不同，意思是整本（一整册书）。", "正版": "zhèng bǎn 与 zhèng běn 第二音节韵母不同（an 与 en），意思是正版（合法版本）。", "账本": "zhàng běn 与 zhèng běn 第一音节韵母不同（a 与 e），意思是账本。"}, "sentence_index": null, "correct_answer": "正本"}, "level_3": {"options": [{"text": "果汁", "is_correct": false, "explanation": "语义：果汁不是文件，“合同果汁”无法指代要交的东西。"}, {"text": "正本", "is_correct": true, "explanation": "正确：“合同正本”指签署的真的那一份，交给老板合理。"}, {"text": "诏书", "is_correct": false, "explanation": "语域：诏书是古代帝王的文告，与现代合同的口语语境不符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是文件，与“合同”组合后无法指代要交的东西。"}], "explanations": {"果汁": "语义：果汁不是文件，“合同果汁”无法指代要交的东西。", "正本": "正确：“合同正本”指签署的真的那一份，交给老板合理。", "诏书": "语域：诏书是古代帝王的文告，与现代合同的口语语境不符。", "钥匙": "语义：钥匙不是文件，与“合同”组合后无法指代要交的东西。"}, "sentence_index": 0, "correct_answer": "正本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们买的是正本书，不是盗版。", "explanation": "这里应该用〈正版〉。正本指文件的原件，书籍的合法版本要说正版。"}, {"text": "这幅画是正本，不是仿品。", "explanation": "这里应该用〈真品〉。正本只指文件的原件，画作的真品要说真品。"}, {"text": "这瓶酒是正本，比那瓶贵很多。", "explanation": "这里应该用〈正品〉。正本只指文件的原件，酒的正品要说正品，不说正本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌词", "is_correct": false, "explanation": "语义：歌词不是需要核验的文件，银行不会要看歌词。"}, {"text": "正本", "is_correct": true, "explanation": "正确：银行要看的是这份文件的原件，即正本。"}, {"text": "诗句", "is_correct": false, "explanation": "语域：诗句是文学语体，用在银行要看文件的口语句子里很突兀。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单不是需要核验的文件原件，句意不通。"}], "explanations": {"歌词": "语义：歌词不是需要核验的文件，银行不会要看歌词。", "正本": "正确：银行要看的是这份文件的原件，即正本。", "诗句": "语域：诗句是文学语体，用在银行要看文件的口语句子里很突兀。", "菜单": "语义：菜单不是需要核验的文件原件，句意不通。"}, "sentence_index": 6, "correct_answer": "正本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的正本是英文的。", "explanation": "这里应该用〈原版〉。正本指文件的原件，电影、书籍的原始版本要说原版。"}, {"text": "我昨天看了一本正本，故事很有意思。", "explanation": "这里应该用〈小说〉。正本指文件的原件，不是可以读故事的书；讲故事的书要说小说。"}, {"text": "这本古书是正本，全世界只有一本。", "explanation": "这里应该用〈孤本〉。正本指文件的原件，全世界仅存一部的古籍要说孤本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去办了一支正本。", "corrected_sentence": "他去办了一份正本。", "error_description": "量词错误：“正本”是文件，应用“份”；“支”用于笔、枪等细长物，不能用于文件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这支正本收好了。", "corrected_sentence": "他把这份正本收好了。", "error_description": "量词错误：“正本”是文件，应用“份”；“支”用于笔、枪等细长物，不能用于文件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
