INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文书的原本；与副本相对。", "primary_collocate": null, "pronunciation": "zhèng běn", "ipa": "ʈʂɤŋ˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这份文件有正本，也有副本。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "正本留在公司，副本给客户。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同一式两份，一份是正本，一份是副本。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "正本和副本的内容应该完全一样。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把正本放进了保险柜里。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信的正本已经寄出去了。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请检查一下正本上有没有签名。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "正本要盖章，副本不用。", "target_word": "正本", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我只拿到副本，没拿到正本。", "target_word": "正本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "复印件不能代替正本。", "target_word": "正本", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "书面", "sense_fingerprint": "文书的原本，与副本相对，通常盖章签名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96962, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正本", "is_correct": true, "explanation": "正确：听到的是 zhèng běn（正本），指与副本相对的文书原本。"}, {"text": "整本", "is_correct": false, "explanation": "zhěng běn（第三声）与 zhèng běn（第四声）声调不同，意思是整本（一整册书）。"}, {"text": "账本", "is_correct": false, "explanation": "zhàng běn 与 zhèng běn 第一音节韵母不同（a 与 e），意思是账本。"}, {"text": "正版", "is_correct": false, "explanation": "zhèng bǎn 与 zhèng běn 第二音节韵母不同（an 与 en），意思是正版（合法版本）。"}], "explanations": {"正本": "正确：听到的是 zhèng běn（正本），指与副本相对的文书原本。", "整本": "zhěng běn（第三声）与 zhèng běn（第四声）声调不同，意思是整本（一整册书）。", "账本": "zhàng běn 与 zhèng běn 第一音节韵母不同（a 与 e），意思是账本。", "正版": "zhèng bǎn 与 zhèng běn 第二音节韵母不同（an 与 en），意思是正版（合法版本）。"}, "sentence_index": null, "correct_answer": "正本"}, "level_3": {"options": [{"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉不是文件，“这份文件有香蕉”句意不通。"}, {"text": "正本", "is_correct": true, "explanation": "正确：“正本”与“副本”相对，文件有正本也有副本。"}, {"text": "诗句", "is_correct": false, "explanation": "语域：诗句是文学语体，放在讲文件的口语句子里很突兀。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声不是文件的一种，句意不通。"}], "explanations": {"香蕉": "语义：香蕉不是文件，“这份文件有香蕉”句意不通。", "正本": "正确：“正本”与“副本”相对，文件有正本也有副本。", "诗句": "语域：诗句是文学语体，放在讲文件的口语句子里很突兀。", "雷声": "语义：雷声不是文件的一种，句意不通。"}, "sentence_index": 0, "correct_answer": "正本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套软件是正本，不是盗版的。", "explanation": "这里应该用〈正版〉。正本指文件的原件，软件的合法版本要说正版。"}, {"text": "这件瓷器是正本，不是仿制品。", "explanation": "这里应该用〈真品〉。正本指文件的原件，瓷器等文物的真实作品要说真品。"}, {"text": "这部小说的正本很有名。", "explanation": "这里应该用〈原著〉。正本指文件的原件，小说的原始作品要说原著。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空上不会有签名，句子不通。"}, {"text": "王朝", "is_correct": false, "explanation": "语域：王朝是历史用语，放在要求检查签名的口语句子里很突兀。"}, {"text": "正本", "is_correct": true, "explanation": "正确：“正本上”指文件的原件，要检查它有没有签名。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉上不能签名，句意不通。"}], "explanations": {"天空": "语义：天空上不会有签名，句子不通。", "王朝": "语域：王朝是历史用语，放在要求检查签名的口语句子里很突兀。", "正本": "正确：“正本上”指文件的原件，要检查它有没有签名。", "香蕉": "语义：香蕉上不能签名，句意不通。"}, "sentence_index": 6, "correct_answer": "正本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部动画片的正本是日文的。", "explanation": "这里应该用〈原版〉。正本指文件的原件，影视作品的原始版本要说原版。"}, {"text": "她的正本画得很好，大家都夸她。", "explanation": "这里应该用〈画作〉。正本指文件的原本，绘画作品要说画作，不说正本。"}, {"text": "这套丛书是正本，全世界只有一套。", "explanation": "这里应该用〈孤本〉。正本指文件的原件，全世界仅存一套的书要说孤本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把正本要先盖章。", "corrected_sentence": "这份正本要先盖章。", "error_description": "量词错误：“正本”是文件，应用“份”；“把”用于有柄的器具，不能用于文件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这把正本收进了抽屉。", "corrected_sentence": "他把这份正本收进了抽屉。", "error_description": "量词错误：“正本”是文件，应用“份”；“把”用于有柄的器具，不能用于文件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
