INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96963, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "顺着一条路或者一个边走。", "primary_collocate": null, "pronunciation": "yán", "ipa": "jɛn˧˥", "syllable_count": 1, "sentences": [{"text": "我们沿着河边慢慢走。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿这条路一直走，就到了。", "target_word": "沿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明沿着马路跑步。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着河边散步。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们沿着小路走进了山里。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请沿着人行道走，别走到马路中间。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天沿着湖边走一圈。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车沿着山路慢慢往上开。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿这条街往前走，右边有银行。", "target_word": "沿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沿着海边走了很久。", "target_word": "沿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沿着", "label": "体标"}], "register": "中性", "sense_fingerprint": "沿：顺着路、河、边等走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96963, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沿", "is_correct": true, "explanation": "正确：沿，顺着一条路或一个边走。"}, {"text": "眼", "is_correct": false, "explanation": "眼 yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。"}, {"text": "演", "is_correct": false, "explanation": "演 yǎn（第三声）与 yán（第二声）声调不同，意思是表演。"}, {"text": "验", "is_correct": false, "explanation": "验 yàn（第四声）与 yán（第二声）声调不同，意思是检验。"}, {"text": "洋", "is_correct": false, "explanation": "洋 yáng 与 yán 韵母不同（ang 与 an），意思是海洋、外国的。"}], "explanations": {"沿": "正确：沿，顺着一条路或一个边走。", "眼": "眼 yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。", "演": "演 yǎn（第三声）与 yán（第二声）声调不同，意思是表演。", "验": "验 yàn（第四声）与 yán（第二声）声调不同，意思是检验。", "洋": "洋 yáng 与 yán 韵母不同（ang 与 an），意思是海洋、外国的。"}, "sentence_index": null, "correct_answer": "沿"}, "level_3": {"options": [{"text": "沿", "is_correct": true, "explanation": "正确：沿着河边，表示顺着河边的路线慢慢走。"}, {"text": "离", "is_correct": false, "explanation": "搭配：“离”表示距离，后面要接参照点，不能表示顺着河边走。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”后面要接被替代的人或事，“替河边慢慢走”说不通。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”需要施事或受事，“被河边慢慢走”不成句。"}], "explanations": {"沿": "正确：沿着河边，表示顺着河边的路线慢慢走。", "离": "搭配：“离”表示距离，后面要接参照点，不能表示顺着河边走。", "替": "配价：“替”后面要接被替代的人或事，“替河边慢慢走”说不通。", "被": "配价：“被”需要施事或受事，“被河边慢慢走”不成句。"}, "sentence_index": 0, "correct_answer": "沿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他沿着大家的意思，同意了这个计划。", "explanation": "这里应该用〈顺着〉。沿着指顺某条路线或边缘走；顺着别人的意思表示依从，要用顺着。"}, {"text": "他沿着镜子看了看自己的脸色。", "explanation": "这里应该用〈对着〉。沿着指顺某条路线或边缘走，面对镜子看自己要用对着。"}, {"text": "沿着时间的推移，城市变化很大。", "explanation": "这里应该用〈随着〉。沿着只表示顺某条路线或边缘，表示伴随时间变化要用随着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96963, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沿", "is_correct": true, "explanation": "正确：沿，顺着一条路或一个边走。"}, {"text": "掩", "is_correct": false, "explanation": "掩 yǎn（第三声）与 yán（第二声）声调不同，意思是遮掩。"}, {"text": "宴", "is_correct": false, "explanation": "宴 yàn（第四声）与 yán（第二声）声调不同，意思是宴席。"}, {"text": "烟", "is_correct": false, "explanation": "烟 yān（第一声）与 yán（第二声）声调不同，意思是烟雾。"}, {"text": "扬", "is_correct": false, "explanation": "扬 yáng 与 yán 韵母不同（ang 与 an），意思是扬起、飞起。"}], "explanations": {"沿": "正确：沿，顺着一条路或一个边走。", "掩": "掩 yǎn（第三声）与 yán（第二声）声调不同，意思是遮掩。", "宴": "宴 yàn（第四声）与 yán（第二声）声调不同，意思是宴席。", "烟": "烟 yān（第一声）与 yán（第二声）声调不同，意思是烟雾。", "扬": "扬 yáng 与 yán 韵母不同（ang 与 an），意思是扬起、飞起。"}, "sentence_index": null, "correct_answer": "沿"}, "level_3": {"options": [{"text": "沿", "is_correct": true, "explanation": "正确：沿着湖边，表示沿湖边的路线走一圈。"}, {"text": "比", "is_correct": false, "explanation": "配价：“比”需要比较的对象，“比湖边走一圈”说不通。"}, {"text": "给", "is_correct": false, "explanation": "语义：“给”表示给予或为了谁，不能表示沿路线走。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”要带可以被处置的对象，“把湖边走一圈”不成立。"}], "explanations": {"沿": "正确：沿着湖边，表示沿湖边的路线走一圈。", "比": "配价：“比”需要比较的对象，“比湖边走一圈”说不通。", "给": "语义：“给”表示给予或为了谁，不能表示沿路线走。", "把": "搭配：“把”要带可以被处置的对象，“把湖边走一圈”不成立。"}, "sentence_index": 6, "correct_answer": "沿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沿着门口大喊了一声。", "explanation": "这里应该用〈冲着〉。沿着指顺某条路线或边缘走，朝门口大喊要用冲着。"}, {"text": "他沿着家里出发，去学校上课。", "explanation": "这里应该用〈从〉。沿着指顺某条路线或边缘走，表示出发的起点要用从。"}, {"text": "沿着未来努力，不要停下来。", "explanation": "这里应该用〈朝着〉。沿着表示顺路线或边缘走，表示向某个目标努力要用朝着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们沿了公园的小路散步。", "corrected_sentence": "我们沿着公园的小路散步。", "error_description": "错误：“沿”后的体标应用“着”，这里误用“了”，说成“沿了公园的小路”不通。正确：应说“沿着公园的小路散步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天早上沿过湖边跑步。", "corrected_sentence": "她每天早上沿着湖边跑步。", "error_description": "错误：“沿”表示顺着路线时要带“着”，不能用“过”，“沿过湖边跑步”不通。正确：应说“沿着湖边跑步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
