INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "没有做某事的打算或意图。", "primary_collocate": null, "pronunciation": "wú yì", "ipa": "u˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "我无意和你吵架，只是想说清楚。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无意参加这次比赛，所以没有报名。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这份工作无意，打算明年换一个。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对当班长无意，你们选别人吧。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板无意加工资，大家都有点失望。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无意结婚，父母很着急。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无意打扰你们，马上就走。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她无意留在这个城市，毕业就回家。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们无意跟别人比，只想做好自己。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无意当官，只想安静地教书。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无意中", "label": "复合"}, {"form": "无意间", "label": "复合"}], "register": "中性", "sense_fingerprint": "无意：没有某种打算或意图，后面常接动词，如无意参加、无意伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无意", "is_correct": true, "explanation": "正确。“我无意和你吵架”表示没有这样的打算，与“只是想说清楚”相符。"}, {"text": "有意", "is_correct": false, "explanation": "语义：“有意”表示有打算、故意，与“只是想说清楚”的语气矛盾。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：“乐意”表示愿意去做，句子会变成愿意吵架，与后半句的意思不合。"}, {"text": "热衷", "is_correct": false, "explanation": "搭配：“热衷”后面要接“于”或“做某事”的结构，“热衷和你吵架”搭配不当。"}], "explanations": {"无意": "正确。“我无意和你吵架”表示没有这样的打算，与“只是想说清楚”相符。", "有意": "语义：“有意”表示有打算、故意，与“只是想说清楚”的语气矛盾。", "乐意": "语义：“乐意”表示愿意去做，句子会变成愿意吵架，与后半句的意思不合。", "热衷": "搭配：“热衷”后面要接“于”或“做某事”的结构，“热衷和你吵架”搭配不当。"}, "sentence_index": 0, "correct_answer": "无意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头无意掉下了山坡。", "explanation": "这里应该用〈不小心〉。“无意”的主语必须是有意图的人，石头没有意图，不能用“无意”。"}, {"text": "他无意参加比赛，所以第一个报了名。", "explanation": "这里应该用〈有意〉。“无意参加”表示没有参加的打算，和“第一个报了名”矛盾。"}, {"text": "她无意出国，所以每天努力准备留学考试。", "explanation": "这里应该用〈有意〉。没有出国的打算，就不会去准备留学考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无意", "is_correct": true, "explanation": "正确。“我无意打扰你们”表示没有打扰的打算，与“马上就走”的语气相符。"}, {"text": "有心", "is_correct": false, "explanation": "语义：“有心”表示有意去做，句子会变成有意打扰，与“马上就走”的客气语气不合。"}, {"text": "热心", "is_correct": false, "explanation": "语义：“热心”形容主动帮助他人，用来修饰“打扰”，句意前后矛盾。"}, {"text": "忙碌", "is_correct": false, "explanation": "搭配：“忙碌”形容人很忙，不能用来说“忙碌打扰你们”。"}], "explanations": {"无意": "正确。“我无意打扰你们”表示没有打扰的打算，与“马上就走”的语气相符。", "有心": "语义：“有心”表示有意去做，句子会变成有意打扰，与“马上就走”的客气语气不合。", "热心": "语义：“热心”形容主动帮助他人，用来修饰“打扰”，句意前后矛盾。", "忙碌": "搭配：“忙碌”形容人很忙，不能用来说“忙碌打扰你们”。"}, "sentence_index": 6, "correct_answer": "无意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器无意地运行了很久。", "explanation": "这里应该用〈不小心〉或删去“无意”。“无意”的主语必须是有意图的人，机器没有意图，不能用“无意”。"}, {"text": "他无意买房，所以每个周末都去看房子。", "explanation": "这里应该用〈有意〉。“无意买房”表示没有买房的打算，和天天去看房子矛盾。"}, {"text": "我无意留下来，所以又租了一年房子。", "explanation": "这里应该用〈有意〉。没有留下的打算，就不会再租一年房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很无意和他争论，只是想解释清楚。", "corrected_sentence": "我无意和他争论，只是想解释清楚。", "error_description": "错误：“无意”前面多了“很”。正确形式是“我无意和他争论”，“无意”是表示没有打算的词，不能用程度副词修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我无意了打扰大家，明天再来。", "corrected_sentence": "我无意打扰大家，明天再来。", "error_description": "错误：“了”放在“无意”和“打扰”之间，位置不对。正确形式是“我无意打扰大家，明天再来。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96969, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "“高兴”表示心情好，与“烦”（心里不高兴）意思相反。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”形容物体坚固，与心情无关，不是“烦”的反义词。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与心情无关，不是“烦”的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“烦”的心情义没有对立关系。"}], "correct_answer": "高兴", "explanations": {"高兴": "“高兴”表示心情好，与“烦”（心里不高兴）意思相反。", "结实": "“结实”形容物体坚固，与心情无关，不是“烦”的反义词。", "粗糙": "“粗糙”形容表面不光滑，与心情无关，不是“烦”的反义词。", "清楚": "“清楚”形容明白、分明，与“烦”的心情义没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
