INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96969, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里不高兴，觉得不舒服。", "primary_collocate": null, "pronunciation": "fán", "ipa": "fan˧˥", "syllable_count": 1, "sentences": [{"text": "我今天心里很烦。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，他一整天都很烦。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太吵了，我真烦。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不说话，因为心里有点烦。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一想到明天的工作，我就烦。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天事情太多，我好烦啊。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很烦，不想见人。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟一直哭，妈妈烦死了。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我出不了门，心里烦得很。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么了？看起来有点烦。", "target_word": "烦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心烦", "label": "复合词"}, {"form": "烦恼", "label": "复合词"}], "register": "口语", "sense_fingerprint": "烦：心里不高兴，觉得不舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400b5293-dbe8-4b37-a144-768922327a84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96969, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烦", "is_correct": true, "explanation": "烦（fán）：心里不高兴，觉得不舒服。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fán（第二声）声调不同，意思是饭食。"}, {"text": "房", "is_correct": false, "explanation": "fáng 与 fán 韵尾不同（-ang 与 -an），意思是房屋。"}, {"text": "翻", "is_correct": false, "explanation": "fān（第一声）与 fán（第二声）声调不同，意思是翻动、翻译。"}, {"text": "反", "is_correct": false, "explanation": "fǎn（第三声）与 fán（第二声）声调不同，意思是相反、反对。"}, {"text": "乏", "is_correct": false, "explanation": "fá 与 fán 韵尾不同（少了 -n），意思是疲乏。"}], "explanations": {"烦": "烦（fán）：心里不高兴，觉得不舒服。", "饭": "fàn（第四声）与 fán（第二声）声调不同，意思是饭食。", "房": "fáng 与 fán 韵尾不同（-ang 与 -an），意思是房屋。", "翻": "fān（第一声）与 fán（第二声）声调不同，意思是翻动、翻译。", "反": "fǎn（第三声）与 fán（第二声）声调不同，意思是相反、反对。", "乏": "fá 与 fán 韵尾不同（少了 -n），意思是疲乏。"}, "sentence_index": null, "correct_answer": "烦"}, "level_3": {"options": [{"text": "烦", "is_correct": true, "explanation": "正确：“烦”形容心里不高兴，与“心里很”搭配。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指肚子需要食物，不能用来形容心情。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能说心里咸。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”指物体含有水分，与心情无关。"}], "explanations": {"烦": "正确：“烦”形容心里不高兴，与“心里很”搭配。", "饿": "语义：“饿”指肚子需要食物，不能用来形容心情。", "咸": "搭配：“咸”形容味道，不能说心里咸。", "湿": "语义：“湿”指物体含有水分，与心情无关。"}, "sentence_index": 0, "correct_answer": "烦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里一个人走山路，我烦得直发抖。", "explanation": "这里应该用〈害怕〉。“烦”表示心里不高兴，不表示因恐惧而发抖。"}, {"text": "他收到录取通知，烦得在屋里转圈。", "explanation": "这里应该用〈高兴〉。“烦”表示心里不高兴，收到好消息时不能用“烦”。"}, {"text": "演讲前他烦得手心直冒汗，话都说不利索。", "explanation": "这里应该用〈紧张〉。“烦”表示心里不高兴，不表示临场时的慌乱和紧张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96969, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烦", "is_correct": true, "explanation": "烦（fán）：心里不高兴，觉得不舒服。"}, {"text": "犯", "is_correct": false, "explanation": "fàn（第四声）与 fán（第二声）声调不同，意思是违反、犯错。"}, {"text": "乏", "is_correct": false, "explanation": "fá 与 fán 韵尾不同（少了 -n），意思是疲乏。"}, {"text": "番", "is_correct": false, "explanation": "fān（第一声）与 fán（第二声）声调不同，意思是次、回。"}, {"text": "返", "is_correct": false, "explanation": "fǎn（第三声）与 fán（第二声）声调不同，意思是返回。"}], "explanations": {"烦": "烦（fán）：心里不高兴，觉得不舒服。", "犯": "fàn（第四声）与 fán（第二声）声调不同，意思是违反、犯错。", "乏": "fá 与 fán 韵尾不同（少了 -n），意思是疲乏。", "番": "fān（第一声）与 fán（第二声）声调不同，意思是次、回。", "返": "fǎn（第三声）与 fán（第二声）声调不同，意思是返回。"}, "sentence_index": null, "correct_answer": "烦"}, "level_3": {"options": [{"text": "烦", "is_correct": true, "explanation": "正确：“烦”形容心里不高兴，与“看起来很”及“不想见人”相合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能用来形容人的神态。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”形容温度，不用来描述人看起来的样子。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，句子说的是人的神态和心情。"}], "explanations": {"烦": "正确：“烦”形容心里不高兴，与“看起来很”及“不想见人”相合。", "甜": "语义：“甜”形容味道，不能用来形容人的神态。", "烫": "搭配：“烫”形容温度，不用来描述人看起来的样子。", "辣": "语义：“辣”形容味道，句子说的是人的神态和心情。"}, "sentence_index": 6, "correct_answer": "烦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的头有点烦，想躺下。", "explanation": "这里应该用〈疼〉。“烦”形容心情，不用来描述头部疼痛。"}, {"text": "我的腿很烦，走不动了。", "explanation": "这里应该用〈酸〉。“烦”形容心情，不用来形容腿部酸软。"}, {"text": "这杯水很烦，现在喝不了。", "explanation": "这里应该用〈烫〉。“烦”形容人的心情，不用来描述水的温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, v