INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天他心里烦很，不爱说话。", "corrected_sentence": "这几天他心里很烦，不爱说话。", "error_description": "“很”放在“烦”之后是错误的。程度副词“很”应放在形容词前面，应说“很烦”，不能说“烦很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天工作太多，我烦太了。", "corrected_sentence": "这几天工作太多，我太烦了。", "error_description": "“太”的位置错误。程度副词“太”应放在形容词“烦”之前，说“太烦了”，不能说“烦太了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db43fd26-2dde-444c-84a9-3bb2a786990b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
