INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做了坏事、被关起来的人。", "primary_collocate": null, "pronunciation": "fàn rén", "ipa": "fan˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "警察把犯人带回了警察局。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个犯人一直坐在小房间里。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人的家人来看他了。", "target_word": "犯人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个犯人很听话，也不想逃跑。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上有一个犯人跑了。", "target_word": "犯人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "犯人每天要在里面做工。", "target_word": "犯人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在监狱里认识了很多犯人。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的犯人最后还是逃走了。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看守叫犯人早上六点起床。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个犯人后悔自己做过坏事。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "犯人们", "label": "复数形式"}], "register": "中性", "sense_fingerprint": "做了坏事被关起来的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96971, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犯人", "is_correct": true, "explanation": "正确：犯人指做了坏事、被关起来的人，可以被警察带回警察局。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地方，不能被警察带回警察局。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“带回”不能用于空气，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是固定在建筑上的东西，不能被带回警察局。"}], "explanations": {"犯人": "正确：犯人指做了坏事、被关起来的人，可以被警察带回警察局。", "花园": "语义：“花园”是地方，不能被警察带回警察局。", "空气": "搭配：“带回”不能用于空气，句意不通。", "窗户": "语义：窗户是固定在建筑上的东西，不能被带回警察局。"}, "sentence_index": 0, "correct_answer": "犯人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那名犯人正在学校里给学生上课。", "explanation": "这里应该用〈老师〉。犯人指做了坏事、被关起来的人，给学生上课的是老师，不能称作犯人。"}, {"text": "他出狱十年了，现在是一家公司的经理，仍然是一名犯人。", "explanation": "这里应该用〈刑满释放人员〉。犯人指正在被依法拘禁的人，出狱后就不再是犯人了。"}, {"text": "犯人已经被判无罪，今天可以回家了。", "explanation": "这里应该用〈无罪释放者〉。犯人指做了坏事并被关起来的人，判无罪的人不是犯人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犯人", "is_correct": true, "explanation": "正确：犯人，他在监狱里认识的就是这类被关押的人。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：监狱里认识的通常是人，说认识很多汽车不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“认识”不能用于玻璃这类材料，句意不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：监狱里不会认识很多花瓶，与场景不符。"}], "explanations": {"犯人": "正确：犯人，他在监狱里认识的就是这类被关押的人。", "汽车": "搭配：监狱里认识的通常是人，说认识很多汽车不通。", "玻璃": "搭配：“认识”不能用于玻璃这类材料，句意不通。", "花瓶": "语义：监狱里不会认识很多花瓶，与场景不符。"}, "sentence_index": 6, "correct_answer": "犯人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那名犯人每天在厨房里做饭，给大家吃。", "explanation": "这里应该用〈厨师〉。犯人指做了坏事、被关起来的人，做饭的是厨师，不能称作犯人。"}, {"text": "那名犯人正在路口指挥交通。", "explanation": "这里应该用〈交警〉。犯人指做了坏事、被依法关押的人，指挥交通的是交警，不能称作犯人。"}, {"text": "那名犯人每天在银行帮客人存钱。", "explanation": "这里应该用〈柜员〉。犯人指做了坏事、被关起来的人，在银行办事的是柜员，不能称作犯人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只犯人昨晚逃走了。", "corrected_sentence": "那名犯人昨晚逃走了。", "error_description": "错误：量词“只”。正确：“名”。“只”用于动物等，修饰人要用“名”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本犯人每天早上都要打扫操场。", "corrected_sentence": "那名犯人每天早上都要打扫操场。", "error_description": "错误：量词“本”。正确：“名”。“本”用于书籍等，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
