INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96972, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "犯罪而被依法拘禁的人。", "primary_collocate": null, "pronunciation": "fàn rén", "ipa": "fan˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "法院判了犯人十年。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人在监狱里要遵守规定。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监狱每个月让犯人见一次家人。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人服刑期间表现很好。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家监狱里关着三百多名犯人。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，犯人也有自己的权利。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人服刑结束后可以回家。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监狱里的犯人要学习法律知识。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名判了刑的犯人。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每周都来监狱给犯人检查身体。", "target_word": "犯人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "犯人们", "label": "复数形式"}], "register": "书面", "sense_fingerprint": "犯罪后依法被关押的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96972, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犯人", "is_correct": true, "explanation": "正确：犯人指犯罪后被依法拘禁的人，法院可以判他刑。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察是抓犯人的人，不是被法院判刑的人。"}, {"text": "树", "is_correct": false, "explanation": "配价：“判”的对象须是人，不能判树十年。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“判……年”只用于人，不能说判窗户十年。"}], "explanations": {"犯人": "正确：犯人指犯罪后被依法拘禁的人，法院可以判他刑。", "警察": "语义：警察是抓犯人的人，不是被法院判刑的人。", "树": "配价：“判”的对象须是人，不能判树十年。", "窗户": "搭配：“判……年”只用于人，不能说判窗户十年。"}, "sentence_index": 0, "correct_answer": "犯人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那名犯人每天骑自行车送报纸。", "explanation": "这里应该用〈送报员〉。犯人指犯罪而被依法拘禁的人，送报纸的是送报员，不能称作犯人。"}, {"text": "那名犯人每天早上都来学校上课，教我们数学。", "explanation": "这里应该用〈老师〉。犯人指犯罪而被依法拘禁的人，给学生上课的是老师，不能称作犯人。"}, {"text": "那名犯人正在电视台播报新闻。", "explanation": "这里应该用〈主持人〉。犯人指被依法拘禁的人，播报新闻的是主持人，不能称作犯人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犯人", "is_correct": true, "explanation": "正确：犯人，服刑结束后可以回家。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“服刑”只用于被判刑的人，学生不能服刑。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：“服刑”只用于人，狗不能服刑。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能服刑，句意不通。"}], "explanations": {"犯人": "正确：犯人，服刑结束后可以回家。", "学生": "搭配：“服刑”只用于被判刑的人，学生不能服刑。", "狗": "搭配：“服刑”只用于人，狗不能服刑。", "花": "语义：花不能服刑，句意不通。"}, "sentence_index": 6, "correct_answer": "犯人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那名犯人在餐厅里给客人端菜。", "explanation": "这里应该用〈服务员〉。犯人指被依法拘禁的人，给客人端菜的是服务员，不能称作犯人。"}, {"text": "犯人已经被判无罪，今天就能回家了。", "explanation": "这里应该用〈无罪释放者〉。犯人指犯罪而被依法拘禁的人，判无罪的人不是犯人。"}, {"text": "那名犯人每天早上开公交车送我们上学。", "explanation": "这里应该用〈司机〉。犯人指被依法拘禁的人，开车送学生的是司机，不能称作犯人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那辆犯人服刑已经三年了。", "corrected_sentence": "那名犯人服刑已经三年了。", "error_description": "错误：量词“辆”。正确：“名”。“辆”用于车，不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张犯人昨天转到了另一所监狱。", "corrected_sentence": "那名犯人昨天转到了另一所监狱。", "error_description": "错误：量词“张”。正确：“名”。“张”用于平面的东西，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
