INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "绕着地球走一圈。", "primary_collocate": null, "pronunciation": "huán qiú", "ipa": "xwan˧˥ tɕʰi̯ou˧˥", "syllable_count": 2, "sentences": [{"text": "他想骑自行车环球一圈。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一个人驾船环球，花了两年。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算明年坐飞机环球一次。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若有足够的资金，你是否愿意环球一次？", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是第一个独自驾船环球的人。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船用了三个月才环球一周。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的梦想是有一天能环球。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位探险家环球一周，终于回到了家乡。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开着车环球，路上拍了很多照片。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她退休以后，决定环球一次。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "环球：动词，指绕地球走一圈，如环球一周", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环球", "is_correct": true, "explanation": "正确答案：环球，指绕地球走一圈，与“骑自行车”绕行一圈相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不是绕行的动作，骑自行车睡觉一圈说不通。"}, {"text": "煮饭", "is_correct": false, "explanation": "语义：煮饭不能用来表示绕行，与骑车的动作不合。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“微笑”不能和“一圈”搭配，不说微笑一圈。"}], "explanations": {"环球": "正确答案：环球，指绕地球走一圈，与“骑自行车”绕行一圈相合。", "睡觉": "语义：睡觉不是绕行的动作，骑自行车睡觉一圈说不通。", "煮饭": "语义：煮饭不能用来表示绕行，与骑车的动作不合。", "微笑": "搭配：“微笑”不能和“一圈”搭配，不说微笑一圈。"}, "sentence_index": 0, "correct_answer": "环球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这个岛上环球一周，走遍了每个角落。", "explanation": "这里应该用〈绕〉。环球指绕整个地球走一圈，不能限定在一个岛上；绕岛一周要说绕。"}, {"text": "这家公司的产品很快就环球了。", "explanation": "这里应该用〈行销〉。环球作动词只表示绕地球走一圈，不表示产品传播到各地；产品销往世界各地要说行销。"}, {"text": "他在教室里环球了一圈，然后吃午饭。", "explanation": "这里应该用〈绕〉。环球只指绕整个地球一周，不能用于教室这样的小空间；在教室里转一圈要说绕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环球", "is_correct": true, "explanation": "正确答案：环球，指绕地球走一圈，与“梦想”的内容相合。"}, {"text": "打鼾", "is_correct": false, "explanation": "语义：打鼾是睡觉时发出的声音，不能作为梦想的内容。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是身体的反应，不是人可以立志去做的事，与“梦想”不合。"}, {"text": "排队", "is_correct": false, "explanation": "搭配：排队指按顺序等候，不说梦想是排队。"}], "explanations": {"环球": "正确答案：环球，指绕地球走一圈，与“梦想”的内容相合。", "打鼾": "语义：打鼾是睡觉时发出的声音，不能作为梦想的内容。", "咳嗽": "语义：咳嗽是身体的反应，不是人可以立志去做的事，与“梦想”不合。", "排队": "搭配：排队指按顺序等候，不说梦想是排队。"}, "sentence_index": 6, "correct_answer": "环球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她退休以后，买了一个环球，每天都看。", "explanation": "环球没有地球仪的意思，不能当作实物买来看，这里的用法不对。"}, {"text": "他在超市门口环球了一圈，然后回家了。", "explanation": "这里应该用〈绕〉。环球指绕整个地球一周，不能用于超市门口这样的小范围；在门口转一圈要说绕。"}, {"text": "她退休以后，决定在家里环球一次。", "explanation": "这里应该用〈转〉。环球指绕整个地球一周，不能限定在家里；在家里走一圈要说转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她打算用一年的时间环球地球一次。", "corrected_sentence": "她打算用一年的时间环球一次。", "error_description": "“环球”是不及物动词，不能带“地球”作宾语，应写“环球一次”；写成“环球地球”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人环球一个周，还写了一本书。", "corrected_sentence": "他一个人环球一周，还写了一本书。", "error_description": "“环球一周”中的“一周”指绕一圈，是固定的动量说法，中间不能加“个”；写成“环球一个周”是错误，应写“环球一周”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
