INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "环绕地球；整个地球。", "primary_collocate": null, "pronunciation": "huán qiú", "ipa": "xwan˧˥ tɕʰi̯ou˧˥", "syllable_count": 2, "sentences": [{"text": "他梦想有一天能去环球旅行。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的产品行销环球，很多国家都能买到。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船开始了一次环球航行。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在环球旅行中认识了很多朋友。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是一次环球旅行的故事。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸退休后，想和妈妈一起环球旅行。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环球航行需要很多钱和时间。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员完成了环球帆船比赛。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的环球旅行花了整整一年。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次环球旅行，我们去了二十个国家。", "target_word": "环球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "环球：环绕地球或指整个地球，常作定语，如环球旅行、环球各地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环球", "is_correct": true, "explanation": "正确答案：环球，指环绕地球或整个地球，修饰“旅行”。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“旅行”的对象是地方，不能说去早餐旅行。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是可以去旅行的地方。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能作为旅行的地点。"}], "explanations": {"环球": "正确答案：环球，指环绕地球或整个地球，修饰“旅行”。", "早餐": "搭配：“旅行”的对象是地方，不能说去早餐旅行。", "数学": "语义：数学是学科，不是可以去旅行的地方。", "冰箱": "语义：冰箱是家用电器，不能作为旅行的地点。"}, "sentence_index": 0, "correct_answer": "环球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "环球变暖让冰川越来越少。", "explanation": "这里应该用〈全球〉。环球指环绕地球或整个地球，但固定说法是“全球变暖”，不说“环球变暖”。"}, {"text": "他每天环球上学，走得很累。", "explanation": "环球指环绕整个地球，范围极大，不能用来形容每天上学走的路；这里应该说“走路上学”。"}, {"text": "我的书桌上放着一个环球，我常常看它。", "explanation": "环球指环绕地球或整个地球，不指地球仪这样的实物；地球仪要说地球仪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环球", "is_correct": true, "explanation": "正确答案：环球，修饰“航行”，指环绕地球的航行。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，不能用来修饰“航行”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是航行的方式或范围，不能修饰“航行”。"}, {"text": "海盗", "is_correct": false, "explanation": "搭配：“海盗”指盗贼，不说海盗航行这样的组合。"}], "explanations": {"环球": "正确答案：环球，修饰“航行”，指环绕地球的航行。", "电视": "语义：电视是家用电器，不能用来修饰“航行”。", "窗户": "语义：窗户不是航行的方式或范围，不能修饰“航行”。", "海盗": "搭配：“海盗”指盗贼，不说海盗航行这样的组合。"}, "sentence_index": 6, "correct_answer": "环球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小镇位于环球的东部。", "explanation": "这里应该用〈地区〉。环球指整个地球，不能用来指一个小镇所在的范围；小镇所在的范围要说地区。"}, {"text": "他把一个环球放进了书包，准备出发。", "explanation": "这里应该用〈地球仪〉。环球指环绕地球或整个地球，不指能放进书包的实物；地球仪是模型，要说地球仪。"}, {"text": "这是一座环球级的博物馆，每年有很多游客。", "explanation": "这里应该用〈世界级〉。环球指环绕地球，不能作为级别的修饰语，这里要说世界级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一环球航行中见到了很多海鸟。", "corrected_sentence": "我们在一次环球航行中见到了很多海鸟。", "error_description": "“一次环球航行”中，“一”后必须有量词“次”，应写作“一次环球航行”；漏掉“次”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他完成了一只环球旅行。", "corrected_sentence": "他完成了一次环球旅行。", "error_description": "量词错误：“旅行”是可以计次的活动，应搭配量词“次”；“只”多用于动物或成对物件中的一个，不能修饰“旅行”，应写“一次环球旅行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
