INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装水或饮料的容器，口小肚子大。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这个瓶里有水，你喝吧。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的瓶忘在教室了，没有水喝。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶很轻，可以带去学校。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从包里拿出一个瓶，喝了几口水。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶是塑料做的，不会碎。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝完饮料后，请把瓶放进回收箱。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶里的果汁是冰的，很好喝。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶太小了，装不下一升水。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友用瓶装满了水，去浇花。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶在瓶里，放进冰箱就不会坏。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶子", "label": "复合"}, {"form": "水瓶", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "瓶：装水、果汁等饮料的容器，口小肚子大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瓶", "is_correct": true, "explanation": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。"}, {"text": "迎", "is_correct": false, "explanation": "yíng（第二声）与 píng 声母不同（y/p），意思是迎接。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 píng 声母不同（x/p），意思是形状。"}, {"text": "宁", "is_correct": false, "explanation": "níng（第二声）与 píng 声母不同（n/p），意思是安宁。"}, {"text": "频", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（n/ng），意思是频繁。"}], "explanations": {"瓶": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。", "迎": "yíng（第二声）与 píng 声母不同（y/p），意思是迎接。", "形": "xíng（第二声）与 píng 声母不同（x/p），意思是形状。", "宁": "níng（第二声）与 píng 声母不同（n/p），意思是安宁。", "频": "pín（第二声）与 píng 韵母不同（n/ng），意思是频繁。"}, "sentence_index": null, "correct_answer": "瓶"}, "level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本不是容器，里面不会有水，“这个课本里有水”说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是容器，里面不会有水。"}, {"text": "瓶", "is_correct": true, "explanation": "正确。“瓶”是装水的容器，“这个瓶里有水，你喝吧”成立。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是容器，里面不会有水。"}], "explanations": {"课本": "语义：课本不是容器，里面不会有水，“这个课本里有水”说不通。", "椅子": "语义：椅子不是容器，里面不会有水。", "瓶": "正确。“瓶”是装水的容器，“这个瓶里有水，你喝吧”成立。", "黑板": "语义：黑板不是容器，里面不会有水。"}, "sentence_index": 0, "correct_answer": "瓶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用瓶切菜。", "explanation": "这里应该用〈菜刀〉。瓶是装水或饮料的容器，不能用来切菜。"}, {"text": "妈妈把衣服放进瓶里洗。", "explanation": "这里应该用〈盆〉。瓶口小，不能用来洗衣服。"}, {"text": "他累了，坐在瓶上休息。", "explanation": "这里应该用〈椅子〉。瓶是装水或饮料的容器，不能坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瓶", "is_correct": true, "explanation": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 píng 声母不同（m/p），意思是明亮。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 píng 声母不同（l/p），意思是零。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 píng 声母不同（t/p），意思是停止。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 píng 声母不同（q/p），意思是感情。"}], "explanations": {"瓶": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。", "明": "míng（第二声）与 píng 声母不同（m/p），意思是明亮。", "零": "líng（第二声）与 píng 声母不同（l/p），意思是零。", "停": "tíng（第二声）与 píng 声母不同（t/p），意思是停止。", "情": "qíng（第二声）与 píng 声母不同（q/p），意思是感情。"}, "sentence_index": null, "correct_answer": "瓶"}, "level_3": {"options": [{"text": "河", "is_correct": false, "explanation": "语义：河里不能装果汁给人喝，“河里的果汁”说不通。"}, {"text": "盆", "is_correct": false, "explanation": "搭配：盆多用于种花或洗东西，不说“盆里的果汁”。"}, {"text": "瓶", "is_correct": true, "explanation": "正确。“瓶里的果汁是冰的，很好喝”，“瓶”指装饮料的容器。"}, {"text": "池子", "is_correct": false, "explanation": "语义：池子是大型的水池，不是盛饮料的容器，“池子里的果汁”说不通。"}], "explanations": {"河": "语义：河里不能装果汁给人喝，“河里的果汁”说不通。", "盆": "搭配：盆多用于种花或洗东西，不说“盆里的果汁”。", "瓶": "正确。“瓶里的果汁是冰的，很好喝”，“瓶”指装饮料的容器。", "池子": "语义：池子是大型的水池，不是盛饮料的容器，“池子里的果汁”说不通。"}, "sentence_index": 6, "correct_answer": "瓶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用瓶煮粥。", "explanation": "这里应该用〈锅〉。瓶口小、不能加热，煮粥要用锅。"}, {"text": "他用瓶擦桌子。", "explanation": "这里应该用〈抹布〉。瓶是盛放液体的容器，不能用来擦东西。"}, {"text": "她用瓶扫地。", "explanation": "这里应该用〈扫帚〉。瓶是装液体的容器，不能用来扫地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
