INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不小心把瓶摔了碎。", "corrected_sentence": "他不小心把瓶摔碎了。", "error_description": "补语错误：“摔碎”是动补结构，“碎”要紧跟“摔”，“了”放在最后，应说“摔碎了”，不能说“摔了碎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
