INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "口小、颈长、腹大的容器。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "桌上的瓶很漂亮，里面插着花。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶，口小颈长，肚子很大。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把玫瑰花插进瓶里。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶里的花开了，屋子里很香。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷收藏了一个老瓶，上面画着花。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别碰倒桌上那个瓶。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶是白色的，上面画着一只鸟。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给妈妈买了一个大瓶，用来插花。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶很高，放在窗边正好。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换花的时候，瓶不小心摔在地上，碎了一地。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶子", "label": "复合"}, {"form": "花瓶", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "瓶：口小、颈长、腹大的容器，常用来插花或摆放装饰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瓶", "is_correct": true, "explanation": "正确。瓶 píng 指口小、颈长、腹大的容器。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 píng 声母不同（m/p），意思是明亮。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 píng 声母不同（l/p），意思是零。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 píng 声母不同（t/p），意思是停止。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 píng 声母不同（q/p），意思是感情。"}, {"text": "贫", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（n/ng），意思是贫穷。"}], "explanations": {"瓶": "正确。瓶 píng 指口小、颈长、腹大的容器。", "明": "míng（第二声）与 píng 声母不同（m/p），意思是明亮。", "零": "líng（第二声）与 píng 声母不同（l/p），意思是零。", "停": "tíng（第二声）与 píng 声母不同（t/p），意思是停止。", "情": "qíng（第二声）与 píng 声母不同（q/p），意思是感情。", "贫": "pín（第二声）与 píng 韵母不同（n/ng），意思是贫穷。"}, "sentence_index": null, "correct_answer": "瓶"}, "level_3": {"options": [{"text": "瓶", "is_correct": true, "explanation": "正确。“瓶”指口小肚大的容器，可以用来插花。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能插花，“桌上的课本很漂亮，里面插着花”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌上的桌子”说不通，桌子里也插不了花。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能摆在桌上，“桌上的花园”不合逻辑。"}], "explanations": {"瓶": "正确。“瓶”指口小肚大的容器，可以用来插花。", "课本": "语义：课本不能插花，“桌上的课本很漂亮，里面插着花”说不通。", "桌子": "语义：“桌上的桌子”说不通，桌子里也插不了花。", "花园": "语义：花园不能摆在桌上，“桌上的花园”不合逻辑。"}, "sentence_index": 0, "correct_answer": "瓶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把蛋糕装进瓶里端上桌。", "explanation": "这里应该用〈盘子〉。瓶口小、腹大，装固体的蛋糕要用盘子。"}, {"text": "妈妈盛了一瓶饭给我。", "explanation": "这里应该用〈碗〉。瓶用来装液体或插花，盛饭要用碗。"}, {"text": "妈妈用瓶煮饭。", "explanation": "这里应该用〈锅〉。瓶口小、不能加热，煮饭要用锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96976, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瓶", "is_correct": true, "explanation": "正确。瓶 píng 指口小、颈长、腹大的容器。"}, {"text": "迎", "is_correct": false, "explanation": "yíng（第二声）与 píng 声母不同（y/p），意思是迎接。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 píng 声母不同（x/p），意思是形状。"}, {"text": "宁", "is_correct": false, "explanation": "níng（第二声）与 píng 声母不同（n/p），意思是安宁。"}, {"text": "频", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（n/ng），意思是频繁。"}], "explanations": {"瓶": "正确。瓶 píng 指口小、颈长、腹大的容器。", "迎": "yíng（第二声）与 píng 声母不同（y/p），意思是迎接。", "形": "xíng（第二声）与 píng 声母不同（x/p），意思是形状。", "宁": "níng（第二声）与 píng 声母不同（n/p），意思是安宁。", "频": "pín（第二声）与 píng 韵母不同（n/ng），意思是频繁。"}, "sentence_index": null, "correct_answer": "瓶"}, "level_3": {"options": [{"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，不能在上面画一只鸟。"}, {"text": "瓶", "is_correct": true, "explanation": "正确。“瓶”是可以画上图案的容器，“这个瓶是白色的”成立。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，一般不说“这个空气”，也画不了鸟。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是流动的水，不能在它上面画画。"}], "explanations": {"云": "语义：云是天上的水汽，不能在上面画一只鸟。", "瓶": "正确。“瓶”是可以画上图案的容器，“这个瓶是白色的”成立。", "空气": "搭配：“空气”是不可数名词，一般不说“这个空气”，也画不了鸟。", "河": "语义：河是流动的水，不能在它上面画画。"}, "sentence_index": 6, "correct_answer": "瓶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把衣服放进瓶里洗。", "explanation": "这里应该用〈盆〉。瓶口小，不能用来洗衣服。"}, {"text": "他用瓶擦干净了桌子。", "explanation": "这里应该用〈抹布〉。瓶是盛放东西的容器，不能用来擦桌子。"}, {"text": "她提着一瓶水果去看朋友。", "explanation": "这里应该用〈篮子〉。瓶用来装液体，装水果要用篮子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了一根瓶，放在厨房窗台上。", "corrected_sentence": "妈妈买了一个瓶，放在厨房窗台上。", "error_description": "量词错误：“瓶”应用量词“个”，说“一个瓶”；“根”用于细长的东西，不能用于瓶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给妈妈买了一个大瓶，把花插进瓶上。", "corrected_sentence": "我给妈妈买了一个大瓶，把花插进瓶里。", "error_description": "方位词错误：花是插到瓶的里面，应说“插进瓶里”，不能说“插进瓶上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
