INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96977, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男孩子或男人。", "primary_collocate": null, "pronunciation": "nán de", "ipa": "nan˧˥ tɤ", "syllable_count": 2, "sentences": [{"text": "门口站着一个男的，他在等人。", "target_word": "男的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男的是我的新同事。", "target_word": "男的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们班有个男的，每天最早到教室。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话里是个男的，不是我妈妈。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "穿红衣服的那个男的是谁？", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面走来一个男的，手里拿着花。", "target_word": "男的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男的帮我提了行李。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车上坐着两个男的和一个女孩。", "target_word": "男的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男的每天骑车上班。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片上的男的是我爸爸。", "target_word": "男的", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "男的：指某个具体的男孩子或男人，口语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男的", "is_correct": true, "explanation": "正确：“男的”指男性，与“他”一致，可以站在门口等人。"}, {"text": "女孩", "is_correct": false, "explanation": "语义：“女孩”是女性，与后文的“他”不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“站着”和“等人”要求有生命的主语，“石头”不能等人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不能“站着”，也不能“等人”。"}], "explanations": {"男的": "正确：“男的”指男性，与“他”一致，可以站在门口等人。", "女孩": "语义：“女孩”是女性，与后文的“他”不符。", "石头": "搭配：“站着”和“等人”要求有生命的主语，“石头”不能等人。", "桌子": "搭配：“桌子”不能“站着”，也不能“等人”。"}, "sentence_index": 0, "correct_answer": "男的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身上有一股很浓的男的味。", "explanation": "这里应该用〈男人〉。“男人味”是固定说法，“男的”不能这样组合。"}, {"text": "各位男的，欢迎来到我们的讲座。", "explanation": "这里应该用〈男士〉。“男的”是口语，正式场合称呼“各位男的”不合适。"}, {"text": "我们学校的男的宿舍在北边。", "explanation": "这里应该用〈男生〉。“男生宿舍”是固定说法，“男的宿舍”不用于学校宿舍的名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男的", "is_correct": true, "explanation": "正确：“男的”指男人，能够“帮我提了行李”。"}, {"text": "空调", "is_correct": false, "explanation": "语义：“空调”不能施动“帮我提了行李”这个动作。"}, {"text": "行李箱", "is_correct": false, "explanation": "搭配：“帮我提行李”的主语须是人，“行李箱”是被提的东西。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”不是人，不能“帮”人提行李。"}], "explanations": {"男的": "正确：“男的”指男人，能够“帮我提了行李”。", "空调": "语义：“空调”不能施动“帮我提了行李”这个动作。", "行李箱": "搭配：“帮我提行李”的主语须是人，“行李箱”是被提的东西。", "电梯": "语义：“电梯”不是人，不能“帮”人提行李。"}, "sentence_index": 6, "correct_answer": "男的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很有男的气概。", "explanation": "这里应该用〈男子〉。“男子气概”是固定说法，“男的气概”不能这样说。"}, {"text": "这次调查显示，男的占比超过六成。", "explanation": "这里应该用〈男性〉。统计报告用“男性占比”，“男的”是口语，不用于书面调查。"}, {"text": "这场男的单打比赛很精彩。", "explanation": "这里应该用〈男子〉。“男子单打”是固定说法，“男的单打”不这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天在超市门口遇到了一只男的。", "corrected_sentence": "他昨天在超市门口遇到了一个男的。", "error_description": "量词错误：指人的“男的”应搭配量词“个”，“只”多用于动物。正确说法是“一个男的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站那个男刚才问路了。", "corrected_sentence": "车站那个男的刚才问路了。", "error_description": "助词错误：指人的“男的”不能省略“的”，“那个男”单用不成词，应说“那个男的”，不能说“那个男”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
