INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男性；男人。", "primary_collocate": null, "pronunciation": "nán de", "ipa": "nan˧˥ tɤ", "syllable_count": 2, "sentences": [{"text": "男的一般比女的高。", "target_word": "男的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的衣服是给男的穿的。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报名的人里，男的比女的多。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "男的和女的都可以参加这个比赛。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗手间分男的和女的。", "target_word": "男的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本杂志的读者大多是男的。", "target_word": "男的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们公司，男的不多。", "target_word": "男的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个游戏男的女的都喜欢玩。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，男的更容易得这种病。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想找一个会做饭的男的。", "target_word": "男的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "男的：泛指男性、男人，与女的相对，口语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男的", "is_correct": true, "explanation": "正确：“男的”指男性，可以与“女的”比较身高。"}, {"text": "女的", "is_correct": false, "explanation": "语义：“女的”与“比女的高”的比较对象同类，句子自相矛盾。"}, {"text": "女孩", "is_correct": false, "explanation": "语义：“女孩”也是女性，与“比女的高”的比较对象性别相同，不成立。"}, {"text": "矮子", "is_correct": false, "explanation": "体貌：“矮子”的“矮”与后文的“高”相矛盾。"}], "explanations": {"男的": "正确：“男的”指男性，可以与“女的”比较身高。", "女的": "语义：“女的”与“比女的高”的比较对象同类，句子自相矛盾。", "女孩": "语义：“女孩”也是女性，与“比女的高”的比较对象性别相同，不成立。", "矮子": "体貌：“矮子”的“矮”与后文的“高”相矛盾。"}, "sentence_index": 0, "correct_answer": "男的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场男的单打比赛很精彩。", "explanation": "这里应该用〈男子〉。“男子单打”是固定说法，“男的单打”不这样说。"}, {"text": "他从头到尾都透着一股男的味。", "explanation": "这里应该用〈男人〉。“男人味”是固定说法，“男的味”不成词。"}, {"text": "这位歌手的男的高音非常动人。", "explanation": "这里应该用〈男高音〉。“男高音”是声乐术语，“男的高音”不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男的", "is_correct": true, "explanation": "正确：“男的”是公司里的人，可以说“不多”。"}, {"text": "恐龙", "is_correct": false, "explanation": "语义：恐龙早已灭绝，不可能在公司里，与“在我们公司”不合。"}, {"text": "熊猫", "is_correct": false, "explanation": "语义：“熊猫”不是人，不能说“在我们公司……不多”。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是时间，不是人，不能说公司里“昨天不多”。"}], "explanations": {"男的": "正确：“男的”是公司里的人，可以说“不多”。", "恐龙": "语义：恐龙早已灭绝，不可能在公司里，与“在我们公司”不合。", "熊猫": "语义：“熊猫”不是人，不能说“在我们公司……不多”。", "昨天": "语义：“昨天”是时间，不是人，不能说公司里“昨天不多”。"}, "sentence_index": 6, "correct_answer": "男的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的男的宿舍在北边。", "explanation": "这里应该用〈男生〉。“男生宿舍”是固定说法，“男的宿舍”不用于学校宿舍的名称。"}, {"text": "尊敬的男的顾客，请您按顺序排队。", "explanation": "这里应该用〈男士〉。“尊敬的男士”是正式称呼，“男的”是口语，用在这种通知里不合适。"}, {"text": "她想找一个很有男的气概的人。", "explanation": "这里应该用〈男子〉。“男子气概”是固定说法，“男的气概”不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司里那个男很会唱歌。", "corrected_sentence": "公司里那个男的很会唱歌。", "error_description": "助词错误：指人的“男的”不能省略“的”，“那个男”单用不成词，应说“那个男的”，不能说“那个男”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天在超市遇到了一只男的。", "corrected_sentence": "她昨天在超市遇到了一个男的。", "error_description": "量词错误：指人的“男的”应搭配量词“个”，“只”多用于动物。正确说法是“一个男的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
