INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96979, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "读了很多书，有学问的人。", "primary_collocate": null, "pronunciation": "zhī shi fèn zǐ", "ipa": "ʈʂɻ̩˥ ʂɻ̩ fən˥˩ tsɨ˨˩˦", "syllable_count": 4, "sentences": [{"text": "爷爷家里有很多书，大家都说他是个知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话慢，戴着眼镜，像个知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的老先生读了一辈子书，是有名的知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁给了一位爱读书的知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位知识分子对历史和哲学都很了解。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一看就是个知识分子，说话很有道理。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个知识分子每天在图书馆看书，一待就是一天。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老知识分子们坐在茶馆里谈论古书。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然没有钱，但是大家都尊敬他这个知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在小说里，作者写了一个爱看书的知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "知識分子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "知识分子：读书多、有学问、有文化修养的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知识分子", "is_correct": true, "explanation": "正确：“家里有很多书”与“读书多、有学问”的意思相符，放入空格后语义通顺。"}, {"text": "文盲", "is_correct": false, "explanation": "语义：“文盲”指不识字的人，与“家里有很多书”的语境直接矛盾。"}, {"text": "厨子", "is_correct": false, "explanation": "语义：“厨子”指做饭的人，与“读书多、有学问”的评价无关，句中语境不支持。"}, {"text": "大老粗", "is_correct": false, "explanation": "语义：“大老粗”是口语说法，指没有文化的粗人，与“家里有很多书”的语境相悖。"}], "explanations": {"知识分子": "正确：“家里有很多书”与“读书多、有学问”的意思相符，放入空格后语义通顺。", "文盲": "语义：“文盲”指不识字的人，与“家里有很多书”的语境直接矛盾。", "厨子": "语义：“厨子”指做饭的人，与“读书多、有学问”的评价无关，句中语境不支持。", "大老粗": "语义：“大老粗”是口语说法，指没有文化的粗人，与“家里有很多书”的语境相悖。"}, "sentence_index": 0, "correct_answer": "知识分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家来了一座知识分子。", "explanation": "这里应该用〈位〉或〈个〉。〈座〉用于山、楼房等大件，不用于指人。"}, {"text": "她很有知识分子，每天都读书。", "explanation": "这里应该用〈学问〉。“很有”后接抽象属性，如“很有学问”，“知识分子”指人，不能说“很有知识分子”。"}, {"text": "这瓶药里含有很多知识分子。", "explanation": "这里应该用〈成分〉。“知识分子”指人，不能用来指药物中的化学物质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知识分子", "is_correct": true, "explanation": "正确：“每天在图书馆看书，一待就是一天”正是读书人的做法，符合语境。"}, {"text": "屠夫", "is_correct": false, "explanation": "语义：“屠夫”以宰杀为业，与“在图书馆看书”不相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”主要从事农业劳动，与“在图书馆看书，一待就是一天”的语境不符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”以做饭为业，与“每天在图书馆看书，一待就是一天”的语境不符。"}], "explanations": {"知识分子": "正确：“每天在图书馆看书，一待就是一天”正是读书人的做法，符合语境。", "屠夫": "语义：“屠夫”以宰杀为业，与“在图书馆看书”不相符。", "农民": "语义：“农民”主要从事农业劳动，与“在图书馆看书，一待就是一天”的语境不符。", "厨师": "语义：“厨师”以做饭为业，与“每天在图书馆看书，一待就是一天”的语境不符。"}, "sentence_index": 6, "correct_answer": "知识分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗很聪明，村里人都叫它知识分子。", "explanation": "这里应该用〈宠物〉。“知识分子”指读书多、有学问的人，不能用来称呼动物。"}, {"text": "他学到了很多知识分子，考试考得很好。", "explanation": "这里应该用〈知识〉。学到的是知识，“知识分子”指人，不能说学到了“知识分子”。"}, {"text": "这本书写得很好，是一位知识分子。", "explanation": "这里应该用〈作品〉。“知识分子”只指人，不能用来形容书籍等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一位爱看书地知识分子。", "corrected_sentence": "他是一位爱看书的知识分子。", "error_description": "结构助词错误：修饰名词应用“的”，“地”用于修饰动词，不能用在“知识分子”前。正确说法是“爱看书的知识分子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头知识分子每天都在图书馆待到很晚。", "corrected_sentence": "这位知识分子每天都在图书馆待到很晚。", "error_description": "量词错误：指人应用“位”，“头”用于牛、羊等动物，不能修饰“知识分子”。正确说法是“这位知识分子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
