INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受过较高教育、从事脑力劳动的人。", "primary_collocate": null, "pronunciation": "zhī shi fèn zǐ", "ipa": "ʈʂɻ̩˥ ʂɻ̩ fən˥˩ tsɨ˨˩˦", "syllable_count": 4, "sentences": [{"text": "他父亲是一位大学教授，也是知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生、老师和工程师都属于知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多知识分子，大家都在研究所工作。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要更多从事科学研究的知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知识分子的工作主要靠脑力，不是体力。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在一个知识分子家庭。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几位知识分子在报社写文章，也教书。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多知识分子毕业后留在大学做研究。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业后在研究所工作，是一名知识分子。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府很重视知识分子的意见。", "target_word": "知识分子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "知識分子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "知识分子：受过较高教育、从事脑力劳动的社会群体，如教师、医生、工程师", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知识分子", "is_correct": true, "explanation": "正确：“大学教授”属于脑力劳动者，与“知识分子”的定义相符，放入空格后语义通顺。"}, {"text": "文盲", "is_correct": false, "explanation": "语义：“文盲”指不识字的人，与“大学教授”的身份相矛盾，句子不成立。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：“小学生”指正在读小学的孩子，不能与“大学教授”并列为父亲的身份。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”指刚出生不久的孩子，不可能同时是“大学教授”，句子不成立。"}], "explanations": {"知识分子": "正确：“大学教授”属于脑力劳动者，与“知识分子”的定义相符，放入空格后语义通顺。", "文盲": "语义：“文盲”指不识字的人，与“大学教授”的身份相矛盾，句子不成立。", "小学生": "语义：“小学生”指正在读小学的孩子，不能与“大学教授”并列为父亲的身份。", "婴儿": "语义：“婴儿”指刚出生不久的孩子，不可能同时是“大学教授”，句子不成立。"}, "sentence_index": 0, "correct_answer": "知识分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校新来了一只知识分子。", "explanation": "这里应该用〈位〉或〈个〉。〈只〉多用于动物，不用于指人的知识分子。"}, {"text": "他学会了很多知识分子。", "explanation": "这里应该用〈知识〉。“学会”的对象是知识，“知识分子”指人，不能当作知识来学。"}, {"text": "这杯水里有很多知识分子。", "explanation": "这里应该用〈微粒〉。“知识分子”只指人，不能用来指水中的物质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知识分子", "is_correct": true, "explanation": "正确：“写文章”和“教书”都是脑力工作，与“那几位”的身份相符。"}, {"text": "工人", "is_correct": false, "explanation": "语义：“工人”以体力劳动为主，与“在报社写文章”不相符。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“厨师”与“写文章、教书”搭配不当，句中没有语境能支持这种身份。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”主要职责是驾驶车辆，与“写文章”和“教书”毫无关联。"}], "explanations": {"知识分子": "正确：“写文章”和“教书”都是脑力工作，与“那几位”的身份相符。", "工人": "语义：“工人”以体力劳动为主，与“在报社写文章”不相符。", "厨师": "搭配：“厨师”与“写文章、教书”搭配不当，句中没有语境能支持这种身份。", "司机": "语义：“司机”主要职责是驾驶车辆，与“写文章”和“教书”毫无关联。"}, "sentence_index": 6, "correct_answer": "知识分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这匹马很聪明，大家都说它是一位知识分子。", "explanation": "这里应该用〈动物〉。“知识分子”指受过较高教育、从事脑力劳动的人，不能用来称呼动物。"}, {"text": "她很有知识分子，懂得很多道理。", "explanation": "这里应该用〈学问〉。“很有”后接“学问”这类抽象属性，“知识分子”指人，不能说“很有知识分子”。"}, {"text": "这把椅子很舒服，是一位知识分子。", "explanation": "这里应该用〈家具〉。“知识分子”只指人，不能用来称呼物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人年轻时是一条知识分子。", "corrected_sentence": "这位老人年轻时是一名知识分子。", "error_description": "量词错误：指人应用“名”或“位”，“条”用于长条形的东西，不能修饰“知识分子”。正确说法是“一名知识分子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的很多条知识分子都在研究所工作。", "corrected_sentence": "这个城市的很多知识分子都在研究所工作。", "error_description": "量词错误：“知识分子”指人，不能用量词“条”（“条”用于长条形的东西）。“很多”后直接接名词即可，正确说法是“很多知识分子”，去掉“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
