INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96981, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一点一点地堆起来，越来越多。", "primary_collocate": null, "pronunciation": "jī", "ipa": "tɕi˥", "syllable_count": 1, "sentences": [{"text": "桌子上积了很多灰。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上积了一层雪。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下了三天，院子里积满了水。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把零钱一点一点积起来。", "target_word": "积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架很久没人用，上面积着一层灰。", "target_word": "积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的水越积越多，车开不过去了。", "target_word": "积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗台上积了灰，你该擦一擦了。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的雪积了一个冬天。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不乱花钱，每个月都积下一点钱。", "target_word": "积", "complexity_tier": "T3", "furigana": "tā bú luàn huā qián，měi gè yuè dōu jī xià yì diǎn qián。", "sentence_source": "generated"}, {"text": "屋顶上的雪积得太厚，爸爸上去把它扫掉了。", "target_word": "积", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "积了", "label": "体标"}, {"form": "积着", "label": "体标"}], "register": "通用", "sense_fingerprint": "动词：灰、雪、水、钱等一点一点堆起来变多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96981, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积（jī，第一声），指一点一点堆起来、越来越多。"}, {"text": "急", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是着急、迅速。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是挤压、拥挤。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是记住、记录。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jī 只差韵尾 n，意思是金子。"}, {"text": "精", "is_correct": false, "explanation": "jīng 与 jī 只差韵尾 ng，意思是精华、精神。"}], "explanations": {"积": "正确：积（jī，第一声），指一点一点堆起来、越来越多。", "急": "jí（第二声）与 jī（第一声）声调不同，意思是着急、迅速。", "挤": "jǐ（第三声）与 jī（第一声）声调不同，意思是挤压、拥挤。", "记": "jì（第四声）与 jī（第一声）声调不同，意思是记住、记录。", "金": "jīn 与 jī 只差韵尾 n，意思是金子。", "精": "jīng 与 jī 只差韵尾 ng，意思是精华、精神。"}, "sentence_index": null, "correct_answer": "积"}, "level_3": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积指灰一点一点堆起来、越来越多，与“很多灰”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能说喝灰。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语须是歌曲，不能说唱灰。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热做饭，桌子上的灰不能煮，句意不通。"}], "explanations": {"积": "正确：积指灰一点一点堆起来、越来越多，与“很多灰”搭配。", "喝": "搭配：“喝”的对象是饮料，不能说喝灰。", "唱": "配价：“唱”的宾语须是歌曲，不能说唱灰。", "煮": "语义：“煮”指加热做饭，桌子上的灰不能煮，句意不通。"}, "sentence_index": 0, "correct_answer": "积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一车石头积在门口。", "explanation": "这里应该用〈堆〉。积强调东西一点一点越积越多，一车石头一次搬来，要用堆。"}, {"text": "会场里积满了人，连过道上都站着人。", "explanation": "这里应该用〈挤〉。积指东西、情绪、事务逐渐累积，不用来指人群；人群挤在一起要用挤。"}, {"text": "他一次就积够了买车的钱。", "explanation": "这里应该用〈攒〉。积强调一点一点累积，与“一次就”矛盾；存钱、凑钱要用攒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96981, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积（jī，第一声），指一点一点堆起来、越来越多。"}, {"text": "极", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是极端、非常。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是自己。"}, {"text": "继", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是继续、继承。"}, {"text": "今", "is_correct": false, "explanation": "jīn 与 jī 只差韵尾 n，意思是现在、今天。"}, {"text": "经", "is_correct": false, "explanation": "jīng 与 jī 只差韵尾 ng，意思是经过、经验。"}], "explanations": {"积": "正确：积（jī，第一声），指一点一点堆起来、越来越多。", "极": "jí（第二声）与 jī（第一声）声调不同，意思是极端、非常。", "己": "jǐ（第三声）与 jī（第一声）声调不同，意思是自己。", "继": "jì（第四声）与 jī（第一声）声调不同，意思是继续、继承。", "今": "jīn 与 jī 只差韵尾 n，意思是现在、今天。", "经": "jīng 与 jī 只差韵尾 ng，意思是经过、经验。"}, "sentence_index": null, "correct_answer": "积"}, "level_3": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积，灰一点一点落在窗台上并越积越多，与“该擦一擦了”相符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”用于悬挂物品，灰不能挂在窗台上。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”指咀嚼食物，窗台上的灰不能嚼，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象是能咬的东西，不能说咬灰。"}], "explanations": {"积": "正确：积，灰一点一点落在窗台上并越积越多，与“该擦一擦了”相符。", "挂": "搭配：“挂”用于悬挂物品，灰不能挂在窗台上。", "嚼": "语义：“嚼”指咀嚼食物，窗台上的灰不能嚼，句意不通。", "咬": "搭配：“咬”的对象是能咬的东西，不能说咬灰。"}, "sentence_index": 6, "correct_answer": "积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一下子积了一个月的米，以防万一。", "explanation": "这里应该用〈囤〉。积指东西一点一点累积，与“一下子”矛盾；大量买下储存要用囤。"}, {"text": "他把碗筷都积进了柜子里。", "explanation": "这里应该用〈装〉。积指东西逐渐聚集、累积，不指把东西放进容器；放进柜子要用装。"}, {"text": "他短短一天内就积够了学费。", "explanation": "这里应该用〈凑〉。积是慢慢累积，不能与“短短一天内”搭配；临时凑齐要用凑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里积了满落叶。", "corrected_sentence": "院子里积满了落叶。", "error_description": "错误：“积了满”。正确：“积满了”。“满”是结果补语，要紧跟“积”，“了”放在补语之后表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水池底积很厚了。", "corrected_sentence": "水池底积得很厚了。", "error_description": "错误：漏掉补语前的“得”。正确：“积得很厚”。积后接程度补语时要用“得”，不能直接说“积很厚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
