INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚集；累积。", "primary_collocate": null, "pronunciation": "jī", "ipa": "tɕi˥", "syllable_count": 1, "sentences": [{"text": "他心里积着一股怨气，一直没发出来。", "target_word": "积", "complexity_tier": "T3", "furigana": "tā xīn li jī zhe yì gǔ yuàn qì，yì zhí méi fā chū lái。", "sentence_source": "generated"}, {"text": "她积了一肚子气，一回家就哭了。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服太多，我一星期没洗，都积在那儿了。", "target_word": "积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的事没做完，下个月又积了很多。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多小问题积在一起，就成了大问题。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家的不满积了很久，终于说了出来。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没回的邮件都积在邮箱里。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业不及时做，很快就会积一大堆。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作一多，问题就积起来了。", "target_word": "积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她心里积了很多委屈，一直没告诉别人。", "target_word": "积", "complexity_tier": "T3", "furigana": "tā xīn li jī le hěn duō wěi qu，yì zhí méi gào su bié rén。", "sentence_source": "generated"}], "morphological_forms": [{"form": "积了", "label": "体标"}, {"form": "积着", "label": "体标"}], "register": "通用", "sense_fingerprint": "动词：事情、情绪、东西聚在一处，不断累积", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96982, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积（jī，第一声），指事情、情绪、东西聚在一处不断累积。"}, {"text": "急", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是着急、迅速。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是挤压、拥挤。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是记住、记录。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jī 只差韵尾 n，意思是金子。"}, {"text": "精", "is_correct": false, "explanation": "jīng 与 jī 只差韵尾 ng，意思是精华、精神。"}], "explanations": {"积": "正确：积（jī，第一声），指事情、情绪、东西聚在一处不断累积。", "急": "jí（第二声）与 jī（第一声）声调不同，意思是着急、迅速。", "挤": "jǐ（第三声）与 jī（第一声）声调不同，意思是挤压、拥挤。", "记": "jì（第四声）与 jī（第一声）声调不同，意思是记住、记录。", "金": "jīn 与 jī 只差韵尾 n，意思是金子。", "精": "jīng 与 jī 只差韵尾 ng，意思是精华、精神。"}, "sentence_index": null, "correct_answer": "积"}, "level_3": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积，怨气长期累积在心里，与“一直没发出来”相符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动东西，心里不能搬着怨气，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等，不能说洗怨气。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，心里不能挖着怨气，句意不通。"}], "explanations": {"积": "正确：积，怨气长期累积在心里，与“一直没发出来”相符。", "搬": "语义：“搬”指移动东西，心里不能搬着怨气，句意不通。", "洗": "搭配：“洗”的对象是衣物等，不能说洗怨气。", "挖": "语义：“挖”指挖掘，心里不能挖着怨气，句意不通。"}, "sentence_index": 0, "correct_answer": "积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人太多，大家都积在一起。", "explanation": "这里应该用〈挤〉。积指事情、情绪、东西逐渐聚集，不用来指人；人群聚在一起要用挤。"}, {"text": "他把旧衣服都积进了箱子里。", "explanation": "这里应该用〈装〉。积指东西逐渐聚集、累积，不指把东西放进容器；装进箱子要用装。"}, {"text": "他心里的不满一下子积了出来。", "explanation": "这里应该用〈爆发〉。积是慢慢累积，与“一下子”矛盾；突然发作要用爆发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96982, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积（jī，第一声），指事情、情绪、东西聚在一处不断累积。"}, {"text": "极", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是极端、非常。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是自己。"}, {"text": "继", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是继续、继承。"}, {"text": "今", "is_correct": false, "explanation": "jīn 与 jī 只差韵尾 n，意思是现在、今天。"}, {"text": "经", "is_correct": false, "explanation": "jīng 与 jī 只差韵尾 ng，意思是经过、经验。"}], "explanations": {"积": "正确：积（jī，第一声），指事情、情绪、东西聚在一处不断累积。", "极": "jí（第二声）与 jī（第一声）声调不同，意思是极端、非常。", "己": "jǐ（第三声）与 jī（第一声）声调不同，意思是自己。", "继": "jì（第四声）与 jī（第一声）声调不同，意思是继续、继承。", "今": "jīn 与 jī 只差韵尾 n，意思是现在、今天。", "经": "jīng 与 jī 只差韵尾 ng，意思是经过、经验。"}, "sentence_index": null, "correct_answer": "积"}, "level_3": {"options": [{"text": "积", "is_correct": true, "explanation": "正确：积，没回的邮件越来越多，聚在邮箱里。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，邮件不能喝。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语是歌曲，邮件不能唱。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，邮件不能煮，句意不通。"}], "explanations": {"积": "正确：积，没回的邮件越来越多，聚在邮箱里。", "喝": "搭配：“喝”的对象是饮料，邮件不能喝。", "唱": "配价：“唱”的宾语是歌曲，邮件不能唱。", "煮": "语义：“煮”指加热食物，邮件不能煮，句意不通。"}, "sentence_index": 6, "correct_answer": "积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一车煤积在墙角。", "explanation": "这里应该用〈堆〉。积指东西一点一点聚集，一车煤一次运来，要用堆。"}, {"text": "她一下子积了很多旧书。", "explanation": "这里应该用〈收集〉。积是慢慢累积，与“一下子”矛盾；一次得到很多东西要用收集。"}, {"text": "她一次就积够了要交的费用。", "explanation": "这里应该用〈凑〉。积是慢慢累积，与“一次就”矛盾；临时凑齐要用凑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些不满慢慢积上来了，终于爆发。", "corrected_sentence": "这些不满慢慢积起来了，终于爆发。", "error_description": "错误：“积上来”。正确：“积起来”。“起来”表示慢慢聚集、形成，“上来”的方向不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上的文件积了着，没人处理。", "corrected_sentence": "桌上的文件积着，没人处理。", "error_description": "错误：“了”与“着”同用。正确：“积着”。表示持续的状态只用“着”，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
