INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96983, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在纸上写上名字，说好以后要这样做。", "primary_collocate": null, "pronunciation": "qiān yuē", "ipa": "tɕʰjɛn˥ yɛ˥", "syllable_count": 2, "sentences": [{"text": "我和房东今天下午签约。", "target_word": "签约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们明天去中介那儿签约，租房子。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想好了吗？想好了就签约吧。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房东说，只要你付钱，我们现在就能签约。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们签约以后，你一年都不能搬走。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王租房时，一直不愿意签约。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房东要我们三个人今天都来签约。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕麻烦，不想和房东签约。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈和健身房签约了，要练一年。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和教练签约，每周上三次课。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "签了约", "label": "体标"}, {"form": "签过约", "label": "体标"}], "register": "中性", "sense_fingerprint": "签约：日常中在纸上签名，约定以后照办（如租房、办卡）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "签约", "is_correct": true, "explanation": "正确：“签约”指与房东订立约定，符合句中的“和房东”。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是人的状态，不能与“和房东”一起做一件事。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指去学校读书，与房东和租房的事情不相关。"}, {"text": "租", "is_correct": false, "explanation": "配价：“租”是及物动词，后面需要宾语，句中缺少“租”的对象。"}], "explanations": {"签约": "正确：“签约”指与房东订立约定，符合句中的“和房东”。", "生病": "语义：“生病”是人的状态，不能与“和房东”一起做一件事。", "上学": "语义：“上学”指去学校读书，与房东和租房的事情不相关。", "租": "配价：“租”是及物动词，后面需要宾语，句中缺少“租”的对象。"}, "sentence_index": 0, "correct_answer": "签约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在收据上签了约。", "explanation": "这里应该用〈签字〉。收据只需签字确认，不是双方约定要照办的合约，不能说“签约”。"}, {"text": "明星在演唱会后给粉丝签约。", "explanation": "这里应该用〈签名〉。“签名”只是写下名字，不涉及约定，“签约”不能这样用。"}, {"text": "我在快递单上签约了。", "explanation": "这里应该用〈签收〉。“签收”指收到货物后签字确认，“签约”指双方约定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "签约", "is_correct": true, "explanation": "正确：租房要和房东签字约定，“房东要我们都来签约”语义通顺。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”是两个人之间的事，房东不会要三个人都来结婚。"}, {"text": "生孩子", "is_correct": false, "explanation": "语义：“生孩子”与房东和租房毫无关系，句意不通。"}, {"text": "打折", "is_correct": false, "explanation": "语义：“打折”指降低价格，是商家做的事，不能说人“来打折”。"}], "explanations": {"签约": "正确：租房要和房东签字约定，“房东要我们都来签约”语义通顺。", "结婚": "语义：“结婚”是两个人之间的事，房东不会要三个人都来结婚。", "生孩子": "语义：“生孩子”与房东和租房毫无关系，句意不通。", "打折": "语义：“打折”指降低价格，是商家做的事，不能说人“来打折”。"}, "sentence_index": 6, "correct_answer": "签约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护照由政府签约。", "explanation": "这里应该用〈签发〉。“签发”指官方发出证件，“签约”指双方约定，护照不能用“签约”。"}, {"text": "校长在学生的请假条上签约了。", "explanation": "这里应该用〈签批〉。“签批”指领导在公文上批示同意，“签约”指双方订立合约，请假条不是合约。"}, {"text": "我每天早上在门口签约。", "explanation": "这里应该用〈签到〉。“签到”指到场登记，不是订立合约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下周一去房东家签过约。", "corrected_sentence": "我们下周一去房东家签约。", "error_description": "体标错误：“过”表示已经经历过的动作，不能用于将来的“下周一”。正确说法是“签约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在办公室很签约，很顺利。", "corrected_sentence": "他们在办公室签约，很顺利。", "error_description": "程度副词错误：“很”不能直接修饰动词“签约”，应删去“很”，改为“他们在办公室签约，很顺利。”（“很顺利”中的“很”修饰形容词，没有问题。）", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
