INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96984, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方在合同上签字，订立合约。", "primary_collocate": null, "pronunciation": "qiān yuē", "ipa": "tɕʰjɛn˥ yɛ˥", "syllable_count": 2, "sentences": [{"text": "两家公司昨天在北京签约了。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位足球运动员和新球队签约了。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说，合同没问题，明天就可以签约。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司已经和他们签约了。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方谈了很久，终于签约了。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "签约的时候，两位老板都很高兴。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个歌手和唱片公司签约后，出了新歌。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们准备下个月和学校签约。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同还没写好，不能签约。", "target_word": "签约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂老板今天要和客户签约，所以很忙。", "target_word": "签约", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "签了约", "label": "体标"}, {"form": "签过约", "label": "体标"}, {"form": "签约仪式", "label": "复合"}], "register": "中性", "sense_fingerprint": "签约：双方在正式合同上签字，订立合约（公司、球队、歌手等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "签约", "is_correct": true, "explanation": "正确：“签约”指两家公司订立合同，与“两家公司”搭配。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是人的休闲活动，“两家公司”不能在北京“散步”，句子不成立。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指人或动物身体不适；用于“两家公司”时只是经营出问题的比喻，与“签约”无关，句子不成立。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：“上班”的主语须是个人，“两家公司”不能“上班”。"}], "explanations": {"签约": "正确：“签约”指两家公司订立合同，与“两家公司”搭配。", "散步": "语义：“散步”是人的休闲活动，“两家公司”不能在北京“散步”，句子不成立。", "生病": "语义：“生病”指人或动物身体不适；用于“两家公司”时只是经营出问题的比喻，与“签约”无关，句子不成立。", "上班": "搭配：“上班”的主语须是个人，“两家公司”不能“上班”。"}, "sentence_index": 0, "correct_answer": "签约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "球星打完比赛，给粉丝签约。", "explanation": "这里应该用〈签名〉。“签名”只是写下名字，不涉及合同，“签约”指订立合约。"}, {"text": "他每天早上都在前台签约。", "explanation": "这里应该用〈签到〉。“签到”指到场登记，不是订立合约。"}, {"text": "他在支票上签约了。", "explanation": "这里应该用〈签字〉。支票上只需签字，不需要订立合约，“签约”不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "签约", "is_correct": true, "explanation": "正确：“签约”指与唱片公司订立合约，与“后”组成先后关系。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是个人活动，不能与唱片公司构成先后动作。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指去学校读书，与唱片公司不相关。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”的主语须是上班的人，“唱片公司”不能“下班”。"}], "explanations": {"签约": "正确：“签约”指与唱片公司订立合约，与“后”组成先后关系。", "散步": "语义：“散步”是个人活动，不能与唱片公司构成先后动作。", "上学": "语义：“上学”指去学校读书，与唱片公司不相关。", "下班": "搭配：“下班”的主语须是上班的人，“唱片公司”不能“下班”。"}, "sentence_index": 6, "correct_answer": "签约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护照由政府签约。", "explanation": "这里应该用〈签发〉。“签发”指官方发出证件，“签约”指双方订立合约，护照不能用“签约”。"}, {"text": "我在快递单上签约了。", "explanation": "这里应该用〈签收〉。“签收”指收到货物后签字确认，“签约”指订立合约，快递单只需签收。"}, {"text": "领导在工作报告上签约了。", "explanation": "这里应该用〈签批〉。“签批”指领导在公文上批示同意，“签约”指双方订立合约，工作报告不是合约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家公司已经很签约了。", "corrected_sentence": "这两家公司已经签约了。", "error_description": "程度副词错误：“很”不能修饰动词“签约”，应删去“很”，改为“这两家公司已经签约了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们下个月准备签过约。", "corrected_sentence": "我们下个月准备签约。", "error_description": "体标错误：“过”表示已经发生过的经历，不能用于“下个月”的计划。正确说法是“准备签约”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
