INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96985, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把钱算清楚，该付的付掉。", "primary_collocate": null, "pronunciation": "jié suàn", "ipa": "tɕjɛ˧˥ swan˥˩", "syllable_count": 2, "sentences": [{"text": "客人走以前，要先结算房费。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到前台结算。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，我去柜台结算了。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板按天给工人结算工资。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买完东西，请到收银台结算。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们离开酒店时结算了所有费用。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机和客人当场结算了车费。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出院前你要先去窗口结算。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只能用手机结算。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经和房东结算了房租。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结算了", "label": "体标"}, {"form": "结算过", "label": "体标"}, {"form": "结算单", "label": "复合"}], "register": "中性", "sense_fingerprint": "算清费用并把该付的钱付掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结算", "is_correct": true, "explanation": "正确答案。结算指把钱算清楚并付掉，与“房费”和“离开以前”的语境相符。"}, {"text": "炒", "is_correct": false, "explanation": "搭配：“炒”不与“房费”搭配，不能说“炒房费”。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”与付费无关，“烤房费”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用于费用，“唱房费”说不通。"}], "explanations": {"结算": "正确答案。结算指把钱算清楚并付掉，与“房费”和“离开以前”的语境相符。", "炒": "搭配：“炒”不与“房费”搭配，不能说“炒房费”。", "烤": "语义：“烤”与付费无关，“烤房费”说不通。", "唱": "语义：“唱”不能用于费用，“唱房费”说不通。"}, "sentence_index": 0, "correct_answer": "结算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "保姆每天结算两个孩子。", "explanation": "这里应该用〈照顾〉。结算指算清费用，不能用来说照顾人。"}, {"text": "老板每天早上结算花园里的花。", "explanation": "这里应该用〈浇〉。结算指算清并付掉费用，不能用来说给花浇水。"}, {"text": "设计师每天结算新的房子。", "explanation": "这里应该用〈设计〉。结算与设计无关，不能用于房子的设计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结算", "is_correct": true, "explanation": "正确答案。结算指把车费算清楚并付掉，与“当场”的语境相符。"}, {"text": "修", "is_correct": false, "explanation": "语义：句中需要表示付钱的动词，“修了车费”不能表示把车费算清付掉，句意不通。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”与付款无关，“切车费”说不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”不与“车费”搭配，不能说“擦车费”。"}], "explanations": {"结算": "正确答案。结算指把车费算清楚并付掉，与“当场”的语境相符。", "修": "语义：句中需要表示付钱的动词，“修了车费”不能表示把车费算清付掉，句意不通。", "切": "语义：“切”与付款无关，“切车费”说不通。", "擦": "搭配：“擦”不与“车费”搭配，不能说“擦车费”。"}, "sentence_index": 6, "correct_answer": "结算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上结算一首小诗。", "explanation": "这里应该用〈朗读〉。结算指付清费用或算清账目，不能用来说朗读诗歌。"}, {"text": "他每天结算衣服。", "explanation": "这里应该用〈洗〉。结算指算清费用，不能用来说洗衣服。"}, {"text": "农民在田里结算菜。", "explanation": "这里应该用〈种〉。结算与种植无关，不能用来说种菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经把房费结算。", "corrected_sentence": "我们已经把房费结算了。", "error_description": "体标缺失：“把”字句的动词后需要“了”或其他补语，应说“我们已经把房费结算了”，不能只说“我们已经把房费结算”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下车后当场结算清晰了车费。", "corrected_sentence": "他下车后当场结算清楚了车费。", "error_description": "补语用词错误：车费算清用“清楚”，不用“清晰”。“清晰”多指视觉、声音或思路的清楚。应说“结算清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
