INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96986, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结清账目；计算清楚。", "primary_collocate": null, "pronunciation": "jié suàn", "ipa": "tɕjɛ˧˥ swan˥˩", "syllable_count": 2, "sentences": [{"text": "月底公司要结算这个月的账。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先结算一下今天的账目。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板每个星期结算一次。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财务正在结算这个月的收入。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "账目还没有结算清楚。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底我们要结算全年的账。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经结算完上个月的账了。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计每天晚上结算一次。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结算以后，我们发现少了一百块。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔账已经结算过了。", "target_word": "结算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结算了", "label": "体标"}, {"form": "结算过", "label": "体标"}, {"form": "结算单", "label": "复合"}], "register": "中性", "sense_fingerprint": "把一段时间的账目算清楚并结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结算", "is_correct": true, "explanation": "正确答案。结算指算清账目，与“这个月的账”相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉账目不是算清账目，与“账”的意思不符。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”不能与“账”搭配，不能说“种这个月的账”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与账目无关，“吃这个月的账”说不通。"}], "explanations": {"结算": "正确答案。结算指算清账目，与“这个月的账”相符。", "烧": "语义：烧掉账目不是算清账目，与“账”的意思不符。", "种": "搭配：“种”不能与“账”搭配，不能说“种这个月的账”。", "吃": "语义：“吃”与账目无关，“吃这个月的账”说不通。"}, "sentence_index": 0, "correct_answer": "结算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们花了一整天结算仓库里的箱子，把它们一个个搬上车。", "explanation": "这里应该用〈搬运〉。结算指算清账目或费用，不能用来指搬运箱子。"}, {"text": "他蹲下来，结算了一下松掉的鞋带。", "explanation": "这里应该用〈系〉。结算指算清账目或费用，不能用来说系鞋带。"}, {"text": "工人们每天早上结算教室。", "explanation": "这里应该用〈打扫〉。结算的对象是账目或费用，不能用来指打扫教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结算", "is_correct": true, "explanation": "正确答案。结算指算清账目，与“上个月的账”相符。"}, {"text": "绣", "is_correct": false, "explanation": "语义：绣花与账目无关，“绣完上个月的账”说不通。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”不与“账”搭配，不能说“织账”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮的对象是食物，不能用来处理账目。"}], "explanations": {"结算": "正确答案。结算指算清账目，与“上个月的账”相符。", "绣": "语义：绣花与账目无关，“绣完上个月的账”说不通。", "织": "搭配：“织”不与“账”搭配，不能说“织账”。", "煮": "语义：煮的对象是食物，不能用来处理账目。"}, "sentence_index": 6, "correct_answer": "结算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人结算好了坏掉的电视机。", "explanation": "这里应该用〈修理〉。结算用于账目和费用，不用于修理电器。"}, {"text": "会议因为下雨结算了一周。", "explanation": "这里应该用〈推迟〉。结算指算清账目，不能用来说日程延后。"}, {"text": "他结算好了书包。", "explanation": "这里应该用〈收拾〉。结算用于账目和费用，不用于整理物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "财务把这笔账结算。", "corrected_sentence": "财务把这笔账结算了。", "error_description": "体标缺失：“把”字句的动词后需要“了”或其他补语，应说“财务把这笔账结算了”，不能只说“财务把这笔账结算”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经把账结算清晰了。", "corrected_sentence": "他们已经把账结算清楚了。", "error_description": "补语用词错误：账目算清用“清楚”，不用“清晰”。“清晰”多指视觉、声音或思路的清楚。应说“结算清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
