INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对计算机网络进行监控、维护和配置的工作。", "primary_collocate": null, "pronunciation": "wǎng luò guǎn lǐ", "ipa": "wɑŋ˨˩˦ luo˥˩ kwan˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "他在公司负责网络管理，每天检查服务器。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络管理要随时监控流量，发现问题就处理。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做网络管理的人要会配置路由器。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行很重视网络管理，专门成立了小组。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请了一位专家来讲网络管理。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络管理工作包括维护设备和更新系统。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学学的是计算机，现在做网络管理。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络管理不好，服务器就容易出故障。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的网络管理由技术部门负责。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想学习网络管理，将来当网络工程师。", "target_word": "网络管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "網絡管理", "label": "繁体"}, {"form": "网络管理员", "label": "复合"}], "register": "中性", "sense_fingerprint": "监控、维护和配置计算机网络的技术工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b8aedc-5ff5-4137-89ea-9c5261b723e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财务", "is_correct": false, "explanation": "语义：“检查服务器”属于技术工作，“财务”是财会工作，与句意不符。"}, {"text": "网络管理", "is_correct": true, "explanation": "正确：“负责网络管理”指承担网络的监控与维护工作，与“检查服务器”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“负责”接工作或任务，“天气”不能被负责。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”是做饭，与后文“检查服务器”的技术工作完全无关。"}], "explanations": {"财务": "语义：“检查服务器”属于技术工作，“财务”是财会工作，与句意不符。", "网络管理": "正确：“负责网络管理”指承担网络的监控与维护工作，与“检查服务器”相符。", "天气": "搭配：“负责”接工作或任务，“天气”不能被负责。", "烹饪": "语义：“烹饪”是做饭，与后文“检查服务器”的技术工作完全无关。"}, "sentence_index": 0, "correct_answer": "网络管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把网络管理装进了背包，每天带去公司。", "explanation": "这里应该用〈笔记本电脑〉。“装进背包”用于具体物品，“网络管理”是工作，不能装进背包。"}, {"text": "公司新买了一台网络管理，专门监控流量。", "explanation": "这里应该用〈网络设备〉。“台”和“买”用于机器，“网络管理”是一种工作，不能买，也不能用“台”计量。"}, {"text": "他的电脑坏了，找人做网络管理。", "explanation": "这里应该说〈修电脑〉。修理坏掉的电脑是维修，“网络管理”指对网络的监控、维护和配置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大学", "is_correct": false, "explanation": "搭配：“做”后接工作或职业，“大学”是学校，不能说“做大学”。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”不是职业或工作，与前文从学计算机转向的语境无关。"}, {"text": "网络管理", "is_correct": true, "explanation": "正确：学计算机后从事网络管理，是合理的职业方向。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“做”不接“工资”，应说“拿工资”或“领工资”。"}], "explanations": {"大学": "搭配：“做”后接工作或职业，“大学”是学校，不能说“做大学”。", "夏天": "语义：“夏天”不是职业或工作，与前文从学计算机转向的语境无关。", "网络管理": "正确：学计算机后从事网络管理，是合理的职业方向。", "工资": "搭配：“做”不接“工资”，应说“拿工资”或“领工资”。"}, "sentence_index": 6, "correct_answer": "网络管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她想经营网络管理，把各行各业的朋友都联系起来。", "explanation": "这里的“网络”指人际关系，“网络管理”只指计算机网络，应说〈经营人脉〉。"}, {"text": "这家餐厅的网络管理很好吃，吸引了很多顾客。", "explanation": "这里应该用〈饭菜〉。“好吃”形容食物，“网络管理”是计算机网络的工作，不能用“好吃”形容。"}, {"text": "她最近沉迷网络管理，每天玩到半夜。", "explanation": "这里应该用〈网络游戏〉。沉迷和玩到半夜说的是娱乐，“网络管理”是技术工作，不能用来描述玩耍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最近负责一台网络管理工作。", "corrected_sentence": "他最近负责一项网络管理工作。", "error_description": "“网络管理工作”前的量词应用“项”。“台”用于机器，这里误用，应改为“一项网络管理工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的网络管理们做得很好，大家都很满意。", "corrected_sentence": "他的网络管理做得很好，大家都很满意。", "error_description": "“网络管理”是抽象的工作，不能加后缀“们”。应去掉“们”，写成“他的网络管理做得很好，大家都很满意。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
