INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "向警方等暗中提供情报的人。", "primary_collocate": null, "pronunciation": "xiàn rén", "ipa": "ɕjɛn˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他在黑帮里做警方的线人。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线人暗中把情报交给了警方。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的线人是一个年轻人。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关也有自己的线人。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线人提供的情报很有用。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有线人，警方很难抓到他们。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当线人是为了保护家人。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张是那个案子里最重要的线人。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线人用手机把地点发给了警方。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者说，他认识一个线人。", "target_word": "线人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "暗中向警方等提供情报的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "线人", "is_correct": true, "explanation": "正确答案。线人指暗中向警方等提供情报的人。"}, {"text": "现任", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是现在担任某个职务的人。"}, {"text": "先人", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是祖先。"}, {"text": "闲人", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是没有事情做的人。"}], "explanations": {"线人": "正确答案。线人指暗中向警方等提供情报的人。", "现任": "rèn（第四声）与 rén（第二声）声调不同，意思是现在担任某个职务的人。", "先人": "xiān（第一声）与 xiàn（第四声）声调不同，意思是祖先。", "闲人": "xián（第二声）与 xiàn（第四声）声调不同，意思是没有事情做的人。"}, "sentence_index": null, "correct_answer": "线人"}, "level_3": {"options": [{"text": "线人", "is_correct": true, "explanation": "正确答案。线人是暗中向警方提供情报的人，与“黑帮里”的语境相符。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”不是人，也不是职位，“警方的水果”说不通。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“做”不与“地址”搭配，不能说“做地址”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能指人，“做警方的天气”说不通。"}], "explanations": {"线人": "正确答案。线人是暗中向警方提供情报的人，与“黑帮里”的语境相符。", "水果": "语义：“水果”不是人，也不是职位，“警方的水果”说不通。", "地址": "搭配：“做”不与“地址”搭配，不能说“做地址”。", "天气": "语义：“天气”不能指人，“做警方的天气”说不通。"}, "sentence_index": 0, "correct_answer": "线人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用线人把我的衣服缝好了。", "explanation": "这里应该用〈针线〉。线人是暗中向警方提供情报的人，不能用来缝衣服。"}, {"text": "我们班的线人每天给我们上课。", "explanation": "这里应该用〈老师〉。线人是暗中提供情报的人，给学生上课的是老师。"}, {"text": "这家医院的线人给我开了药。", "explanation": "这里应该用〈医生〉。线人是暗中提供情报的人，开药的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "线人", "is_correct": true, "explanation": "正确答案。线人指暗中向警方等提供情报的人。"}, {"text": "仙人", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是神仙。"}, {"text": "贤人", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是有德才的人。"}, {"text": "现任", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是现在担任某个职务的人。"}], "explanations": {"线人": "正确答案。线人指暗中向警方等提供情报的人。", "仙人": "xiān（第一声）与 xiàn（第四声）声调不同，意思是神仙。", "贤人": "xián（第二声）与 xiàn（第四声）声调不同，意思是有德才的人。", "现任": "rèn（第四声）与 rén（第二声）声调不同，意思是现在担任某个职务的人。"}, "sentence_index": null, "correct_answer": "线人"}, "level_3": {"options": [{"text": "线人", "is_correct": true, "explanation": "正确答案。线人是人，“当线人”指担任暗中提供情报的角色。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：“钢笔”是文具，不能用“当”指人的身份，“他当钢笔”句意不通。"}, {"text": "木头", "is_correct": false, "explanation": "语义：“木头”不能用“当”来指某种身份，句子说不通。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“当”后接身份或职业，不能接“厕所”这类场所。"}], "explanations": {"线人": "正确答案。线人是人，“当线人”指担任暗中提供情报的角色。", "钢笔": "语义：“钢笔”是文具，不能用“当”指人的身份，“他当钢笔”句意不通。", "木头": "语义：“木头”不能用“当”来指某种身份，句子说不通。", "厕所": "搭配：“当”后接身份或职业，不能接“厕所”这类场所。"}, "sentence_index": 6, "correct_answer": "线人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公交车上的线人每天开车送我们上班。", "explanation": "这里应该用〈司机〉。线人是暗中提供情报的人，开车的是司机。"}, {"text": "飞机上的线人给我们送来了饮料。", "explanation": "这里应该用〈乘务员〉。线人是暗中提供情报的人，送饮料的是乘务员。"}, {"text": "商店的线人帮我把东西装进了袋子。", "explanation": "这里应该用〈店员〉。线人是暗中提供情报的人，在商店服务顾客的是店员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次行动依靠了一条线人。", "corrected_sentence": "这次行动依靠了一个线人。", "error_description": "量词错误：“线人”指人，量词应用“个”，不能用“条”。正确说法是“一个线人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我见过那两个线人们。", "corrected_sentence": "我见过那两个线人。", "error_description": "复数错误：前面已有数量词“两个”，“线人”后不能再加“们”。应说“那两个线人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "扩大", "is_correct": true, "explanation": "扩大：与缩小意思相反，指体积或面积变大。"}, {"text": "保持", "is_correct": false, "explanation": "保持：与缩小没有反义关系，指维持原样。"}, {"text": "停留", "is_correct": false, "explanation": "停留：与缩小没有反义关系，指暂时不动。"}, {"text": "前进", "is_correct": false, "explanation": "前进：与缩小没有反义关系，指向前移动。"}], "correct_answer": "扩大", "explanations": {"扩大": "扩大：与缩小意思相反，指体积或面积变大。", "保持": "保持：与缩小没有反义关系，指维持原样。", "停留": "停留：与缩小没有反义关系，指暂时不动。", "前进": "前进：与缩小没有反义关系，指向前移动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "扩大", "is_correct": true, "explanation": "扩大：与缩小意思相反，指范围或差距变大。"}, {"text": "改善", "is_correct": false, "explanation": "改善：与缩小没有反义关系，指变得更好。"}, {"text": "维持", "is_correct": false, "explanation": "维持：与缩小没有反义关系，指保持不变。"}, {"text": "出现", "is_correct": false, "explanation": "出现：与缩小没有反义关系，指显现或产生。"}], "correct_answer": "扩大", "explanations": {"扩大": "扩大：与缩小意思相反，指范围或差距变大。", "改善": "改善：与缩小没有反义关系，指变得更好。", "维持": "维持：与缩小没有反义关系，指保持不变。", "出现": "出现：与缩小没有反义关系，指显现或产生。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得比原来小。", "primary_collocate": null, "pronunciation": "suō xiǎo", "ipa": "swo˥ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "冰块在太阳下慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "furigana": "bīngkuài zài tàiyáng xià mànmàn suō xiǎo le.", "sentence_source": "generated"}, {"text": "中午太阳升高，影子慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的差距正在缩小。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果放了几天，明显缩小了。", "target_word": "缩小", "complexity_tier": "T3", "furigana": "zhè ge píngguǒ fàng le jǐ tiān, míngxiǎn suō xiǎo le.", "sentence_source": "generated"}, {"text": "气球漏气后，慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天一到，池塘的面积就缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜡烛燃烧以后，体积缩小了一半。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水变少，湖面缩小了一半。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的伤口慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫富差距没有缩小。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缩小了", "label": "体标"}, {"form": "缩小过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事物自己变小（不及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3f50a8-17b0-4f70-a8c6-cd248e706fce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩小", "is_correct": true, "explanation": "缩小：冰块受热慢慢变小，符合语境。"}, {"text": "增大", "is_correct": false, "explanation": "语义：“增大”指变大，与“太阳下慢慢”导致冰块变小的语境相反。"}, {"text": "长大", "is_correct": false, "explanation": "搭配：“长大”多用于人和生物，冰块不能长大。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”形容人的体型，冰块不能说变胖。"}], "explanations": {"缩小": "缩小：冰块受热慢慢变小，符合语境。", "增大": "语义：“增大”指变大，与“太阳下慢慢”导致冰块变小的语境相反。", "长大": "搭配：“长大”多用于人和生物，冰块不能长大。", "变胖": "体貌：“变胖”形容人的体型，冰块不能说变胖。"}, "sentence_index": 0, "correct_answer": "缩小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨停以后，雨声慢慢缩小了。", "explanation": "这里应该用〈变小〉或〈减弱〉。缩小指体积或范围变小，声音的减弱不能用缩小。"}, {"text": "台风过后，风力明显缩小了。", "explanation": "这里应该用〈减弱〉。缩小指体积或范围变小，风力、力量的下降要用减弱。"}, {"text": "吃了药以后，病人的疼痛缩小了不少。", "explanation": "这里应该用〈减轻〉。缩小指体积或范围变小，疼痛、负担的减少要用减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩小", "is_correct": true, "explanation": "缩小：蜡烛燃烧后体积变小了一半，符合语境。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”指变多，与燃烧以后蜡烛变小的语境相反。"}, {"text": "膨胀", "is_correct": false, "explanation": "语义：“膨胀”指体积变大，与燃烧后变小的语境相反。"}, {"text": "变窄", "is_correct": false, "explanation": "搭配：“变窄”说的是宽度，不能说“体积变窄”。"}], "explanations": {"缩小": "缩小：蜡烛燃烧后体积变小了一半，符合语境。", "增加": "语义：“增加”指变多，与燃烧以后蜡烛变小的语境相反。", "膨胀": "语义：“膨胀”指体积变大，与燃烧后变小的语境相反。", "变窄": "搭配：“变窄”说的是宽度，不能说“体积变窄”。"}, "sentence_index": 6, "correct_answer": "缩小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的物价缩小了不少。", "explanation": "这里应该用〈降低〉。缩小指体积或范围变小，物价、价格的下降要用降低。"}, {"text": "这次会议的时间缩小了一个小时。", "explanation": "这里应该用〈缩短〉。时间的减少要用缩短；缩小多指体积或范围变小。"}, {"text": "夜里气温缩小了好几度。", "explanation": "这里应该用〈下降〉。缩小指体积或范围变小，气温的下降要用下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裤子洗了几次，明显的缩小了。", "corrected_sentence": "这条裤子洗了几次，明显缩小了。", "error_description": "错误：“明显的缩小了”；正确：“明显缩小了”。“明显”是状语，修饰“缩小”，后面不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜡烛烧了一会儿，慢慢缩小了了。", "corrected_sentence": "蜡烛烧了一会儿，慢慢缩小了。", "error_description": "错误：“缩小了了”；正确：“缩小了”。“了”只需用一个，重复使用不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96992, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "扩大", "is_correct": true, "explanation": "扩大：与缩小意思相反，指把字或范围变大。"}, {"text": "保存", "is_correct": false, "explanation": "保存：与缩小没有反义关系，指留存下来。"}, {"text": "复制", "is_correct": false, "explanation": "复制：与缩小没有反义关系，指做出相同的副本。"}, {"text": "购买", "is_correct": false, "explanation": "购买：与缩小没有反义关系，指买下。"}], "correct_answer": "扩大", "explanations": {"扩大": "扩大：与缩小意思相反，指把字或范围变大。", "保存": "保存：与缩小没有反义关系，指留存下来。", "复制": "复制：与缩小没有反义关系，指做出相同的副本。", "购买": "购买：与缩小没有反义关系，指买下。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
