INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "严重危害他人或社会的行为。", "primary_collocate": null, "pronunciation": "zuì è", "ipa": "tswei˥˩ ɤ˥˩", "syllable_count": 2, "sentences": [{"text": "法律会惩罚一切罪恶。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的罪恶伤害了很多无辜的人。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毒品是一种危害社会的罪恶。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，这是不可原谅的罪恶。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认了自己所有的罪恶。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织犯下了许多罪恶。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察终于揭露了他们的罪恶。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些罪恶让整个城市不得安宁。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史不会忘记那些罪恶。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为自己的罪恶坐了十年牢。", "target_word": "罪恶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "罪恶感", "label": "复合"}], "register": "书面语", "sense_fingerprint": "严重危害他人社会的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罪恶", "is_correct": true, "explanation": "“罪恶”指严重危害他人或社会的行为，可以被法律惩罚，符合句意。"}, {"text": "欢笑", "is_correct": false, "explanation": "语义：“欢笑”不是能被惩罚的行为，“惩罚一切欢笑”句意不通。"}, {"text": "荣誉", "is_correct": false, "explanation": "搭配：“惩罚”的对象应是违法或过错行为，不能说惩罚“荣誉”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”不是行为，不能被法律惩罚，句意不通。"}], "explanations": {"罪恶": "“罪恶”指严重危害他人或社会的行为，可以被法律惩罚，符合句意。", "欢笑": "语义：“欢笑”不是能被惩罚的行为，“惩罚一切欢笑”句意不通。", "荣誉": "搭配：“惩罚”的对象应是违法或过错行为，不能说惩罚“荣誉”。", "礼物": "语义：“礼物”不是行为，不能被法律惩罚，句意不通。"}, "sentence_index": 0, "correct_answer": "罪恶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们之间有一个罪恶，已经解释清楚了。", "explanation": "这里应该用〈误会〉。罪恶指严重危害他人或社会的行为，两人之间的误会不能称为罪恶。"}, {"text": "他是一个罪恶，法官判了他十年。", "explanation": "这里应该用〈罪犯〉。罪恶指行为，不指人；说一个人作恶要用罪犯。"}, {"text": "他这次传球出现了明显的罪恶。", "explanation": "这里应该用〈失误〉。罪恶指严重危害他人或社会的行为，传球时的失误不属于此类，应说失误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罪恶", "is_correct": true, "explanation": "“罪恶”指严重危害他人或社会的行为，可以被揭露，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是个人的身体数据，不是可以被揭露的隐情，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能被揭露，“揭露他们的天气”句意不通。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“揭露”后接真相、秘密、罪行等，不能说“揭露午饭”。"}], "explanations": {"罪恶": "“罪恶”指严重危害他人或社会的行为，可以被揭露，符合句意。", "体重": "语义：“体重”是个人的身体数据，不是可以被揭露的隐情，句意不通。", "天气": "语义：“天气”是自然现象，不能被揭露，“揭露他们的天气”句意不通。", "午饭": "搭配：“揭露”后接真相、秘密、罪行等，不能说“揭露午饭”。"}, "sentence_index": 6, "correct_answer": "罪恶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场洪水带来了巨大的罪恶。", "explanation": "这里应该用〈灾难〉。罪恶指严重危害他人或社会的行为，洪水是自然灾害，应说灾难。"}, {"text": "这把椅子太罪恶了，我想换一把。", "explanation": "这里应该用〈旧〉。罪恶指严重危害他人或社会的行为，形容椅子应说旧。"}, {"text": "这次车祸给他的身体造成了罪恶。", "explanation": "这里应该用〈伤害〉。车祸对身体造成的是伤害，罪恶指严重危害他人或社会的行为，不能用于此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些人一直在策划各种罪恶们。", "corrected_sentence": "这些人一直在策划各种罪恶。", "error_description": "“罪恶”是抽象名词，不能加“们”表复数；应说“各种罪恶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "记者把那些罪恶们写进了报道。", "corrected_sentence": "记者把那些罪恶写进了报道。", "error_description": "“罪恶”是抽象名词，不能加“们”表复数；应说“那些罪恶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
