INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96995, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在文件上写上自己的名字。", "primary_collocate": null, "pronunciation": "shǔ", "ipa": "ʂu˨˩˦", "syllable_count": 1, "sentences": [{"text": "请在这张纸上署上你的名字。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在合同上署了自己的名字。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿起笔，在信的最后署上名字。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要在文件的右下角署上姓名。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们在照片后面署上名字。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理已经在文件上署上了名字。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有在别人的文件上署过名字。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画完画以后，小明在角落署上了自己的名字。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都在这封信上署了名字，表示同意。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先署上日期和名字，再交给我。", "target_word": "署", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "署了", "label": "体标"}, {"form": "署过", "label": "体标"}, {"form": "署上", "label": "结果补语"}, {"form": "署名", "label": "复合词"}], "register": "书面", "sense_fingerprint": "在文件上写上自己的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "署", "is_correct": true, "explanation": "正确：署，在文件上写上自己的名字。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，shū 的意思是书。"}, {"text": "述", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，shù 的意思是叙述。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shǔ（第三声）声调不同，shú 的意思是熟悉、成熟。"}], "explanations": {"署": "正确：署，在文件上写上自己的名字。", "书": "shū（第一声）与 shǔ（第三声）声调不同，shū 的意思是书。", "述": "shù（第四声）与 shǔ（第三声）声调不同，shù 的意思是叙述。", "熟": "shú（第二声）与 shǔ（第三声）声调不同，shú 的意思是熟悉、成熟。"}, "sentence_index": null, "correct_answer": "署"}, "level_3": {"options": [{"text": "署", "is_correct": true, "explanation": "署：在文件上写上自己的名字，与句中“名字”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃名字”。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣物，不能说“穿名字”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语“名字”。"}], "explanations": {"署": "署：在文件上写上自己的名字，与句中“名字”相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃名字”。", "穿": "搭配：“穿”的宾语应是衣物，不能说“穿名字”。", "睡": "配价：“睡”是不及物动词，不能带宾语“名字”。"}, "sentence_index": 0, "correct_answer": "署"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上署了一封长信。", "explanation": "这里应该用〈写〉。署只表示在文件上写下名字，写长篇内容要用〈写〉。"}, {"text": "他把作业署了一遍，交给老师。", "explanation": "这里应该用〈抄〉。署只指写名字，把作业重新写一遍要用〈抄〉。"}, {"text": "我们在这张纸上署了公章。", "explanation": "这里应该用〈盖〉。署指写名字，盖公章要用〈盖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96995, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "署", "is_correct": true, "explanation": "正确：署，在文件上写上自己的名字。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，shù 的意思是树。"}, {"text": "输", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，shū 的意思是输掉。"}, {"text": "赎", "is_correct": false, "explanation": "shú（第二声）与 shǔ（第三声）声调不同，shú 的意思是赎回。"}], "explanations": {"署": "正确：署，在文件上写上自己的名字。", "树": "shù（第四声）与 shǔ（第三声）声调不同，shù 的意思是树。", "输": "shū（第一声）与 shǔ（第三声）声调不同，shū 的意思是输掉。", "赎": "shú（第二声）与 shǔ（第三声）声调不同，shú 的意思是赎回。"}, "sentence_index": null, "correct_answer": "署"}, "level_3": {"options": [{"text": "署", "is_correct": true, "explanation": "署：在文件上写上自己的名字，与句中“名字”相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮料，不能说“喝名字”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“名字”。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指转让物品，不能用来表示在文件上写名字，与句意不合。"}], "explanations": {"署": "署：在文件上写上自己的名字，与句中“名字”相符。", "喝": "搭配：“喝”的宾语应是饮料，不能说“喝名字”。", "笑": "配价：“笑”是不及物动词，不能带宾语“名字”。", "卖": "语义：“卖”指转让物品，不能用来表示在文件上写名字，与句意不合。"}, "sentence_index": 6, "correct_answer": "署"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在墙上署了一朵大花。", "explanation": "这里应该用〈画〉。署只指写名字，画花要用〈画〉。"}, {"text": "他在石头上署了一个字。", "explanation": "这里应该用〈刻〉。署是写名字，在石头上刻字要用〈刻〉。"}, {"text": "经理负责署每个人的工作。", "explanation": "这里应该用〈布置〉。署只指在文件上写名字，安排工作要用〈布置〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请在这份表格上署了你的名字。", "corrected_sentence": "请在这份表格上署上你的名字。", "error_description": "体标错误：祈使句“请……”中不能用“了”表示完成，应用结果补语“上”。正确说法：署上你的名字。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来没有在别人的合同上署了自己的名字。", "corrected_sentence": "她从来没有在别人的合同上署过自己的名字。", "error_description": "体标错误：“从来没有”表示从未有过某种经历，应用“过”，不能用“了”。正确说法：署过自己的名字。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
