INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96997, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "年纪不大，但是做事很稳、很像大人。", "primary_collocate": null, "pronunciation": "lǎo chéng", "ipa": "lɑʊ˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个孩子才十岁，说话很老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪不大，看起来很老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明做事老成，大家都喜欢他。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二岁的他遇到麻烦很老成，先冷静想办法。", "target_word": "老成", "complexity_tier": "T3", "furigana": "shí èr suì de tā yù dào má fan hěn lǎo chéng xiān lěng jìng xiǎng bàn fǎ", "sentence_source": "generated"}, {"text": "他才八岁，安慰哭泣的朋友时却很老成。", "target_word": "老成", "complexity_tier": "T3", "furigana": "tā cái bā suì ān wèi kū qì de péng you shí què hěn lǎo chéng", "sentence_source": "generated"}, {"text": "这个小女孩很老成，像个小大人。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟虽然只有九岁，遇事却总是很老成。", "target_word": "老成", "complexity_tier": "T3", "furigana": "dì di suī rán zhǐ yǒu jiǔ suì yù shì què zǒng shì hěn lǎo chéng", "sentence_source": "generated"}, {"text": "别看他年轻，办事特别老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就比同龄人老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学生比同年级的孩子老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "孩子或年轻人言行像大人一样稳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3f50a8-17b0-4f70-a8c6-cd248e706fce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老陈", "is_correct": false, "explanation": "lǎo chén（陈）与 lǎo chéng 只差韵尾，n 对 ng，“老陈”是对姓陈的人的称呼。"}, {"text": "老成", "is_correct": true, "explanation": "正确：老成（lǎo chéng），指年纪不大却做事稳重。"}, {"text": "老臣", "is_correct": false, "explanation": "lǎo chén（臣）与 lǎo chéng 只差韵尾，n 对 ng，意思是资历深的老大臣。"}, {"text": "老秤", "is_correct": false, "explanation": "lǎo chèng（秤）与 lǎo chéng 只差声调，第四声对第二声，意思是老式的秤。"}], "explanations": {"老陈": "lǎo chén（陈）与 lǎo chéng 只差韵尾，n 对 ng，“老陈”是对姓陈的人的称呼。", "老成": "正确：老成（lǎo chéng），指年纪不大却做事稳重。", "老臣": "lǎo chén（臣）与 lǎo chéng 只差韵尾，n 对 ng，意思是资历深的老大臣。", "老秤": "lǎo chèng（秤）与 lǎo chéng 只差声调，第四声对第二声，意思是老式的秤。"}, "sentence_index": null, "correct_answer": "老成"}, "level_3": {"options": [{"text": "苍老", "is_correct": false, "explanation": "语义：“苍老”指年老衰弱，与“才十岁”矛盾。"}, {"text": "老成", "is_correct": true, "explanation": "正确：“老成”指年纪小却说话稳重，符合“说话很老成”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或形象，不能用来形容说话。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：“硬朗”多用于身体，不能说“说话很硬朗”。"}], "explanations": {"苍老": "语义：“苍老”指年老衰弱，与“才十岁”矛盾。", "老成": "正确：“老成”指年纪小却说话稳重，符合“说话很老成”。", "高大": "体貌：“高大”形容身材或形象，不能用来形容说话。", "硬朗": "搭配：“硬朗”多用于身体，不能说“说话很硬朗”。"}, "sentence_index": 0, "correct_answer": "老成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这筐草莓已经很老成了，可以摘下来吃了。", "explanation": "这里应该用〈成熟〉。老成形容人年纪不大却言行稳重，草莓熟了要用“成熟”。"}, {"text": "他骑车很老成，十分钟就到了学校。", "explanation": "这里应该用〈熟练〉。老成形容为人处世稳重，骑车这类技能要用“熟练”。"}, {"text": "这架梯子放得很老成，我放心爬上去。", "explanation": "这里应该用〈稳当〉。老成形容人的言行，物体放置稳固要用“稳当”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96997, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老生", "is_correct": false, "explanation": "lǎo shēng（生）与 lǎo chéng 声母不同（sh 对 ch），声调也不同，“老生”是京剧中扮演中老年男子的角色。"}, {"text": "老成", "is_correct": true, "explanation": "正确：老成（lǎo chéng），指年纪不大却做事稳重。"}, {"text": "老虫", "is_correct": false, "explanation": "lǎo chóng（虫）与 lǎo chéng 声母相同，韵母不同（ong 对 eng），在一些方言里“老虫”指老鼠。"}, {"text": "老曾", "is_correct": false, "explanation": "lǎo zēng（曾）与 lǎo chéng 声母不同（z 对 ch），声调也不同，“老曾”是对姓曾的人的称呼。"}], "explanations": {"老生": "lǎo shēng（生）与 lǎo chéng 声母不同（sh 对 ch），声调也不同，“老生”是京剧中扮演中老年男子的角色。", "老成": "正确：老成（lǎo chéng），指年纪不大却做事稳重。", "老虫": "lǎo chóng（虫）与 lǎo chéng 声母相同，韵母不同（ong 对 eng），在一些方言里“老虫”指老鼠。", "老曾": "lǎo zēng（曾）与 lǎo chéng 声母不同（z 对 ch），声调也不同，“老曾”是对姓曾的人的称呼。"}, "sentence_index": null, "correct_answer": "老成"}, "level_3": {"options": [{"text": "老成", "is_correct": true, "explanation": "正确：“老成”指年纪小却遇事稳重，与“虽然”的转折相符。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“只有九岁”矛盾。"}, {"text": "花白", "is_correct": false, "explanation": "体貌：“花白”形容头发的颜色，不能形容遇事的态度。"}, {"text": "佝偻", "is_correct": false, "explanation": "体貌：“佝偻”形容身体弯曲的样子，不能形容遇事的态度。"}], "explanations": {"老成": "正确：“老成”指年纪小却遇事稳重，与“虽然”的转折相符。", "年迈": "语义：“年迈”指年纪很大，与“只有九岁”矛盾。", "花白": "体貌：“花白”形容头发的颜色，不能形容遇事的态度。", "佝偻": "体貌：“佝偻”形容身体弯曲的样子，不能形容遇事的态度。"}, "sentence_index": 6, "correct_answer": "老成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子很老成，一道题一看就懂。", "explanation": "这里应该用〈聪明〉。老成指言行稳重，不指头脑灵活，形容学得快、反应快要用“聪明”。"}, {"text": "这个小家伙很老成，一见到糖就跑过去抢。", "explanation": "这里应该用〈馋〉。老成指稳重有分寸，不指贪吃，形容嘴馋要用“馋”。"}, {"text": "这个小男孩很老成，总能把大家逗笑。", "explanation": "这里应该用〈幽默〉。老成指稳重，不指风趣诙谐，让人发笑要用“幽默”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他才十岁，做事却很老成很。", "corrected_sentence": "他才十岁，做事却很老成。", "error_description": "错误：句末多出一个“很”，“很老成很”；正确：“很老成”。程度副词“很”只放在形容词前，句末不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他比他哥哥最老成。", "corrected_sentence": "他比他哥哥更老成。", "error_description": "错误：“比…最老成”；正确：“比…更老成”。比较句中表示程度加深要用“更”，“最”表示最高级，不能与“比”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
