INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96998, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "年纪不大却做事稳重，经验多。", "primary_collocate": null, "pronunciation": "lǎo chéng", "ipa": "lɑʊ˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小王才二十五岁，办事很老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻的医生处理问题很老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然年轻，但是做生意老成得很。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的助手很老成，经理很放心。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪轻轻，却老成稳重。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回答记者的问题很老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的队长带队很老成，大家都服他。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看他做事多老成，一点也不像新手。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人很老成，从不乱说话。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他二十出头，谈起工作却十分老成。", "target_word": "老成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "年轻人办事稳重、经验丰富", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3f50a8-17b0-4f70-a8c6-cd248e706fce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老陈", "is_correct": false, "explanation": "lǎo chén（陈）与 lǎo chéng 只差韵尾，n 对 ng，“老陈”是对姓陈的人的称呼。"}, {"text": "老成", "is_correct": true, "explanation": "正确：老成（lǎo chéng），指年轻人办事稳重、经验丰富。"}, {"text": "老臣", "is_correct": false, "explanation": "lǎo chén（臣）与 lǎo chéng 只差韵尾，n 对 ng，意思是资历深的老大臣。"}, {"text": "老秤", "is_correct": false, "explanation": "lǎo chèng（秤）与 lǎo chéng 只差声调，第四声对第二声，意思是老式的秤。"}], "explanations": {"老陈": "lǎo chén（陈）与 lǎo chéng 只差韵尾，n 对 ng，“老陈”是对姓陈的人的称呼。", "老成": "正确：老成（lǎo chéng），指年轻人办事稳重、经验丰富。", "老臣": "lǎo chén（臣）与 lǎo chéng 只差韵尾，n 对 ng，意思是资历深的老大臣。", "老秤": "lǎo chèng（秤）与 lǎo chéng 只差声调，第四声对第二声，意思是老式的秤。"}, "sentence_index": null, "correct_answer": "老成"}, "level_3": {"options": [{"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“才二十五岁”矛盾。"}, {"text": "老成", "is_correct": true, "explanation": "正确：“老成”指年纪不大却办事稳重，符合“办事很老成”。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：“硬朗”多用于身体，不能说“办事很硬朗”。"}, {"text": "花白", "is_correct": false, "explanation": "体貌：“花白”形容头发的颜色，不能形容办事。"}], "explanations": {"年迈": "语义：“年迈”指年纪很大，与“才二十五岁”矛盾。", "老成": "正确：“老成”指年纪不大却办事稳重，符合“办事很老成”。", "硬朗": "搭配：“硬朗”多用于身体，不能说“办事很硬朗”。", "花白": "体貌：“花白”形容头发的颜色，不能形容办事。"}, "sentence_index": 0, "correct_answer": "老成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些西红柿已经很老成了，可以摘下来卖了。", "explanation": "这里应该用〈成熟〉。老成形容人办事稳重，西红柿熟了要用“成熟”。"}, {"text": "他整理房间很老成，半小时就收拾好了。", "explanation": "这里应该用〈利索〉。老成形容人办事稳重、有经验，整理房间这类动作要用“利索”。"}, {"text": "这块布很老成，颜色都发白了。", "explanation": "这里应该用〈陈旧〉。老成形容人办事稳重、经验丰富，布料用旧了要用“陈旧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96998, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老曾", "is_correct": false, "explanation": "lǎo zēng（曾）与 lǎo chéng 声母不同（z 对 ch），声调也不同，“老曾”是对姓曾的人的称呼。"}, {"text": "老成", "is_correct": true, "explanation": "正确：老成（lǎo chéng），指年轻人办事稳重、经验丰富。"}, {"text": "老生", "is_correct": false, "explanation": "lǎo shēng（生）与 lǎo chéng 声母不同（sh 对 ch），声调也不同，“老生”是京剧中扮演中老年男子的角色。"}, {"text": "老虫", "is_correct": false, "explanation": "lǎo chóng（虫）与 lǎo chéng 声母相同，韵母不同（ong 对 eng），在一些方言里“老虫”指老鼠。"}], "explanations": {"老曾": "lǎo zēng（曾）与 lǎo chéng 声母不同（z 对 ch），声调也不同，“老曾”是对姓曾的人的称呼。", "老成": "正确：老成（lǎo chéng），指年轻人办事稳重、经验丰富。", "老生": "lǎo shēng（生）与 lǎo chéng 声母不同（sh 对 ch），声调也不同，“老生”是京剧中扮演中老年男子的角色。", "老虫": "lǎo chóng（虫）与 lǎo chéng 声母相同，韵母不同（ong 对 eng），在一些方言里“老虫”指老鼠。"}, "sentence_index": null, "correct_answer": "老成"}, "level_3": {"options": [{"text": "幼稚", "is_correct": false, "explanation": "语义：“幼稚”指不成熟，与“大家都服他”的语境矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境，不能说“带队很嘈杂”。"}, {"text": "老成", "is_correct": true, "explanation": "正确：“老成”指办事稳重，与“大家都服他”的语境相符。"}, {"text": "苍老", "is_correct": false, "explanation": "语义：“苍老”指年老，与“年轻的队长”矛盾。"}], "explanations": {"幼稚": "语义：“幼稚”指不成熟，与“大家都服他”的语境矛盾。", "嘈杂": "搭配：“嘈杂”形容声音或环境，不能说“带队很嘈杂”。", "老成": "正确：“老成”指办事稳重，与“大家都服他”的语境相符。", "苍老": "语义：“苍老”指年老，与“年轻的队长”矛盾。"}, "sentence_index": 6, "correct_answer": "老成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很老成，一学就会，从来不用别人教第二遍。", "explanation": "这里应该用〈聪明〉。老成指稳重，不指学得快，形容理解快、学得快要用“聪明”。"}, {"text": "他很老成，每天一大早就把屋子打扫完了。", "explanation": "这里应该用〈勤快〉。老成指稳重有分寸，不指干活积极，形容爱干活、勤快要用“勤快”。"}, {"text": "他很老成，每次开会都能把大家逗笑。", "explanation": "这里应该用〈幽默〉。老成指稳重，不指风趣诙谐，让人发笑要用“幽默”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他二十岁，办事却很很老成。", "corrected_sentence": "他二十岁，办事却很老成。", "error_description": "错误：“很很老成”；正确：“很老成”。程度副词“很”只用一次，重复使用是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他老成的处理了问题。", "corrected_sentence": "他老成地处理了问题。", "error_description": "错误：“老成的处理”；正确：“老成地处理”。修饰动词的状语要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f51810f-8016-472e-904c-88a0c1130eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
