INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96999, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很多人都知道的。", "primary_collocate": null, "pronunciation": "wén míng", "ipa": "wən˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这是一座闻名的古城。", "target_word": "闻名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是一位闻名全国的歌手。", "target_word": "闻名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们去看了那个闻名世界的大桥。", "target_word": "闻名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里有很多闻名的小吃。", "target_word": "闻名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "长城是闻名中外的好地方。", "target_word": "闻名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了一本闻名世界的小说。", "target_word": "闻名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是我们城市里闻名的医生。", "target_word": "闻名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家闻名的老店在山下。", "target_word": "闻名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想去看一看那座闻名的大山。", "target_word": "闻名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位闻名全国的老师来过我们学校。", "target_word": "闻名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "很多人都知道的（作定语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闻名", "is_correct": true, "explanation": "正确：闻名作定语修饰古城，表示很多人都知道，符合“一座……的古城”的语境。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：聪明形容人或动物的智力，不能用来修饰城市。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：年轻指年龄短，与“古城”的古老相矛盾。"}, {"text": "害羞", "is_correct": false, "explanation": "搭配：害羞形容人的性格，城市不会害羞。"}], "explanations": {"闻名": "正确：闻名作定语修饰古城，表示很多人都知道，符合“一座……的古城”的语境。", "聪明": "搭配：聪明形容人或动物的智力，不能用来修饰城市。", "年轻": "语义：年轻指年龄短，与“古城”的古老相矛盾。", "害羞": "搭配：害羞形容人的性格，城市不会害羞。"}, "sentence_index": 0, "correct_answer": "闻名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天闻名了一个好消息。", "explanation": "这里应该用〈听到〉。闻名是形容词，指很多人都知道，不能带“消息”作宾语表示听见。"}, {"text": "这位老师闻名了我们全班的同学。", "explanation": "这里应该用〈熟悉〉。闻名是形容词，不能带宾语“同学”；表示认识同学要用熟悉。"}, {"text": "他做事很闻名，从来不迟到。", "explanation": "这里应该用〈认真〉。闻名说人或事物名气大，不用来形容做事的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闻名", "is_correct": true, "explanation": "正确：闻名作定语修饰医生，表示她在城市里很有名气，搭配自然。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：光滑形容物体表面，不能用来修饰医生。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：潮湿形容天气或环境，不能用来修饰职业身份。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：甜蜜形容感情或滋味，不能用来描述一个人的职业身份。"}], "explanations": {"闻名": "正确：闻名作定语修饰医生，表示她在城市里很有名气，搭配自然。", "光滑": "搭配：光滑形容物体表面，不能用来修饰医生。", "潮湿": "搭配：潮湿形容天气或环境，不能用来修饰职业身份。", "甜蜜": "语义：甜蜜形容感情或滋味，不能用来描述一个人的职业身份。"}, "sentence_index": 6, "correct_answer": "闻名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈闻名了一下花，说很香。", "explanation": "这里应该用〈闻〉。闻名指很多人都知道，不表示用鼻子闻气味。"}, {"text": "这个小吃摊闻名了整条街的客人。", "explanation": "这里应该用〈吸引〉。闻名是形容词，不能带宾语“客人”；表示吸引客人要用吸引。"}, {"text": "这道菜做得很闻名，大家都爱吃。", "explanation": "这里应该用〈好吃〉。闻名说名气大，不用作“做得……”的补语来评价味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家茶馆闻名在全国。", "corrected_sentence": "这家茶馆闻名全国。", "error_description": "错误形式：“闻名在全国”；正确形式：“闻名全国”。“闻名”后直接接补语“全国”，不能插入介词“在”，应说“闻名全国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校请来了一位闻名全国地专家。", "corrected_sentence": "我们学校请来了一位闻名全国的专家。", "error_description": "错误形式：“闻名全国地”；正确形式：“闻名全国的”。“闻名全国”修饰名词时要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
