INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97001, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97001, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "如果是这样的话。", "primary_collocate": null, "pronunciation": "ruò shì", "ipa": "ɻuɔ˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "若是这样，我们改天再去吧。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他发烧了？若是这样，你应该带他去医院。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说他不来了？若是这样，我们开始吧。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他中奖了？若是真的，那太好了。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经道歉了？若是那样，你不用担心了。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说路上很堵，若是这样，我们早点走吧。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不够？若是这样，我可以借给你。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天没睡觉？若是这样，今天别让他开车。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不想去？若是那样，我一个人去。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有说谎吗？若是这样，我们应该相信他。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "承接上文，表示如果是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "若是", "is_correct": true, "explanation": "若是：如果是这样，承接上文，与句意相符。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或并列，不表示假设条件，与“若是这样”的推断不合。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，与“若是这样”的假设条件不合。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”后面要接动作或结果，不能用“这样”作条件。"}], "explanations": {"若是": "若是：如果是这样，承接上文，与句意相符。", "而且": "语义：“而且”表示递进或并列，不表示假设条件，与“若是这样”的推断不合。", "因此": "语义：“因此”表示结果，与“若是这样”的假设条件不合。", "于是": "搭配：“于是”后面要接动作或结果，不能用“这样”作条件。"}, "sentence_index": 0, "correct_answer": "若是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "若是他每天都很努力，所以考上了大学。", "explanation": "这里应该用〈因为〉。“若是”表示假设，句中“很努力”是已知原因，与“所以”搭配要用〈因为〉。"}, {"text": "我们可以坐地铁，若是打车去。", "explanation": "这里应该用〈或者〉。“若是”不表示选择，列出两种方式要用〈或者〉。"}, {"text": "你要去超市，若是去医院？", "explanation": "这里应该用〈还是〉。“若是”不能用于择一的问句，两者选一要用〈还是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "若是", "is_correct": true, "explanation": "若是：如果是这样，承接上文，与“若是这样”的推断相符。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折语气，不能引出假设条件，与句意不合。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，与“钱不够”后的假设性推断不合。"}, {"text": "只是", "is_correct": false, "explanation": "搭配：“只是”后面通常要接转折的分句，不能用“这样”作条件。"}], "explanations": {"若是": "若是：如果是这样，承接上文，与“若是这样”的推断相符。", "却": "语义：“却”表示转折语气，不能引出假设条件，与句意不合。", "因此": "语义：“因此”表示结果，与“钱不够”后的假设性推断不合。", "只是": "搭配：“只是”后面通常要接转折的分句，不能用“这样”作条件。"}, "sentence_index": 6, "correct_answer": "若是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会做饭，若是还会洗衣服。", "explanation": "这里应该用〈而且〉。“若是”表示假设条件，句中“还会洗衣服”是补充的已知能力，应用〈而且〉。"}, {"text": "这次考试我复习得很充分，若是没有考好。", "explanation": "这里应该用〈却〉。“若是”表示假设，句中“没有考好”是已知结果，表示转折要用〈却〉。"}, {"text": "这个方法很好，若是有一点慢。", "explanation": "这里应该用〈不过〉。“若是”表示假设，句中“有一点慢”是已知的缺点，表示转折要用〈不过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若是了那样，我们明天再去吧。", "corrected_sentence": "若是那样，我们明天再去吧。", "error_description": "体标误用：连词“若是”后面不能加“了”，“了”只能用于动词或形容词之后。正确说法：若是那样，我们明天再去吧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电影票卖完了？若是的这样，我们明天去看。", "corrected_sentence": "电影票卖完了？若是这样，我们明天去看。", "error_description": "结构错误：连词“若是”后面不能加“的”，应说“若是这样”。正确说法：电影票卖完了？若是这样，我们明天去看。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
