INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97002, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示假设，相当于如果。", "primary_collocate": null, "pronunciation": "ruò shì", "ipa": "ɻuɔ˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "若是下雨，比赛会改到明天。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是你有时间，请来我家吃饭。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是天气好，我们明天去爬山。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是路上堵车，我会提前给你打电话。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是你同意，我们现在签合同。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是明天不忙，我想去看看爷爷。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是有问题，请随时告诉我。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是东西太贵，你可以不买。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是他来了，请让他在门口等我。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若是我们早点出发，应该不会迟到。", "target_word": "若是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "连词，引出假设条件，相当于如果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结果，不表示假设，“所以下雨”不能引出假设条件。"}, {"text": "若是", "is_correct": true, "explanation": "连词，表示假设，引出条件，与后句“比赛会改到明天”相符。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与“比赛会改到明天”的因果推断不协调。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”用于并列或递进，不能单独在句首引出假设条件。"}], "explanations": {"所以": "语义：“所以”表示因果结果，不表示假设，“所以下雨”不能引出假设条件。", "若是": "连词，表示假设，引出条件，与后句“比赛会改到明天”相符。", "虽然": "语义：“虽然”表示让步，与“比赛会改到明天”的因果推断不协调。", "而且": "搭配：“而且”用于并列或递进，不能单独在句首引出假设条件。"}, "sentence_index": 0, "correct_answer": "若是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不想去医院，若是想去书店。", "explanation": "这里应该用〈而是〉。否定前句后引出另一个选择要用〈而是〉，“若是”只引出假设，不能这样用。"}, {"text": "这次旅行很愉快，若是有点累。", "explanation": "这里应该用〈只是〉。表示整体好、个别有不足要用〈只是〉，“若是”不能表示这种转折。"}, {"text": "他很努力，若是成绩不太好。", "explanation": "这里应该用〈不过〉。前句肯定、后句转折要用〈不过〉，“若是”引出的假设与前句不构成转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折对立，与“请随时告诉我”的假设条件不协调。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”承接前一个动作，句首单用不能引出假设条件。"}, {"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，与“请随时告诉我”的提醒语气不符。"}, {"text": "若是", "is_correct": true, "explanation": "连词，表示假设，引出条件，与后句“请随时告诉我”相符。"}], "explanations": {"然而": "语义：“然而”表示转折对立，与“请随时告诉我”的假设条件不协调。", "于是": "搭配：“于是”承接前一个动作，句首单用不能引出假设条件。", "可是": "语义：“可是”表示转折，与“请随时告诉我”的提醒语气不符。", "若是": "连词，表示假设，引出条件，与后句“请随时告诉我”相符。"}, "sentence_index": 6, "correct_answer": "若是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没来上课，若是他生病了，所以没来。", "explanation": "这里应该用〈因为〉。“若是”只引出假设，而“他生病了”是已知原因；“若是……所以”把已知原因说成假设，搭配不当。"}, {"text": "他已经搬到北京了，若是他搬到了北京，就不会再回来。", "explanation": "这里应该用〈既然〉。“他已经搬到北京了”是已知事实，据此引出推论要用〈既然〉；“若是”只表示假设，不能用于已经发生的事。"}, {"text": "我们已经决定下周出发，若是下周出发，所以能赶上假期。", "explanation": "这里应该用〈既然〉。“下周出发”已是定下的计划，据此引出结论要用〈既然〉；“若是”引出假设，与“所以”的因果推断搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若是的你明天有空，就一起去图书馆吧。", "corrected_sentence": "若是你明天有空，就一起去图书馆吧。", "error_description": "“若是”后面多加了“的”。正确形式是“若是你明天有空”，“的”不能放在连词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若是是东西不合适，你可以退货。", "corrected_sentence": "若是东西不合适，你可以退货。", "error_description": "“若是”后面多加了一个“是”。正确形式是“若是东西不合适”，“若是”本身已表示假设，不能重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
