INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责处置或办理某事的人。", "primary_collocate": null, "pronunciation": "chǔ lǐ zhě", "ipa": "ʈʂʰu˨˩˦ li˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这件事的处理者是王经理。", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投诉的处理者会给你打电话。", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁是这个问题的处理者？", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "处理者要先听双方怎么说。", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批货的处理者已经签字确认了。", "target_word": "处理者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故的处理者已经到了现场。", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为处理者，他一直很公平。", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文件的处理者必须认真看每一页。", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我这个案子的处理者是谁。", "target_word": "处理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "处理者把问题都解决了。", "target_word": "处理者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "处理者：名词，负责处置或办理某件事务、问题的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作者", "is_correct": false, "explanation": "语义：“作者”指写作或创作的人，与“这件事”的处置语境不相容。"}, {"text": "翻译者", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能用来指“这件事”的办理人。"}, {"text": "发明者", "is_correct": false, "explanation": "语义：“发明”指创造新事物，与“这件事”需要办理处置的语境不符。"}, {"text": "处理者", "is_correct": true, "explanation": "名词，指负责处置或办理这件事的人，与“王经理”的身份相符。"}], "explanations": {"作者": "语义：“作者”指写作或创作的人，与“这件事”的处置语境不相容。", "翻译者": "搭配：“翻译”的对象是语言文字，不能用来指“这件事”的办理人。", "发明者": "语义：“发明”指创造新事物，与“这件事”需要办理处置的语境不符。", "处理者": "名词，指负责处置或办理这件事的人，与“王经理”的身份相符。"}, "sentence_index": 0, "correct_answer": "处理者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的处理者坏了，需要修理。", "explanation": "这里应该用〈处理器〉。“处理者”只指办理事务的人，机器的芯片或部件要用〈处理器〉。"}, {"text": "这件事的处理者是被处分的那个学生。", "explanation": "这里应该用〈处理对象〉。“处理者”指负责办理事务的人，被处分的学生是被处理的对象，不能叫“处理者”。"}, {"text": "我见过一只处理者。", "explanation": "这里应该用〈位〉。“处理者”指人，量词要用“位”，不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受益者", "is_correct": false, "explanation": "语义：“受益者”指从中获利的人，与“一直很公平”的角色不符。"}, {"text": "收藏者", "is_correct": false, "explanation": "搭配：“收藏者”对应收藏的物品，不能与“作为……他一直很公平”这样的身份搭配。"}, {"text": "观赏者", "is_correct": false, "explanation": "语义：“观赏者”只是看的人，不负责裁断，与“公平”的角色不符。"}, {"text": "处理者", "is_correct": true, "explanation": "名词，指负责办理事务的人，与“一直很公平”的角色相符。"}], "explanations": {"受益者": "语义：“受益者”指从中获利的人，与“一直很公平”的角色不符。", "收藏者": "搭配：“收藏者”对应收藏的物品，不能与“作为……他一直很公平”这样的身份搭配。", "观赏者": "语义：“观赏者”只是看的人，不负责裁断，与“公平”的角色不符。", "处理者": "名词，指负责办理事务的人，与“一直很公平”的角色相符。"}, "sentence_index": 6, "correct_answer": "处理者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的处理者是下午三点开始的，大家都回家了。", "explanation": "这里应该用〈处理过程〉。“是……开始的”描述的是办理的过程，“处理者”指人，不能这样作主语。"}, {"text": "这次会议的处理者是下午三点举行的，大家还在讨论。", "explanation": "“处理者”指负责办理事务的人，不能说“是……举行的”。这里说的是会议本身，应删去“的处理者”，说“这次会议是下午三点举行的”。"}, {"text": "这次事故的处理者持续了三天，大家都很累。", "explanation": "“处理者”指人，不能指事故处理所用的时间，这段时间要用〈时间〉表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那一只处理者已经来了。", "corrected_sentence": "那一位处理者已经来了。", "error_description": "量词用错。“处理者”指人，量词应用“位”，不能用“只”。正确形式是“那一位处理者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次事故的处理者者是一位交警。", "corrected_sentence": "这次事故的处理者是一位交警。", "error_description": "“处理者”的后缀“者”被重复使用。“处理者”已是完整的词，正确形式是“处理者”，不能写成“处理者者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97005, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
