INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97005, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很，非常。", "primary_collocate": null, "pronunciation": "mán", "ipa": "man˧˥", "syllable_count": 1, "sentences": [{"text": "这家店的面蛮好吃的，你可以试试。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气蛮好的，我们出去走走吧。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得蛮好，大家都很吃惊。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服蛮便宜的，才五十块钱。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个电影蛮有意思的。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跑得蛮快的，一下子就到了。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间蛮大的，住三个人没问题。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天蛮高兴的，还请我们吃糖。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书蛮难的，我看了三天才看完。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做的菜蛮香的，是什么菜？", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蠻", "label": "繁体"}], "register": "口语", "sense_fingerprint": "蛮：口语程度副词，放在形容词前表示“很”，常与“的”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97005, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛮", "is_correct": true, "explanation": "正确。蛮 mán 是口语程度副词，意思是“很”。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。"}, {"text": "慢", "is_correct": false, "explanation": "màn（第四声）与 mán（第二声）声调不同，意思是慢。"}, {"text": "忙", "is_correct": false, "explanation": "máng（第二声）与 mán 韵母不同（an/ang），意思是忙。"}, {"text": "男", "is_correct": false, "explanation": "nán（第二声）与 mán 声母不同（n/m），意思是男人。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 mán 声母不同（l/m），意思是蓝色。"}], "explanations": {"蛮": "正确。蛮 mán 是口语程度副词，意思是“很”。", "满": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。", "慢": "màn（第四声）与 mán（第二声）声调不同，意思是慢。", "忙": "máng（第二声）与 mán 韵母不同（an/ang），意思是忙。", "男": "nán（第二声）与 mán 声母不同（n/m），意思是男人。", "蓝": "lán（第二声）与 mán 声母不同（l/m），意思是蓝色。"}, "sentence_index": null, "correct_answer": "蛮"}, "level_3": {"options": [{"text": "不", "is_correct": false, "explanation": "语义：“不好吃的，你可以试试”前后矛盾，否定词与推荐语气不合。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示刚好或仅仅，与程度无关，“这家店的面才好吃的”说不通。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示时间，不表示程度，“已经好吃的”说不通。"}, {"text": "蛮", "is_correct": true, "explanation": "正确。“蛮”放在形容词前表示程度，“蛮好吃的”是口语常用说法。"}], "explanations": {"不": "语义：“不好吃的，你可以试试”前后矛盾，否定词与推荐语气不合。", "才": "语义：“才”表示刚好或仅仅，与程度无关，“这家店的面才好吃的”说不通。", "已经": "语义：“已经”表示时间，不表示程度，“已经好吃的”说不通。", "蛮": "正确。“蛮”放在形容词前表示程度，“蛮好吃的”是口语常用说法。"}, "sentence_index": 0, "correct_answer": "蛮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天比昨天蛮冷，记得多穿点。", "explanation": "这里应该用〈更〉。“比”字句里不能用“蛮”这类程度副词，应说“今天比昨天更冷”。"}, {"text": "我蛮在看书，别打扰我。", "explanation": "这里应该用〈正在〉。“蛮”是程度副词，不能用于表示进行的“在”结构。"}, {"text": "他蛮把窗户关上了。", "explanation": "这里应该用〈随手〉。“蛮”不能修饰“把”字句中的处置动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97005, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛮", "is_correct": true, "explanation": "正确。蛮 mán 是口语程度副词，意思是“很”。"}, {"text": "难", "is_correct": false, "explanation": "nán（第二声）与 mán 声母不同（n/m），意思是困难。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 mán 声母不同（f/m），意思是烦恼。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。"}], "explanations": {"蛮": "正确。蛮 mán 是口语程度副词，意思是“很”。", "难": "nán（第二声）与 mán 声母不同（n/m），意思是困难。", "烦": "fán（第二声）与 mán 声母不同（f/m），意思是烦恼。", "满": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。"}, "sentence_index": null, "correct_answer": "蛮"}, "level_3": {"options": [{"text": "更", "is_correct": false, "explanation": "语义：“更大”需要比较对象，句中没有比较的基准，说不通。"}, {"text": "蛮", "is_correct": true, "explanation": "正确。“这个房间蛮大的”表示程度，口语中很常用。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示刚好或仅仅，与程度无关，“这个房间才大的”说不通。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示重复或追加，“又大的”在此说不通。"}], "explanations": {"更": "语义：“更大”需要比较对象，句中没有比较的基准，说不通。", "蛮": "正确。“这个房间蛮大的”表示程度，口语中很常用。", "才": "语义：“才”表示刚好或仅仅，与程度无关，“这个房间才大的”说不通。", "又": "语义：“又”表示重复或追加，“又大的”在此说不通。"}, "sentence_index": 6, "correct_answer": "蛮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天很蛮饿。", "explanation": "这里不应重复表示程度。“很”与“蛮”都表示程度，只保留其一，应说“我今天蛮饿”。"}, {"text": "他蛮是学生。", "explanation": "这里应该直接说“他是学生”。“蛮”表示程度，不能修饰判断动词“是”。"}, {"text": "他蛮张口说了一句，大家都没听懂。", "explanation": "这里应该用〈刚〉。“蛮”是程度副词，不能修饰“张口”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋蛮舒服地，走了一天也不累。", "corrected_sentence": "这双鞋蛮舒服的，走了一天也不累。", "error_description": "“地”错误：“蛮”修饰形容词作谓语时，形容词后应用“的”，说“蛮舒服的”，不能说“蛮舒服地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个厨房蛮干净地，我很喜欢。", "corrected_sentence": "这个厨房蛮干净的，我很喜欢。", "error_description": "的／地错误：“蛮”修饰形容词作谓语时，形容词后应用“的”，说“蛮干净的”；“地”用于修饰动词，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
