INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度相当高；很。", "primary_collocate": null, "pronunciation": "mán", "ipa": "man˧˥", "syllable_count": 1, "sentences": [{"text": "他看起来蛮年轻的，其实已经四十岁了。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿到公司蛮远的，要坐一个小时车。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试我考得蛮不错，爸爸很满意。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的地方蛮安静的，晚上很好睡。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友蛮好的，常常帮别人的忙。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路蛮长的，走到家要半小时。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王唱歌蛮好听的，你听过吗？", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天蛮累的，想早点睡觉。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做的蛋糕蛮甜的，小孩子都爱吃。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子蛮聪明的，一学就会。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蠻", "label": "繁体"}], "register": "口语", "sense_fingerprint": "蛮：副词，表示程度相当高，用在形容词或心理动词前，口语色彩强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛮", "is_correct": true, "explanation": "正确。蛮 mán 是口语副词，表示程度相当高。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。"}, {"text": "忙", "is_correct": false, "explanation": "máng（第二声）与 mán 韵母不同（an/ang），意思是忙。"}, {"text": "男", "is_correct": false, "explanation": "nán（第二声）与 mán 声母不同（n/m），意思是男人。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 mán 声母不同（l/m），意思是蓝色。"}], "explanations": {"蛮": "正确。蛮 mán 是口语副词，表示程度相当高。", "满": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。", "忙": "máng（第二声）与 mán 韵母不同（an/ang），意思是忙。", "男": "nán（第二声）与 mán 声母不同（n/m），意思是男人。", "蓝": "lán（第二声）与 mán 声母不同（l/m），意思是蓝色。"}, "sentence_index": null, "correct_answer": "蛮"}, "level_3": {"options": [{"text": "才", "is_correct": false, "explanation": "语义：“才”表示刚好或仅仅，与程度无关，“他看起来才年轻的”说不通。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示时间，不表示程度，“已经年轻的”说不通。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示恰好或刚刚，“刚年轻的”说不通。"}, {"text": "蛮", "is_correct": true, "explanation": "正确。“他看起来蛮年轻的”表示程度相当高，口语中常用。"}], "explanations": {"才": "语义：“才”表示刚好或仅仅，与程度无关，“他看起来才年轻的”说不通。", "已经": "语义：“已经”表示时间，不表示程度，“已经年轻的”说不通。", "刚": "语义：“刚”表示恰好或刚刚，“刚年轻的”说不通。", "蛮": "正确。“他看起来蛮年轻的”表示程度相当高，口语中常用。"}, "sentence_index": 0, "correct_answer": "蛮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比从前蛮胖。", "explanation": "这里应该用〈更〉。“比”字句里不能用“蛮”这类程度副词，应说“他比从前更胖”。"}, {"text": "我蛮在睡觉，别吵我。", "explanation": "这里应该用〈正在〉。“蛮”是程度副词，不能用于表示进行的“在”结构。"}, {"text": "他蛮把书放回了书架。", "explanation": "这里应该用〈随手〉。“蛮”不能修饰“把”字句中的处置动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛮", "is_correct": true, "explanation": "正确。蛮 mán 是口语副词，表示程度相当高。"}, {"text": "慢", "is_correct": false, "explanation": "màn（第四声）与 mán（第二声）声调不同，意思是慢。"}, {"text": "难", "is_correct": false, "explanation": "nán（第二声）与 mán 声母不同（n/m），意思是困难。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 mán 声母不同（f/m），意思是烦恼。"}], "explanations": {"蛮": "正确。蛮 mán 是口语副词，表示程度相当高。", "慢": "màn（第四声）与 mán（第二声）声调不同，意思是慢。", "难": "nán（第二声）与 mán 声母不同（n/m），意思是困难。", "烦": "fán（第二声）与 mán 声母不同（f/m），意思是烦恼。"}, "sentence_index": null, "correct_answer": "蛮"}, "level_3": {"options": [{"text": "只", "is_correct": false, "explanation": "语义：“只”表示仅仅，“唱歌只好听的”说不通。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示刚好或仅仅，与程度无关，“小王唱歌才好听的”说不通。"}, {"text": "蛮", "is_correct": true, "explanation": "正确。“小王唱歌蛮好听的”表示程度相当高，口语中常用。"}, {"text": "更", "is_correct": false, "explanation": "语义：“更好听”需要比较对象，句中没有比较的基准，说不通。"}], "explanations": {"只": "语义：“只”表示仅仅，“唱歌只好听的”说不通。", "才": "语义：“才”表示刚好或仅仅，与程度无关，“小王唱歌才好听的”说不通。", "蛮": "正确。“小王唱歌蛮好听的”表示程度相当高，口语中常用。", "更": "语义：“更好听”需要比较对象，句中没有比较的基准，说不通。"}, "sentence_index": 6, "correct_answer": "蛮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天很蛮累。", "explanation": "这里不应重复表示程度。“很”与“蛮”都表示程度，只保留其一，应说“我今天蛮累”。"}, {"text": "这个孩子蛮是老师。", "explanation": "这里应该直接说“这个孩子是老师”。“蛮”是程度副词，不能修饰判断动词“是”。"}, {"text": "他蛮扛起箱子就走了。", "explanation": "这里应该用〈一下子〉。“蛮”是程度副词，不能修饰“扛起”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学生蛮认真地，老师很喜欢他。", "corrected_sentence": "这个学生蛮认真的，老师很喜欢他。", "error_description": "“地”错误：“蛮”修饰形容词作谓语时，形容词后应用“的”，说“蛮认真的”，不能说“蛮认真地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小伙子蛮热情地，大家都喜欢他。", "corrected_sentence": "这个小伙子蛮热情的，大家都喜欢他。", "error_description": "的／地错误：“蛮”修饰形容词作谓语时，形容词后应用“的”，说“蛮热情的”；“地”用于修饰动词，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97007, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97007, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97007, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有很多血，看起来很吓人。", "primary_collocate": null, "pronunciation": "xuè xīng", "ipa": "ɕɥɛ˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这部电影太血腥了，我不敢看。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有很多血，场面很血腥。", "target_word": "血腥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说那个事故现场很血腥。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不能看这么血腥的画面。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏太血腥，我女儿不能玩。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻里的照片太血腥了，我马上关了电视。", "target_word": "血腥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生见过很多血腥的场面，一点也不怕。", "target_word": "血腥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个血腥的画面，我到现在还记得。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拍这场戏时，导演用了很多红色的水，看起来特别血腥。", "target_word": "血腥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太血腥了，我不想再看一遍。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "血腥味", "label": "复合"}], "register": "中性", "sense_fingerprint": "血腥：画面、场面里有很多血，看着吓人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97007, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "血腥", "is_correct": true, "explanation": "正确答案：血腥（xuè xīng），意思是有很多血、看着吓人的画面或场面。"}, {"text": "血型", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，意思是血型，指血液的类别。"}, {"text": "血清", "is_correct": false, "explanation": "qīng 与 xīng 声母不同（q 与 x），意思是血清，指血液凝固后分离出的淡黄色液体。"}, {"text": "血性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，意思是刚烈勇敢的气概。"}], "explanations": {"血腥": "正确答案：血腥（xuè xīng），意思是有很多血、看着吓人的画面或场面。", "血型": "xíng（第二声）与 xīng（第一声）声调不同，意思是血型，指血液的类别。", "血清": "qīng 与 xīng 声母不同（q 与 x），意思是血清，指血液凝固后分离出的淡黄色液体。", "血性": "xìng（第四声）与 xīng（第一声）声调不同，意思是刚烈勇敢的气概。"}, "sentence_index": null, "correct_answer": "血腥"}, "level_3": {"options": [{"text": "血腥", "is_correct": true, "explanation": "正确答案：血腥，形容画面有很多血、令人害怕，与“不敢看”相合。"}, {"text": "搞笑", "is_correct": false, "explanation": "语义：“搞笑”说的是好笑，与“我不敢看”的害怕语境不合。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”说的是乏味，不会让人不敢看。"}, {"text": "柔和", "is_correct": false, "explanation": "搭配：“柔和”多形容光线、声音、颜色，不说电影太柔和。"}], "explanations": {"血腥": "正确答案：血腥，形容画面有很多血、令人害怕，与“不敢看”相合。", "搞笑": "语义：“搞笑”说的是好笑，与“我不敢看”的害怕语境不合。", "无聊": "语义：“无聊”说的是乏味，不会让人不敢看。", "柔和": "搭配：“柔和”多形容光线、声音、颜色，不说电影太柔和。"}, "sentence_index": 0, "correct_answer": "血腥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试成绩很血腥，我都不敢看。", "explanation": "这里应该用〈惨〉。血腥指有很多血、令人害怕的场面，不用来形容成绩；成绩很差要说惨。"}, {"text": "这件裙子很血腥，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。血腥指有很多血、令人害怕的场面，不用来形容衣服的颜色，颜色明亮要用鲜艳。"}, {"text": "这个西瓜很血腥，我吃了两块。", "explanation": "这里应该用〈甜〉。血腥指有很多血、令人害怕的场面，不用来形容水果的味道；西瓜好吃要说甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血腥", "is_correct": true, "explanation": "正确答案：血腥，指场面有很多血、令人害怕，与“一点也不怕”形成对照。"}, {"text": "温馨", "is_correct": false, "explanation": "语义：“温馨”指温暖、舒适，与“一点也不怕”的语境不合。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指好笑，不能用来形容让人一点也不怕的场面。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水、眼睛等，不说场面清澈。"}], "explanations": {"血腥": "正确答案：血腥，指场面有很多血、令人害怕，与“一点也不怕”形成对照。", "温馨": "语义：“温馨”指温暖、舒适，与“一点也不怕”的语境不合。", "幽默": "语义：“幽默”指好笑，不能用来形容让人一点也不怕的场面。", "清澈": "搭配：“清澈”形容水、眼睛等，不说场面清澈。"}, "sentence_index": 6, "correct_answer": "血腥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个夜市很血腥，人特别多。", "explanation": "这里应该用〈热闹〉。血腥只形容有很多血、令人害怕的场面，不用来形容人多、声音大的地方。"}, {"text": "这件衣服价格很血腥，只要五十块。", "explanation": "这里应该用〈便宜〉。血腥指有很多血、令人害怕的场面，不能形容价格；价格低要说便宜。"}, {"text": "这盆花很血腥，我每天都浇水。", "explanation": "这里应该用〈漂亮〉。血腥指有很多血、令人害怕的场面，不能用来形容花；花好看要说漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那幅画太血腥的了，我看了很不舒服。", "corrected_sentence": "那幅画太血腥了，我看了很不舒服。", "error_description": "“太……了”框架中，“血腥”后不加“的”，应写“太血腥了”；多加“的”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个很血腥画面吓到了我。", "corrected_sentence": "那个很血腥的画面吓到了我。", "error_description": "修饰名词“画面”时，“很血腥”后要加“的”，应写“很血腥的画面”；漏掉“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
