INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97008, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "带有血的气味或场面；残酷。", "primary_collocate": null, "pronunciation": "xuè xīng", "ipa": "ɕɥɛ˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "那场战争非常血腥，死了很多人。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写了许多血腥的故事。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用血腥的手段打败了对手。", "target_word": "血腥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家过去的历史很血腥。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢这么血腥的比赛。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场血腥的战斗持续了三天。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国王对待敌人的手段非常血腥。", "target_word": "血腥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事又残酷又血腥，不适合小孩。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打仗是血腥的，没有人喜欢。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屠宰场里的空气又热又血腥，让人想吐。", "target_word": "血腥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "血腥味", "label": "复合"}], "register": "中性", "sense_fingerprint": "血腥：带血的气味或场面，引申为残酷（战争、镇压、暴力）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d21887-be9b-48fa-b9d1-c635d54b606e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97008, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "血腥", "is_correct": true, "explanation": "正确答案：血腥（xuè xīng），指带血的气味或场面，也指残酷。"}, {"text": "血型", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，意思是血型，指血液的类别。"}, {"text": "血清", "is_correct": false, "explanation": "qīng 与 xīng 声母不同（q 与 x），意思是血清，指血液凝固后分离出的液体。"}, {"text": "血性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，意思是刚烈勇敢的气概。"}], "explanations": {"血腥": "正确答案：血腥（xuè xīng），指带血的气味或场面，也指残酷。", "血型": "xíng（第二声）与 xīng（第一声）声调不同，意思是血型，指血液的类别。", "血清": "qīng 与 xīng 声母不同（q 与 x），意思是血清，指血液凝固后分离出的液体。", "血性": "xìng（第四声）与 xīng（第一声）声调不同，意思是刚烈勇敢的气概。"}, "sentence_index": null, "correct_answer": "血腥"}, "level_3": {"options": [{"text": "血腥", "is_correct": true, "explanation": "正确答案：血腥，形容战争残酷、死伤很多，与“死了很多人”一致。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”说没有声响，与“死了很多人”的战争场面不合。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指好笑，与战争中死人的情况完全矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水、眼睛等，不说战争非常清澈。"}], "explanations": {"血腥": "正确答案：血腥，形容战争残酷、死伤很多，与“死了很多人”一致。", "安静": "语义：“安静”说没有声响，与“死了很多人”的战争场面不合。", "幽默": "语义：“幽默”指好笑，与战争中死人的情况完全矛盾。", "清澈": "搭配：“清澈”形容水、眼睛等，不说战争非常清澈。"}, "sentence_index": 0, "correct_answer": "血腥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的寺庙很血腥，很多人去参观。", "explanation": "这里应该用〈古老〉。血腥形容残酷或带血的场面，不用来形容寺庙等建筑；寺庙年代久远要说古老。"}, {"text": "这床被子很血腥，我每天晚上都盖着它睡觉。", "explanation": "这里应该用〈柔软〉。血腥只用于带血的气味或残酷的场面，不能形容被子的质地；被子松软要说柔软。"}, {"text": "这条街很血腥，每天都有很多人。", "explanation": "这里应该用〈繁华〉。血腥不用于描写街道的热闹、繁华，只用于带血或残酷的场面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血腥", "is_correct": true, "explanation": "正确答案：血腥，指残酷的手段，与“敌人”的语境一致。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”指态度和善，与对待敌人的残酷手段矛盾。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”指快乐，不能用来形容对待敌人的手段。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体的质地，不说手段柔软。"}], "explanations": {"血腥": "正确答案：血腥，指残酷的手段，与“敌人”的语境一致。", "温柔": "语义：“温柔”指态度和善，与对待敌人的残酷手段矛盾。", "欢乐": "语义：“欢乐”指快乐，不能用来形容对待敌人的手段。", "柔软": "搭配：“柔软”形容物体的质地，不说手段柔软。"}, "sentence_index": 6, "correct_answer": "血腥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏夜的风又血腥又清新，让人想出去走走。", "explanation": "这里应该用〈凉爽〉。血腥指带血的气味或残酷的场面，与“清新”矛盾；形容夏夜的风要说凉爽。"}, {"text": "屋子里又血腥又干净，让人很舒服。", "explanation": "这里应该用〈温暖〉。血腥指带血的气味，与“干净”矛盾；屋里暖和要说温暖。"}, {"text": "这张明信片上的风景又血腥又美丽，我很喜欢。", "explanation": "这里应该用〈漂亮〉。血腥指带血的气味或残酷的场面，不能形容风景；风景好看要说漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个暴君处决犯人的方式的非常血腥，大家都很害怕。", "corrected_sentence": "那个暴君处决犯人的方式非常血腥，大家都很害怕。", "error_description": "“方式”后已用“的”接修饰语，“非常”前不应再加“的”，应写“处决犯人的方式非常血腥”；多加“的”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看守用很血腥方式对待囚犯，大家都不敢反抗。", "corrected_sentence": "看守用很血腥的方式对待囚犯，大家都不敢反抗。", "error_description": "修饰名词“方式”时，“很血腥”后要加“的”，应写“很血腥的方式”；漏掉“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92183c2c-9b14-4356-b186-02c915827b8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
