INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97009, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种工作里的人才懂的特别说法。", "primary_collocate": null, "pronunciation": "háng huà", "ipa": "xɑŋ˧˥ xu̯ɑ˥˩", "syllable_count": 2, "sentences": [{"text": "他们说的是行话，别人都听不懂。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意的人有自己的行话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚进厂的时候，我不懂师傅们的行话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句行话是什么意思？", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的行话，客人听了会很奇怪。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥是修车的，常说一些修车的行话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了不少行话，现在像个老手。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要对孩子说行话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张给我讲了一套他们的行话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词是我们公司的行话，外面的人不用。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句行话", "label": "量词"}, {"form": "一套行话", "label": "量词"}], "register": "口语", "sense_fingerprint": "一种工作里的人才懂的特别说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "语义：饭是用来吃的，不能说“说的是饭”，句子讲不通。"}, {"text": "行话", "is_correct": true, "explanation": "正确：行话是某个工作里的人才懂的特别说法，正好与“别人都听不懂”相符。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是用来唱的，不是可以“说”的内容，句意不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“说”的对象是语言或话题，“钢琴”是乐器，不能作所说的内容。"}], "explanations": {"饭": "语义：饭是用来吃的，不能说“说的是饭”，句子讲不通。", "行话": "正确：行话是某个工作里的人才懂的特别说法，正好与“别人都听不懂”相符。", "歌": "语义：歌是用来唱的，不是可以“说”的内容，句意不通。", "钢琴": "搭配：“说”的对象是语言或话题，“钢琴”是乐器，不能作所说的内容。"}, "sentence_index": 0, "correct_answer": "行话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的行话很感人。", "explanation": "这里应该用〈歌词〉。行话指同一行业内部的专门用语，不是歌曲的唱词；形容歌词感人，要用歌词。"}, {"text": "他一口气吃了三碗行话，大家都笑他。", "explanation": "行话是专门用语，不能吃；“吃”要搭配食物，这里不通。"}, {"text": "这本书的行话很高。", "explanation": "这里把〈水平〉的概念用到了行话上。行话只是一种专门说法，没有高低之分，说“很高”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新手", "is_correct": false, "explanation": "语义：“学”的对象是知识或技能，“新手”不是可以学的东西，与“像个老手”也相矛盾。"}, {"text": "行话", "is_correct": true, "explanation": "正确：行话是行内人才懂的说法，学得多，才会像个老手。"}, {"text": "错误", "is_correct": false, "explanation": "搭配：“学”后接知识或技能，“学了不少错误”不通，也与“现在像个老手”相矛盾。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“学”后接知识或技能，“鞋子”是物品，不能说“学了不少鞋子”。"}], "explanations": {"新手": "语义：“学”的对象是知识或技能，“新手”不是可以学的东西，与“像个老手”也相矛盾。", "行话": "正确：行话是行内人才懂的说法，学得多，才会像个老手。", "错误": "搭配：“学”后接知识或技能，“学了不少错误”不通，也与“现在像个老手”相矛盾。", "鞋子": "搭配：“学”后接知识或技能，“鞋子”是物品，不能说“学了不少鞋子”。"}, "sentence_index": 6, "correct_answer": "行话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的行话很便宜。", "explanation": "这里应该用〈价格〉。行话指同一行业内部的专门用语，没有价钱，不能说“行话很便宜”；衣服的价钱要用价格。"}, {"text": "他把行话穿在身上，走到哪儿都很显眼。", "explanation": "行话是专门用语，不能穿在身上；“穿”要搭配衣物，这里不通。"}, {"text": "这家店的行话很好吃。", "explanation": "这里应该用〈菜〉。行话是专门用语，不是食物；形容食物好吃，要说菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车间里的人说的全是行话们，外人根本听不懂。", "corrected_sentence": "车间里的人说的全是行话，外人根本听不懂。", "error_description": "后缀错误：“们”不能加在“行话”这样指事物的名词后，应说“全是行话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师傅一开口就讲一只行话，我们听得很累。", "corrected_sentence": "这位老师傅一开口就讲行话，我们听得很累。", "error_description": "量词错误：行话不用“只”计量，“只”多用于动物和某些单个的小东西。这里不应加量词，应说“讲行话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
