INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97010, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一行业内部使用的专门用语。", "primary_collocate": null, "pronunciation": "háng huà", "ipa": "xɑŋ˧˥ xu̯ɑ˥˩", "syllable_count": 2, "sentences": [{"text": "医生们说的行话，病人常常听不懂。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业有很多行话，新人要慢慢学。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一开口就是行话，我一句也没听懂。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师用行话写合同，普通人看不明白。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搞电脑的人常说一些行话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在饭店工作，要先学会这里的行话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对客人讲话，不用行话，说得很清楚。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些行话对外人来说很难懂。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅们用行话聊着天，我在一旁听着。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书把行话换成了普通的话。", "target_word": "行话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句行话", "label": "量词"}, {"form": "一套行话", "label": "量词"}], "register": "口语", "sense_fingerprint": "同一行业内部使用的专门用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诗", "is_correct": false, "explanation": "语义：诗是文学作品，医生不会拿它来交流，“医生们说的诗”句意不通。"}, {"text": "行话", "is_correct": true, "explanation": "正确：行话是同一行业内部使用的专门用语，医生们用它交流，病人自然听不懂。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的记号，不是医生说的话，句子讲不通。"}, {"text": "讲座", "is_correct": false, "explanation": "搭配：“说”的对象是话语或语言，“讲座”是一种活动，不能说“医生们说的讲座”。"}], "explanations": {"诗": "语义：诗是文学作品，医生不会拿它来交流，“医生们说的诗”句意不通。", "行话": "正确：行话是同一行业内部使用的专门用语，医生们用它交流，病人自然听不懂。", "乐谱": "语义：乐谱是记录音乐的记号，不是医生说的话，句子讲不通。", "讲座": "搭配：“说”的对象是话语或语言，“讲座”是一种活动，不能说“医生们说的讲座”。"}, "sentence_index": 0, "correct_answer": "行话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最近股市的行话一路上涨，大家都很高兴。", "explanation": "这里应该用〈行情〉。行话指同一行业内部的专门用语，不是市场的涨跌状况；说市场走势要用行情。"}, {"text": "他在这个行话工作了十年。", "explanation": "这里应该用〈行业〉。行话是行业内部的专门用语，不是工作的领域，不能说“在行话工作”。"}, {"text": "他是个行话，大家都认识他。", "explanation": "这里应该用〈行家〉。行话是专门用语，不能用来指人；指在某行当里经验丰富的人，要用行家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌", "is_correct": false, "explanation": "语义：歌是用来唱的，“不用歌”与“讲话”的语境不合，句子讲不通。"}, {"text": "行话", "is_correct": true, "explanation": "正确：行话是专门用语，“不用行话、说得很清楚”说明向客人讲话时要用通俗的说法。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是用来演奏的器具，与“讲话”无关，“不用乐器”句意不通。"}, {"text": "棋", "is_correct": false, "explanation": "搭配：“用”后接表达方式或工具，“棋”不是讲话的手段，说“不用棋”不通。"}], "explanations": {"歌": "语义：歌是用来唱的，“不用歌”与“讲话”的语境不合，句子讲不通。", "行话": "正确：行话是专门用语，“不用行话、说得很清楚”说明向客人讲话时要用通俗的说法。", "乐器": "语义：乐器是用来演奏的器具，与“讲话”无关，“不用乐器”句意不通。", "棋": "搭配：“用”后接表达方式或工具，“棋”不是讲话的手段，说“不用棋”不通。"}, "sentence_index": 6, "correct_answer": "行话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗的行话很优美，大家都爱读。", "explanation": "这里应该用〈诗句〉。行话指同一行业内部的专门用语，不是诗的句子；形容诗句优美，要用诗句。"}, {"text": "他用行话打扫了房间。", "explanation": "这里应该用〈扫帚〉。行话是专门用语，不是工具；打扫房间要用扫帚，不能用行话。"}, {"text": "这道菜就是一套行话。", "explanation": "这里误把〈菜肴〉的意思用到了行话上。行话指同一行业内部的专门用语，不能说成一道菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有一座自己的行话，新人要先学。", "corrected_sentence": "这家公司有一套自己的行话，新人要先学。", "error_description": "量词错误：行话用“套”或“句”计量，不能用“座”（座多用于山、楼等大型物体）。应说“一套自己的行话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学了很多行话们，现在能听懂大部分内容。", "corrected_sentence": "他学了很多行话，现在能听懂大部分内容。", "error_description": "后缀错误：“们”只加在指人的名词后，“行话”指事物，不能说“行话们”，应说“很多行话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
