INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大家在电脑上看着对方的脸开会。", "primary_collocate": null, "pronunciation": "shì pín huì yì", "ipa": "ʂʐ̩˥˩ pʰin˧˥ xuei˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "我在家用电脑开视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频会议上，我看见了每个同事的脸。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对着电脑参加视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频会议的时候，请看着屏幕。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在房间里开视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的视频会议九点开始。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频会议里，大家都笑着说早上好。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长开了一个视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频会议中，小王忘了关声音。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把电脑放好，准备开视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "視頻會議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在电脑屏幕上看见彼此的脸一起开会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视频会议", "is_correct": true, "explanation": "正确：在家用电脑看着对方的脸开会，就是视频会议，与“在家用电脑开”搭配。"}, {"text": "外卖", "is_correct": false, "explanation": "搭配：“开”不能接“外卖”，应说“叫外卖”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：在家用电脑无法开汽车，与“在家”的场景矛盾。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“用电脑开雨伞”不合常理，雨伞要用手撑开。"}], "explanations": {"视频会议": "正确：在家用电脑看着对方的脸开会，就是视频会议，与“在家用电脑开”搭配。", "外卖": "搭配：“开”不能接“外卖”，应说“叫外卖”。", "汽车": "语义：在家用电脑无法开汽车，与“在家”的场景矛盾。", "雨伞": "语义：“用电脑开雨伞”不合常理，雨伞要用手撑开。"}, "sentence_index": 0, "correct_answer": "视频会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在视频会议里买了一斤苹果。", "explanation": "这里应该用〈超市〉。买苹果要去超市，视频会议是远程开会，不能在里面买东西。"}, {"text": "视频会议获得了电影节大奖。", "explanation": "这里应该用〈短片〉。获奖的是影片，会议不能获奖。"}, {"text": "我在海边拍了视频会议。", "explanation": "这里应该用〈录像〉。拍下来的是影像，应说“拍录像”；视频会议是实时进行的会议，不能被拍下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视频会议", "is_correct": true, "explanation": "正确：视频会议里大家可以隔着屏幕笑着打招呼，符合“笑着说早上好”的场景。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地不是人们笑着打招呼的地方，与“笑着说早上好”冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会有人，大家不可能在冰箱里打招呼。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦里的人不是真的在一起，与“大家都笑着说早上好”的真实场景不符。"}], "explanations": {"视频会议": "正确：视频会议里大家可以隔着屏幕笑着打招呼，符合“笑着说早上好”的场景。", "墓地": "语义：墓地不是人们笑着打招呼的地方，与“笑着说早上好”冲突。", "冰箱": "语义：冰箱里不会有人，大家不可能在冰箱里打招呼。", "梦": "语义：梦里的人不是真的在一起，与“大家都笑着说早上好”的真实场景不符。"}, "sentence_index": 6, "correct_answer": "视频会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在视频会议上跑了第一名。", "explanation": "这里应该用〈运动会〉。跑第一名是在运动会上发生的，视频会议是远程开会，不能用于体育比赛。"}, {"text": "我们在视频会议里坐了摩天轮。", "explanation": "这里应该用〈游乐园〉。坐摩天轮要在游乐园，视频会议是远程开会，不能作为游玩的地方。"}, {"text": "我们在视频会议里堆了一座沙堡。", "explanation": "这里应该用〈海边〉。堆沙堡要在沙滩上进行，视频会议是远程开会，不能用来堆沙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他习惯在卧室里用电脑开一只视频会议。", "corrected_sentence": "他习惯在卧室里用电脑开一场视频会议。", "error_description": "量词错误：“视频会议”应用量词“场”，说“开一场视频会议”；“只”用于动物或单个物件，不能用于会议。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只视频会议讨论得很认真。", "corrected_sentence": "这次视频会议讨论得很认真。", "error_description": "量词错误：“视频会议”应用量词“次”，说“这次视频会议”；“只”用于动物或单个物件，不能用于会议。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
