INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通过网络传送图像和声音进行的远程会议。", "primary_collocate": null, "pronunciation": "shì pín huì yì", "ipa": "ʂʐ̩˥˩ pʰin˧˥ xuei˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "公司明天上午有一场视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外，只能参加视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为网络不好，视频会议停了几分钟。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的视频会议有二十多个人参加。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用视频会议和北京的同事谈工作。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频会议开始前，请先打开声音。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天不能出门，所以改成视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次视频会议开了一个小时，大家都很累。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在视频会议上说了新计划。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开视频会议比出差便宜多了。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "視頻會議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "借助网络连接异地人员的远程会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视频会议", "is_correct": true, "explanation": "正确：“场”可以计量会议，“视频会议”是通过网络进行的远程会议，与“明天上午”搭配。"}, {"text": "电子邮件", "is_correct": false, "explanation": "搭配：“场”计量活动、比赛、会议等，不能用来数“电子邮件”，应说“一封电子邮件”。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭通常在中午吃，与“明天上午”的时间矛盾。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“场”不能计量“水果”，应说“一箱水果”或“一盘水果”。"}], "explanations": {"视频会议": "正确：“场”可以计量会议，“视频会议”是通过网络进行的远程会议，与“明天上午”搭配。", "电子邮件": "搭配：“场”计量活动、比赛、会议等，不能用来数“电子邮件”，应说“一封电子邮件”。", "午饭": "语义：午饭通常在中午吃，与“明天上午”的时间矛盾。", "水果": "搭配：“场”不能计量“水果”，应说“一箱水果”或“一盘水果”。"}, "sentence_index": 0, "correct_answer": "视频会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把视频会议放进了冰箱。", "explanation": "这里应该用〈蛋糕〉。能放进冰箱的是食物，视频会议是远程开会，不是东西。"}, {"text": "运动员在视频会议中打破了纪录。", "explanation": "这里应该用〈比赛〉。打破纪录发生在体育比赛中，视频会议是远程开会，不能用于比赛。"}, {"text": "学生在视频会议上游了一百米。", "explanation": "这里应该用〈泳池〉。游一百米要在泳池或海里进行，视频会议是远程开会，不能作为游泳的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视频会议", "is_correct": true, "explanation": "正确：下雨不能出门，只能改成通过网络进行的远程会议。"}, {"text": "郊游", "is_correct": false, "explanation": "语义：郊游需要外出，与“不能出门”直接矛盾。"}, {"text": "雅集", "is_correct": false, "explanation": "语域：“雅集”是文言色彩很浓的词，与口语化的句子不协调。"}, {"text": "游行", "is_correct": false, "explanation": "语义：游行要走上街头，与“不能出门”直接矛盾。"}], "explanations": {"视频会议": "正确：下雨不能出门，只能改成通过网络进行的远程会议。", "郊游": "语义：郊游需要外出，与“不能出门”直接矛盾。", "雅集": "语域：“雅集”是文言色彩很浓的词，与口语化的句子不协调。", "游行": "语义：游行要走上街头，与“不能出门”直接矛盾。"}, "sentence_index": 6, "correct_answer": "视频会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在视频会议里玩了一整天。", "explanation": "这里应该用〈游乐园〉。玩耍的场所是游乐园，视频会议是远程开会，不能作为玩耍的地方。"}, {"text": "我们在视频会议上捡了很多贝壳。", "explanation": "这里应该用〈海边〉。捡贝壳要在海边，视频会议是远程开会，不能作为捡东西的地方。"}, {"text": "我们在视频会议上看了日出。", "explanation": "这里应该用〈山上〉。看日出要到山上或海边，视频会议是远程开会，不是一个地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今天开了一条视频会议。", "corrected_sentence": "我们今天开了一场视频会议。", "error_description": "量词误用：会议应用“场”或“次”计量，“条”用于细长的东西，应说“一场视频会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她生病了，只好在家参观视频会议。", "corrected_sentence": "她生病了，只好在家参加视频会议。", "error_description": "搭配错误：会议要说“参加”，“参观”用于看地方或展览，应说“参加视频会议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97013, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "疏远：与“亲密”相反，指关系不近、感情淡薄，是词典收录的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：表示明白、不含糊，与“亲密”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃：指态度庄重或神情认真，与“亲密”没有反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙：指事情多、忙碌，与“亲密”没有反义关系。"}], "correct_answer": "疏远", "explanations": {"疏远": "疏远：与“亲密”相反，指关系不近、感情淡薄，是词典收录的反义词。", "清楚": "清楚：表示明白、不含糊，与“亲密”没有反义关系。", "严肃": "严肃：指态度庄重或神情认真，与“亲密”没有反义关系。", "繁忙": "繁忙：指事情多、忙碌，与“亲密”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97013, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "疏远：与“亲密”相反，指关系不近、感情淡薄，是词典收录的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：指光线充足或颜色鲜亮，与“亲密”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：指空间大，与“亲密”没有反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "辛苦：指劳累或费力，与“亲密”没有反义关系。"}], "correct_answer": "疏远", "explanations": {"疏远": "疏远：与“亲密”相反，指关系不近、感情淡薄，是词典收录的反义词。", "明亮": "明亮：指光线充足或颜色鲜亮，与“亲密”没有反义关系。", "宽敞": "宽敞：指空间大，与“亲密”没有反义关系。", "辛苦": "辛苦：指劳累或费力，与“亲密”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97013, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "关系很好，在一起很开心。", "primary_collocate": null, "pronunciation": "qīn mì", "ipa": "tɕʰin˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "我和同桌的关系很亲密，天天一起玩。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹两个亲密地坐在沙发上聊天。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫和小狗住在一起，很亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他俩亲密得像亲兄弟一样。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们亲密地围坐在一起吃饭。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对好朋友总是手拉着手，很亲密。", "target_word": "亲密", "complexity_tier": "T3", "furigana": "zhè duì hǎo péngyou zǒngshì shǒu lā zhe shǒu hěn qīn mì", "sentence_source": "generated"}, {"text": "爸爸和女儿一起做饭，样子很亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班同学都很亲密，像一家人。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人和孙子亲密地靠在一起。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们亲密地围在一起给他过生日。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲密无间", "label": "成语"}, {"form": "亲密度", "label": "复合"}, {"form": "親密", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关系好在一起很开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲密", "is_correct": true, "explanation": "亲密：两人关系好，与“关系很”搭配，符合“天天一起玩”的语境。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼神，不能用来形容两人的关系。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”说价格高，与“关系”的意思不相合。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”形容湿度或物品状态，不能用来形容两人的关系。"}], "explanations": {"亲密": "亲密：两人关系好，与“关系很”搭配，符合“天天一起玩”的语境。", "明亮": "搭配：“明亮”形容光线或眼神，不能用来形容两人的关系。", "昂贵": "语义：“昂贵”说价格高，与“关系”的意思不相合。", "干燥": "语义：“干燥”形容湿度或物品状态，不能用来形容两人的关系。"}, "sentence_index": 0, "correct_answer": "亲密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "节日的街道很亲密。", "explanation": "这里应该用〈热闹〉。亲密形容人与人之间的关系和感情，说街道、场面的热闹要用热闹。"}, {"text": "今天的天气很亲密。", "explanation": "这里应该用〈暖和〉。亲密形容人与人在一起的关系和感情，描述天气的冷暖要用暖和。"}, {"text": "这两根铁管焊接得很亲密。", "explanation": "这里应该用〈紧密〉。亲密形容人与人之间的感情，金属零件之间的连接要用紧密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲密", "is_correct": true, "explanation": "亲密：形容两人的样子亲近，符合“一起做饭”的画面。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”形容价钱高，不能用来形容人的样子。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境吵，不说“样子嘈杂”。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”形容东西用久了、不新鲜，不能用来形容人在做饭时的样子。"}], "explanations": {"亲密": "亲密：形容两人的样子亲近，符合“一起做饭”的画面。", "昂贵": "语义：“昂贵”形容价钱高，不能用来形容人的样子。", "嘈杂": "搭配：“嘈杂”形容声音或环境吵，不说“样子嘈杂”。", "陈旧": "语义：“陈旧”形容东西用久了、不新鲜，不能用来形容人在做饭时的样子。"}, "sentence_index": 6, "correct_answer": "亲密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两根木头之间很亲密。", "explanation": "亲密只用来形容人与人之间的感情，两根木头之间不能说亲密，这里是误用。"}, {"text": "这份文件和那张表格很亲密。", "explanation": "亲密的对象必须是人，文件和表格之间不能用亲密来形容。"}, {"text": "这块蛋糕和那个盘子很亲密。", "explanation": "亲密不能用来形容物品之间的关系，蛋糕和盘子之间用亲密是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他俩亲密的聊着天。", "corrected_sentence": "他俩亲密地聊着天。", "error_description": "错误形式：“亲密的聊”；正确形式：“亲密地聊”。修饰动词的状语要用“地”，“的”用在名词前，这里应该用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩聊地很亲密。", "corrected_sentence": "他们俩聊得很亲密。", "error_description": "错误形式：“聊地很亲密”；正确形式：“聊得很亲密”。连接动词与程度补语的要用结构助词“得”，“地”是用在状语后的助词，不能用在补语前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
