INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97014, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "关系密切；感情深厚。", "primary_collocate": null, "pronunciation": "qīn mì", "ipa": "tɕʰin˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "他们两家的关系非常亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲和孩子之间的感情很亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人之间的关系很亲密。", "target_word": "亲密", "complexity_tier": "T3", "furigana": "liǎng guó lǐng dǎo rén zhī jiān de guān xì hěn qīn mì", "sentence_source": "generated"}, {"text": "她和老朋友的关系一直很亲密。", "target_word": "亲密", "complexity_tier": "T3", "furigana": "tā hé lǎo péngyou de guān xì yìzhí hěn qīn mì", "sentence_source": "generated"}, {"text": "这对夫妻看起来很亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司和客户的关系越来越亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和同事之间没有那么亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲密的朋友之间也要互相尊重。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从小一起长大，关系很亲密。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的关系变得亲密起来。", "target_word": "亲密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲密无间", "label": "成语"}, {"form": "亲密度", "label": "复合"}, {"form": "親密", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关系密切感情深厚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲密", "is_correct": true, "explanation": "亲密：关系密切、感情深厚，与“关系非常”搭配，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌好看，不能用来形容两家之间的关系。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”说价格高，与“关系”的意思不相合。"}, {"text": "繁忙", "is_correct": false, "explanation": "语义：“繁忙”形容人或事务多、忙碌，不能说关系繁忙。"}], "explanations": {"亲密": "亲密：关系密切、感情深厚，与“关系非常”搭配，符合句意。", "漂亮": "体貌：“漂亮”形容外貌好看，不能用来形容两家之间的关系。", "昂贵": "语义：“昂贵”说价格高，与“关系”的意思不相合。", "繁忙": "语义：“繁忙”形容人或事务多、忙碌，不能说关系繁忙。"}, "sentence_index": 0, "correct_answer": "亲密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个小区离得很亲密。", "explanation": "这里应该用〈近〉。亲密形容人与人之间的感情，两个地方之间的远近要用近。"}, {"text": "这家饭店的服务很亲密。", "explanation": "这里应该用〈亲切〉。亲密指人之间的感情深厚，形容服务态度、待人方式要用亲切。"}, {"text": "这两块木板拼接得很亲密。", "explanation": "这里应该用〈紧密〉。亲密形容人与人之间的感情，木板之间的拼接要用紧密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲密", "is_correct": true, "explanation": "亲密：关系密切；“没有那么亲密”表示关系不太近，符合句意。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼睛，不能用来形容人与人之间的关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体含水分多，不能用来形容同事之间的关系。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音或环境吵闹，不能用来形容同事之间的关系。"}], "explanations": {"亲密": "亲密：关系密切；“没有那么亲密”表示关系不太近，符合句意。", "明亮": "搭配：“明亮”形容光线或眼睛，不能用来形容人与人之间的关系。", "潮湿": "语义：“潮湿”形容空气或物体含水分多，不能用来形容同事之间的关系。", "嘈杂": "语义：“嘈杂”形容声音或环境吵闹，不能用来形容同事之间的关系。"}, "sentence_index": 6, "correct_answer": "亲密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两根电线之间很亲密。", "explanation": "亲密只用来形容人与人之间的感情或关系，电线之间不能说亲密，这里是误用。"}, {"text": "这份合同和原件之间很亲密。", "explanation": "亲密的对象必须是人，合同和原件是文件，二者之间不能用亲密来形容。"}, {"text": "这块石头和那棵树很亲密。", "explanation": "亲密不能用来形容物体之间的关系，石头和树之间用亲密是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩的关系一直很很亲密。", "corrected_sentence": "他们俩的关系一直很亲密。", "error_description": "程度副词“很”只能用一次，不能重复。错误形式：“很很亲密”；正确形式：“很亲密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个孩子亲密的拉着手。", "corrected_sentence": "两个孩子亲密地拉着手。", "error_description": "错误形式：“亲密的拉着”；正确形式：“亲密地拉着”。修饰动词的状语要用“地”，“的”用在名词前，这里应该用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
