INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "嘴里说出来的话。", "primary_collocate": null, "pronunciation": "yán yǔ", "ipa": "jɛn˧˥ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的言语中带着笑意。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别在背后说伤人的言语。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用温柔的言语安慰我。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他听了这些言语，心里很难受。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的几句言语，让我有了信心。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些难听的言语，我不想再听。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用言语安慰着生病的朋友。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冲动时说出的言语，常常让人后悔。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的言语让他很感动。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的言语简短，却让人印象深刻。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "言语：名词，嘴里说出来的一句句话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97015, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指嘴里说出来的话，读 yán yǔ，是正确答案。"}, {"text": "谚语", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是谚语，即流传的俗语。"}, {"text": "韩语", "is_correct": false, "explanation": "hán 与 yán 声母不同（h 与 y），意思是韩国的语言。"}, {"text": "烟雨", "is_correct": false, "explanation": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾般的细雨。"}], "explanations": {"言语": "言语指嘴里说出来的话，读 yán yǔ，是正确答案。", "谚语": "yàn（第四声）与 yán（第二声）声调不同，意思是谚语，即流传的俗语。", "韩语": "hán 与 yán 声母不同（h 与 y），意思是韩国的语言。", "烟雨": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾般的细雨。"}, "sentence_index": null, "correct_answer": "言语"}, "level_3": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指说出来的话，此处“他的言语中带着笑意”正确。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，说不出话，“他的石头中带着笑意”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能带着笑意，“他的桌子中带着笑意”说不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“钢铁”一般形容坚硬，不能与“带着笑意”搭配。"}], "explanations": {"言语": "言语指说出来的话，此处“他的言语中带着笑意”正确。", "石头": "语义：石头是无生命的物体，说不出话，“他的石头中带着笑意”说不通。", "桌子": "语义：桌子不能带着笑意，“他的桌子中带着笑意”说不通。", "钢铁": "搭配：“钢铁”一般形容坚硬，不能与“带着笑意”搭配。"}, "sentence_index": 0, "correct_answer": "言语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花的言语很浓。", "explanation": "这里应该用〈香味〉。言语指嘴里说出的话，不能用来形容花的气味。"}, {"text": "这个言语很香。", "explanation": "这里应该用〈包子〉。言语指嘴里说出的话，不能用来形容食物的香味。"}, {"text": "他把这些言语打包寄走了。", "explanation": "这里应该用〈包裹〉。言语指嘴里说出的话，是抽象的，不能像包裹一样打包寄走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97015, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指嘴里说出来的话，读 yán yǔ，是正确答案。"}, {"text": "延误", "is_correct": false, "explanation": "yán wù 与 yán yǔ 只差后一个音节（wù 与 yǔ），意思是耽误、拖延。"}, {"text": "阴雨", "is_correct": false, "explanation": "yīn（第一声）与 yán（第二声）韵母不同（in 与 an），意思是阴天下雨。"}, {"text": "谚语", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是流传的俗语。"}], "explanations": {"言语": "言语指嘴里说出来的话，读 yán yǔ，是正确答案。", "延误": "yán wù 与 yán yǔ 只差后一个音节（wù 与 yǔ），意思是耽误、拖延。", "阴雨": "yīn（第一声）与 yán（第二声）韵母不同（in 与 an），意思是阴天下雨。", "谚语": "yàn（第四声）与 yán（第二声）声调不同，意思是流传的俗语。"}, "sentence_index": null, "correct_answer": "言语"}, "level_3": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指说出来的话，此处“她用言语安慰朋友”正确。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是书写工具，不能用来安慰人，“她用铅笔安慰”说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不能用来安慰人，句子说不通。"}, {"text": "路灯", "is_correct": false, "explanation": "搭配：“用”之后接的是安慰的手段，路灯不能用来安慰人，搭配不通。"}], "explanations": {"言语": "言语指说出来的话，此处“她用言语安慰朋友”正确。", "铅笔": "语义：铅笔是书写工具，不能用来安慰人，“她用铅笔安慰”说不通。", "河流": "语义：河流是自然景物，不能用来安慰人，句子说不通。", "路灯": "搭配：“用”之后接的是安慰的手段，路灯不能用来安慰人，搭配不通。"}, "sentence_index": 6, "correct_answer": "言语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的言语很高，几乎够不着。", "explanation": "这里应该用〈身材〉。“高”形容人的身高，不能用来形容言语。"}, {"text": "他的言语生病了，今天请假在家。", "explanation": "这里应该用〈身体〉。言语指嘴里说出的话，不能生病、请假。"}, {"text": "他的言语已经五十岁了。", "explanation": "这里应该用〈年龄〉。言语指嘴里说出的话，不能用来说人的岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一头言语很温和，让人安心。", "corrected_sentence": "他的言语很温和，让人安心。", "error_description": "“头”用于牛、猪等动物，不能用来计量言语。正确说法是“他的言语很温和”，应去掉“一头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的几只言语让我很感动。", "corrected_sentence": "他的几句言语让我很感动。", "error_description": "言语应以“句”计量，说“几句言语”。“只”用于动物或成对的东西，不能用来计量言语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
