INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说的话；语言。", "primary_collocate": null, "pronunciation": "yán yǔ", "ipa": "jɛn˧˥ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的言语很温和。", "target_word": "言语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不爱说话，言语很少。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请注意你的言语，别伤人。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的言语里带着一点生气。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的言语很粗俗，大家都不愿和他交谈。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的言语朴实，很多道理都藏在里面。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的言语让我很难过。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学会了用简单的言语表达想法。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间，言语要真诚。", "target_word": "言语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他言语不多，做事却很努力。", "target_word": "言语", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "言语：名词，说的话、言辞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97016, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指说的话，读 yán yǔ，是正确答案。"}, {"text": "谚语", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是谚语，即流传的俗语。"}, {"text": "阴雨", "is_correct": false, "explanation": "yīn（第一声）与 yán（第二声）韵母不同（in 与 an），意思是阴天下雨。"}, {"text": "韩语", "is_correct": false, "explanation": "hán 与 yán 声母不同（h 与 y），意思是韩国的语言。"}], "explanations": {"言语": "言语指说的话，读 yán yǔ，是正确答案。", "谚语": "yàn（第四声）与 yán（第二声）声调不同，意思是谚语，即流传的俗语。", "阴雨": "yīn（第一声）与 yán（第二声）韵母不同（in 与 an），意思是阴天下雨。", "韩语": "hán 与 yán 声母不同（h 与 y），意思是韩国的语言。"}, "sentence_index": null, "correct_answer": "言语"}, "level_3": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指说的话，此处“他的言语很温和”指说话的方式，正确。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能用“很温和”形容，说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能“温和”，“他的桌子很温和”说不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“钢铁”一般形容坚硬，与“温和”搭配不通。"}], "explanations": {"言语": "言语指说的话，此处“他的言语很温和”指说话的方式，正确。", "石头": "语义：石头是无生命的物体，不能用“很温和”形容，说不通。", "桌子": "语义：桌子不能“温和”，“他的桌子很温和”说不通。", "钢铁": "搭配：“钢铁”一般形容坚硬，与“温和”搭配不通。"}, "sentence_index": 0, "correct_answer": "言语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的言语很鲜艳。", "explanation": "这里应该用〈颜色〉。言语指说出的话，不能用来形容衣服的颜色。"}, {"text": "这桌言语很可口。", "explanation": "这里应该用〈饭菜〉。言语指说出的话，不能用来形容饭菜的味道。"}, {"text": "这把椅子的言语很结实。", "explanation": "这里应该用〈质量〉。言语指说的话，不能用来说椅子结实与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97016, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指说的话，读 yán yǔ，是正确答案。"}, {"text": "延误", "is_correct": false, "explanation": "yán wù 与 yán yǔ 只差后一个音节（wù 与 yǔ），意思是耽误、拖延。"}, {"text": "烟雨", "is_correct": false, "explanation": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾般的细雨。"}, {"text": "谚语", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是流传的俗语。"}], "explanations": {"言语": "言语指说的话，读 yán yǔ，是正确答案。", "延误": "yán wù 与 yán yǔ 只差后一个音节（wù 与 yǔ），意思是耽误、拖延。", "烟雨": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾般的细雨。", "谚语": "yàn（第四声）与 yán（第二声）声调不同，意思是流传的俗语。"}, "sentence_index": null, "correct_answer": "言语"}, "level_3": {"options": [{"text": "言语", "is_correct": true, "explanation": "言语指说的话，此处“你的言语让我很难过”指你说的话，正确。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不会让人难过，“你的花瓶让我很难过”说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不能使人“很难过”，句子说不通。"}, {"text": "路灯", "is_correct": false, "explanation": "搭配：“路灯”不能作“让我很难过”的主语，搭配不通。"}], "explanations": {"言语": "言语指说的话，此处“你的言语让我很难过”指你说的话，正确。", "花瓶": "语义：花瓶是器物，不会让人难过，“你的花瓶让我很难过”说不通。", "河流": "语义：河流是自然景物，不能使人“很难过”，句子说不通。", "路灯": "搭配：“路灯”不能作“让我很难过”的主语，搭配不通。"}, "sentence_index": 6, "correct_answer": "言语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把言语放进了箱子里。", "explanation": "这里应该用〈东西〉。言语指说出的话，是抽象的，不能当作有形的物品放进箱子。"}, {"text": "他的言语很粗壮。", "explanation": "这里应该用〈体格〉。粗壮形容身体，不能用来形容言语。"}, {"text": "他的言语有一米八。", "explanation": "这里应该用〈身高〉。言语指说出的话，不能用来表示人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的一把言语总是很有礼貌。", "corrected_sentence": "她的言语总是很有礼貌。", "error_description": "“言语”是抽象名词，不能用“把”计量（“把”用于有柄的器具）。正确说法是“她的言语”，应去掉“一把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的几座言语让我想了很久。", "corrected_sentence": "他的几句言语让我想了很久。", "error_description": "“言语”应以“句”计量，说“几句言语”。“座”用于山、房屋等大型固定物，不能用来计量言语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
