INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97017, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在心里先想一想事情会怎么样。", "primary_collocate": null, "pronunciation": "shè xiǎng", "ipa": "ʂɤ˥˩ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "出发以前，我先设想了一下路上的情况。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我设想过很多次，明年自己开一家小店。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她设想了面试官可能问的问题。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，经理先设想了几种结果。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先设想一下，十年后的城市是什么样。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有设想过，事情会这么顺利。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们设想了三个办法，最后选了第二个。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划时，要先设想可能出现的问题。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子设想着长大后坐飞机去很远的地方。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没设想过，雨会下得这么大。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设想了", "label": "体标（了）"}, {"form": "设想过", "label": "体标（过）"}, {"form": "设想着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "事先在心里想事情将会怎样发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设想", "is_correct": true, "explanation": "正确：“设想”指事先在心里想象，可以与“先……了一下”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“情况”，“吃情况”没有这种说法。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”不能接“情况”，“撕情况”没有这种说法。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏物，与“路上的情况”不相干。"}], "explanations": {"设想": "正确：“设想”指事先在心里想象，可以与“先……了一下”搭配。", "吃": "搭配：“吃”不能接“情况”，“吃情况”没有这种说法。", "撕": "搭配：“撕”不能接“情况”，“撕情况”没有这种说法。", "打扫": "语义：“打扫”指清除脏物，与“路上的情况”不相干。"}, "sentence_index": 0, "correct_answer": "设想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在地下设想了一座古墓。", "explanation": "这里应该用〈发现〉。发现指找到已经存在的东西，设想只是事先在心里想象，不能用于真实存在的古墓。"}, {"text": "医生仔细设想了病人的伤口。", "explanation": "这里应该用〈检查〉。医生用眼睛和仪器查看伤口，设想只是心里的想象，不能表示查看实物。"}, {"text": "师傅用扳手设想了那辆自行车。", "explanation": "这里应该用〈修〉。用扳手修车是实际动作，设想只是心里的预想，不能表示动手修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设想", "is_correct": true, "explanation": "正确：“设想了三个办法”指事先在心里想出几种办法，与“最后选了第二个”衔接。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记了办法就无法再从中选择，与“最后选了第二个”矛盾。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”不能接“办法”，“吃掉办法”没有这种说法。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能用于“办法”，“拍办法”没有这种说法。"}], "explanations": {"设想": "正确：“设想了三个办法”指事先在心里想出几种办法，与“最后选了第二个”衔接。", "忘记": "语义：忘记了办法就无法再从中选择，与“最后选了第二个”矛盾。", "吃掉": "搭配：“吃掉”不能接“办法”，“吃掉办法”没有这种说法。", "拍": "搭配：“拍”不能用于“办法”，“拍办法”没有这种说法。"}, "sentence_index": 6, "correct_answer": "设想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把每天的气温设想在本子上。", "explanation": "这里应该用〈记录〉。把数据写在本子上是记录，设想只是心里的预想，不能用来写下已有的数据。"}, {"text": "他用抹布设想了桌子上的灰尘。", "explanation": "这里应该用〈擦〉。擦灰尘是实际的动作，设想是心里的活动，不能用于动作。"}, {"text": "工人给墙设想了一层漆。", "explanation": "这里应该用〈涂〉。把漆涂在墙上是实际的动作，设想不能用于这种动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他设想了过很多种可能。", "corrected_sentence": "他设想过很多种可能。", "error_description": "体标重复：“设想”后面只用“过”或“了”之一，表示曾经有过的经历应说“设想过”，不能同时用“了”和“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没设想了这种结果。", "corrected_sentence": "我从没设想过这种结果。", "error_description": "体标错误：“从没”表示从未有过的经历，要用“过”，不能用“了”，应说“从没设想过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
