INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说假话骗别人的钱或东西。", "primary_collocate": null, "pronunciation": "zhà piàn", "ipa": "ʈʂa˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "有人打电话诈骗老人的钱。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用假身份诈骗了很多人。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陌生人在网上诈骗我的钱。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男人诈骗朋友三万块钱。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子常常诈骗不懂手机的老人。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己是医生，其实是想诈骗。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察提醒大家，小心有人诈骗。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠诈骗别人的钱生活。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要相信陌生人，他可能想诈骗你。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人诈骗过很多学生。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诈骗了", "label": "完成体"}, {"form": "诈骗过", "label": "经历体"}, {"form": "诈骗犯", "label": "复合"}, {"form": "詐騙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说假话骗取别人钱物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97019, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诈骗", "is_correct": true, "explanation": "诈骗：用说假话的方式骗取钱财，与“打电话”和“老人的钱”的语境相合。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：“赠送”是白白给予，与句中骗取钱财的语境相反。"}, {"text": "访问", "is_correct": false, "explanation": "搭配：“访问”的对象是人或机构，不说“访问老人的钱”。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆祝，和“老人的钱”搭配不成合理的句子。"}], "explanations": {"诈骗": "诈骗：用说假话的方式骗取钱财，与“打电话”和“老人的钱”的语境相合。", "赠送": "语义：“赠送”是白白给予，与句中骗取钱财的语境相反。", "访问": "搭配：“访问”的对象是人或机构，不说“访问老人的钱”。", "祝贺": "语义：“祝贺”表示庆祝，和“老人的钱”搭配不成合理的句子。"}, "sentence_index": 0, "correct_answer": "诈骗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他趁人不注意，诈骗了别人的手机。", "explanation": "这里应该用〈盗窃〉。诈骗靠说假话骗取财物，趁人不注意暗中拿走东西要用盗窃。"}, {"text": "他用暴力诈骗了朋友三万块钱。", "explanation": "这里应该用〈抢劫〉。诈骗靠说假话骗取财物，用暴力当场夺取财物要用抢劫。"}, {"text": "他靠力气诈骗了朋友的自行车。", "explanation": "这里应该用〈抢〉。诈骗靠说假话骗取财物，靠力气夺走东西要用抢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诈骗", "is_correct": true, "explanation": "诈骗：正是警察提醒大家要防范的行为，与“小心”的语境相合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“小心有人”的提醒语境不符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示热情接待，不能和“小心有人”连用成提醒。"}, {"text": "颁布", "is_correct": false, "explanation": "语义：“颁布”的对象是法令、规定等，不能用来说人对别人做的坏事，与提醒语境不符。"}], "explanations": {"诈骗": "诈骗：正是警察提醒大家要防范的行为，与“小心”的语境相合。", "表扬": "语义：“表扬”是称赞，与“小心有人”的提醒语境不符。", "欢迎": "语义：“欢迎”表示热情接待，不能和“小心有人”连用成提醒。", "颁布": "语义：“颁布”的对象是法令、规定等，不能用来说人对别人做的坏事，与提醒语境不符。"}, "sentence_index": 6, "correct_answer": "诈骗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头诈骗了我三百块钱。", "explanation": "诈骗的施事必须是能编造谎言的人，石头不能施骗，这里不能用诈骗。"}, {"text": "这张桌子诈骗了我的积蓄。", "explanation": "诈骗的施事必须是能说谎的人，桌子不能施骗，这里是误用。"}, {"text": "天气诈骗了我们的钱。", "explanation": "诈骗的施事必须是能编造谎言的人，天气不能施骗，这里不能用诈骗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人去年诈骗着很多学生的钱。", "corrected_sentence": "那个人去年诈骗了很多学生的钱。", "error_description": "错误形式：“诈骗着”；正确形式：“诈骗了”。“去年”表示已完成的过去事件，应用完成体“了”，“着”表示持续，不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个骗子诈骗了过很多老人。", "corrected_sentence": "那个骗子诈骗过很多老人。", "error_description": "错误形式：“诈骗了过”；正确形式：“诈骗过”。表示经历只用“过”，“了”和“过”不能连用在同一个动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
