INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用欺骗的方法获取财物。", "primary_collocate": null, "pronunciation": "zhà piàn", "ipa": "ʈʂa˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "警察抓住了诈骗他人财物的人。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司用假合同诈骗客户的钱。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他诈骗了一百多万元。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，诈骗别人的财物是犯罪。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们团伙专门诈骗银行客户。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们通过假网站诈骗客户的钱财。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用假发票诈骗公司的钱。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认定他诈骗了不少财物。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他假装投资，诈骗了十几个人的钱。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经因为诈骗坐过牢。", "target_word": "诈骗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诈骗了", "label": "完成体"}, {"form": "诈骗过", "label": "经历体"}, {"form": "诈骗罪", "label": "复合"}, {"form": "詐騙", "label": "繁体"}], "register": "书面", "sense_fingerprint": "以欺骗手段获取财物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1637d622-b7a2-4a01-9ab5-6c78e5b29999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诈骗", "is_correct": true, "explanation": "诈骗：用欺骗手段获取财物，与“抓住”的违法语境相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫，与句中被抓的违法者的身份相反。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：“赠送”是给予，不是需要警察抓捕的行为。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多用于艺术作品或景色，不说“欣赏他人财物”。"}], "explanations": {"诈骗": "诈骗：用欺骗手段获取财物，与“抓住”的违法语境相合。", "保护": "语义：“保护”是护卫，与句中被抓的违法者的身份相反。", "赠送": "语义：“赠送”是给予，不是需要警察抓捕的行为。", "欣赏": "搭配：“欣赏”多用于艺术作品或景色，不说“欣赏他人财物”。"}, "sentence_index": 0, "correct_answer": "诈骗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地铁上一把诈骗了别人的包。", "explanation": "这里应该用〈抢夺〉。诈骗靠说谎骗取财物，当场伸手夺走别人的包要用抢夺。"}, {"text": "他诈骗了朋友的一个秘密。", "explanation": "这里应该用〈套取〉。诈骗骗取的是财物，从对方那里套出秘密、信息要用套取。"}, {"text": "歹徒持刀诈骗了一家商店。", "explanation": "这里应该用〈抢劫〉。诈骗靠说谎骗取财物，持刀当场夺取财物要用抢劫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诈骗", "is_correct": true, "explanation": "诈骗：用假发票骗取钱财，与“假发票”和“钱”的语境相合。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：“印刷”的对象是文字或图案，不说“印刷公司的钱”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是表达谢意，不能用在用假发票取钱的语境中。"}, {"text": "保管", "is_correct": false, "explanation": "语义：“保管”是妥善存放，与用假发票取钱的语境矛盾。"}], "explanations": {"诈骗": "诈骗：用假发票骗取钱财，与“假发票”和“钱”的语境相合。", "印刷": "搭配：“印刷”的对象是文字或图案，不说“印刷公司的钱”。", "感谢": "语义：“感谢”是表达谢意，不能用在用假发票取钱的语境中。", "保管": "语义：“保管”是妥善存放，与用假发票取钱的语境矛盾。"}, "sentence_index": 6, "correct_answer": "诈骗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子诈骗了我三百块钱。", "explanation": "诈骗的施事必须是能编造谎言的人，桌子不能施骗，这里不能用诈骗。"}, {"text": "天气诈骗了我的积蓄。", "explanation": "诈骗的施事必须是能说谎的人，天气不能施骗，这里是误用。"}, {"text": "空调诈骗了我的电费。", "explanation": "诈骗的施事必须是能编造谎言的人，空调不能施骗，这里不能用诈骗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年诈骗着一百多万元。", "corrected_sentence": "他去年诈骗了一百多万元。", "error_description": "错误形式：“诈骗着”；正确形式：“诈骗了”。已完成的过去事件要用完成体“了”，“着”表示持续，不能与数量结果连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团伙曾经诈骗了过多家银行的客户。", "corrected_sentence": "这个团伙曾经诈骗过多家银行的客户。", "error_description": "错误形式：“诈骗了过”；正确形式：“诈骗过”。“曾经”表示经历，只用“过”，“了”和“过”不能连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da1aded-452a-49c9-a989-5fcd518132c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97021, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97021, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97021, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看一看，想一想，说好不好。", "primary_collocate": null, "pronunciation": "píng shěn", "ipa": "pʰiŋ˧˥ ʂən˨˩˦", "syllable_count": 2, "sentences": [{"text": "美术课上，老师请同学们评审彼此的画。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Měi shù kè shàng, lǎo shī qǐng tóng xué men píng shěn bǐ cǐ de huà.", "sentence_source": "generated"}, {"text": "这次厨艺比赛，评委们评审了每一道菜。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Zhè cì chú yì bǐ sài, píng wěi men píng shěn le měi yí dào cài.", "sentence_source": "generated"}, {"text": "同学们互相评审对方的作文。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手工比赛，老师请家长一起评审作品。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Zhè cì shǒu gōng bǐ sài, lǎo shī qǐng jiā zhǎng yì qǐ píng shěn zuò pǐn.", "sentence_source": "generated"}, {"text": "辩论赛结束后，裁判认真评审了双方的发言。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Biàn lùn sài jié shù hòu, cái pàn rèn zhēn píng shěn le shuāng fāng de fā yán.", "sentence_source": "generated"}, {"text": "音乐社的同学们一起评审了新歌。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Yīn yuè shè de tóng xué men yì qǐ píng shěn le xīn gē.", "sentence_source": "generated"}, {"text": "这首诗好不好，请大家来评审。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班想请老师评审一下新的板报设计。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Wǒ men bān xiǎng qǐng lǎo shī píng shěn yí xià xīn de bǎn bào shè jì.", "sentence_source": "generated"}, {"text": "老师们认真评审了每位选手的表演。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Lǎo shī men rèn zhēn píng shěn le měi wèi xuǎn shǒu de biǎo yǎn.", "sentence_source": "generated"}, {"text": "你先把几篇稿子评审一遍，再告诉我哪篇好。", "target_word": "评审", "complexity_tier": "T3", "furigana": "Nǐ xiān bǎ jǐ piān gǎozi píng shěn yí biàn, zài gàosu wǒ nǎ piān hǎo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "评审了", "label": "体标"}, {"form": "评审着", "label": "体标"}, {"form": "评审一下", "label": "动量"}], "register": "中性", "sense_fingerprint": "看过想过之后，说出某物好不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评审", "is_correct": true, "explanation": "正确。老师请同学们看看想想，说彼此的画好不好，符合语境。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”的对象是食物或味道，不能说“尝彼此的画”。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”是不及物动词，后面不能直接带“彼此的画”这样的宾语。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是把东西扯破，老师不会请同学们“撕彼此的画”，与评判画好不好的语境不合。"}], "explanations": {"评审": "正确。老师请同学们看看想想，说彼此的画好不好，符合语境。", "尝": "搭配：“尝”的对象是食物或味道，不能说“尝彼此的画”。", "见面": "配价：“见面”是不及物动词，后面不能直接带“彼此的画”这样的宾语。", "撕": "语义：“撕”是把东西扯破，老师不会请同学们“撕彼此的画”，与评判画好不好的语境不合。"}, "sentence_index": 0, "correct_answer": "评审"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家每天评审日出的变化，并把它记录下来。", "explanation": "这里应该用〈观察〉。评审是评定好坏，记录现象的变化要用观察。"}, {"text": "妈妈每天都评审我的校服，把它们弄得干干净净。", "explanation": "这里应该用〈洗〉。评审是评定好坏，清洗衣物要用洗。"}, {"text": "我先评审一下手机，再把它插上充电器。", "explanation": "这里应该用〈充〉。评审是评定好坏，给手机充电要用充。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评审", "is_correct": true, "explanation": "正确。请大家对诗作出好坏的判断，符合语境。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热做饭，与判断诗好不好无关。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间或场地，不能用来指评判一首诗。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是休息，与“请大家来”判断诗好不好的意思不合。"}], "explanations": {"评审": "正确。请大家对诗作出好坏的判断，符合语境。", "煮": "语义：“煮”是加热做饭，与判断诗好不好无关。", "打扫": "搭配：“打扫”的对象是房间或场地，不能用来指评判一首诗。", "睡": "语义：“睡”是休息，与“请大家来”判断诗好不好的意思不合。"}, "sentence_index": 6, "correct_answer": "评审"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生每天都要评审病人的体温。", "explanation": "这里应该用〈检查〉。评审是评定好坏，量体温、看身体状况要用检查。"}, {"text": "工人正在评审房间的面积。", "explanation": "这里应该用〈测量〉。评审是评议好坏，量面积要用测量。"}, {"text": "司机每天都评审汽车的油箱。", "explanation": "这里应该用〈加油〉。评审是评定好坏，给车添油要用加油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师评审了完我的作文。", "corrected_sentence": "老师评审完了我的作文。", "error_description": "错误在“完”的位置。“完”是结果补语，要紧跟在动词后面，应说“评审完了”，不能说“评审了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把这篇作文评审一个。", "corrected_sentence": "请你把这篇作文评审一下。", "error_description": "错误在量词。“评审”的动作次数要用动量词，如“一下”“一遍”；“个”是名量词，不能放在动词后面表示动作次数，应说“评审一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
