INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "评议审查。", "primary_collocate": null, "pronunciation": "píng shěn", "ipa": "pʰiŋ˧˥ ʂən˨˩˦", "syllable_count": 2, "sentences": [{"text": "专家正在评审这个设计方案。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们评审了所有的参赛作品。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目明天上午评审。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要评审他们的申请材料。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们评审过三百份报告。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请外面的专家来评审这份计划。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些论文由五位老师一起评审。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们怎么评审参赛的歌曲，我不清楚。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你们认真评审，不要太快。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评审这本书花了他们两个星期。", "target_word": "评审", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评审了", "label": "体标"}, {"form": "评审过", "label": "体标"}, {"form": "评审员", "label": "复合"}], "register": "书面", "sense_fingerprint": "专家或老师正式评议并审查方案、作品、材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评审", "is_correct": true, "explanation": "正确。“评审”指评议审查，专家对设计方案的正式评议用它。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”是不及物动词，后面不能直接带“这个设计方案”这样的宾语。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃设计方案”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱设计方案”。"}], "explanations": {"评审": "正确。“评审”指评议审查，专家对设计方案的正式评议用它。", "见面": "配价：“见面”是不及物动词，后面不能直接带“这个设计方案”这样的宾语。", "吃": "搭配：“吃”的对象是食物，不能说“吃设计方案”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱设计方案”。"}, "sentence_index": 0, "correct_answer": "评审"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在评审地上的纸屑，弯着腰忙了半天。", "explanation": "这里应该用〈捡〉。评审是评议作品或方案，拾起地上的纸屑要用捡。"}, {"text": "老师当众评审了他的错误。", "explanation": "这里应该用〈批评〉。评审是评议作品或方案，指出别人的错误要用批评。"}, {"text": "他每天早上都评审牙齿。", "explanation": "这里应该用〈刷〉。评审是评议作品或方案，清洁牙齿要用刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评审", "is_correct": true, "explanation": "正确。五位老师对论文进行评议审查，符合语境。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是扯破，与老师评议论文的意思不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热做食物，与论文无关。"}, {"text": "骑", "is_correct": false, "explanation": "配价：“骑”要求可以骑乘的宾语，“论文”不能被骑。"}], "explanations": {"评审": "正确。五位老师对论文进行评议审查，符合语境。", "撕": "语义：“撕”是扯破，与老师评议论文的意思不合。", "煮": "语义：“煮”是加热做食物，与论文无关。", "骑": "配价：“骑”要求可以骑乘的宾语，“论文”不能被骑。"}, "sentence_index": 6, "correct_answer": "评审"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生每天都要评审病人的血压。", "explanation": "这里应该用〈检查〉。评审是评议作品或方案，量血压、查身体要用检查。"}, {"text": "厨房里的阿姨每天都评审炉子的温度，很费心。", "explanation": "这里应该用〈调〉。评审是评议作品或方案，调节炉火的温度要用调。"}, {"text": "工人正在评审坏掉的水管。", "explanation": "这里应该用〈维修〉。评审是评议作品或方案，修理坏掉的东西要用维修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天评审过这个方案。", "corrected_sentence": "我明天评审这个方案。", "error_description": "错误在“过”。“过”表示已经完成的动作，不能和“明天”这样的将来时间词一起用。正确说法是“我明天评审这个方案”，去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师们评审很仔细。", "corrected_sentence": "老师们评审得很仔细。", "error_description": "错误在“得”。“很仔细”是描写评审方式的程度补语，中间要用“得”连接，应说“评审得很仔细”，不能说“评审很仔细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
