INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97023, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说话算话，不骗人。", "primary_collocate": null, "pronunciation": "chéng xìn", "ipa": "ʈʂʰɤŋ˧˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他做生意很诚信，从不骗人。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说到做到，是个诚信的孩子。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要诚信，答应别人的事就要做到。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店对客人很诚信，不卖假东西。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话算话，大家都说她很诚信。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要教孩子诚信，不能说谎。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一向诚信，所以朋友都愿意帮他。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很诚信，说好三天送到就三天送到。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不诚信的人，别人不会相信他。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话都做到了，很诚信。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诚信度", "label": "复合"}, {"form": "不诚信", "label": "否定"}], "register": "中性", "sense_fingerprint": "说到做到，不骗人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97023, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诚信", "is_correct": true, "explanation": "正确答案：诚信（chéng xìn），意思是说话算话、不骗人。"}, {"text": "诚心", "is_correct": false, "explanation": "声调不同：“诚心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是真心、实意。"}, {"text": "成心", "is_correct": false, "explanation": "声调不同：“成心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是故意。"}, {"text": "征信", "is_correct": false, "explanation": "声母不同：“征信”读 zhēng xìn，zh 与 ch 不同，首字也是一声，意思是征集信息或信用调查。"}], "explanations": {"诚信": "正确答案：诚信（chéng xìn），意思是说话算话、不骗人。", "诚心": "声调不同：“诚心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是真心、实意。", "成心": "声调不同：“成心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是故意。", "征信": "声母不同：“征信”读 zhēng xìn，zh 与 ch 不同，首字也是一声，意思是征集信息或信用调查。"}, "sentence_index": null, "correct_answer": "诚信"}, "level_3": {"options": [{"text": "诚信", "is_correct": true, "explanation": "正确。“诚信”形容做生意说话算话、不骗人，符合语境。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容心情难过，不能用来描述做生意的人的品行。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写身高，不能用来形容做生意的为人。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写体型，不能用来形容做生意的为人。"}], "explanations": {"诚信": "正确。“诚信”形容做生意说话算话、不骗人，符合语境。", "悲伤": "语义：“悲伤”形容心情难过，不能用来描述做生意的人的品行。", "矮": "体貌：“矮”描写身高，不能用来形容做生意的为人。", "瘦": "体貌：“瘦”描写体型，不能用来形容做生意的为人。"}, "sentence_index": 0, "correct_answer": "诚信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她诚信地关心每一位同学。", "explanation": "这里应该用〈真诚〉。诚信说的是守信不骗人，表达感情的态度真挚要用真诚。"}, {"text": "他见到老朋友很诚信，拉着手不放。", "explanation": "这里应该用〈热情〉。诚信说的是守信不骗人，见面时的亲切要用热情。"}, {"text": "这台电脑质量很诚信，用了三年没出过问题。", "explanation": "这里应该用〈可靠〉。诚信用来形容人的为人，机器质量稳定要用可靠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诚信", "is_correct": true, "explanation": "正确。“诚信”说明他守信不骗人，所以朋友愿意帮他，符合语境。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”形容性情残暴，与“朋友都愿意帮他”的语境矛盾。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”形容价格或物品，不能用来形容人的品行。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”形容人枯燥乏味，与“朋友都愿意帮他”的语境不合。"}], "explanations": {"诚信": "正确。“诚信”说明他守信不骗人，所以朋友愿意帮他，符合语境。", "凶狠": "语义：“凶狠”形容性情残暴，与“朋友都愿意帮他”的语境矛盾。", "贵": "搭配：“贵”形容价格或物品，不能用来形容人的品行。", "无聊": "语义：“无聊”形容人枯燥乏味，与“朋友都愿意帮他”的语境不合。"}, "sentence_index": 6, "correct_answer": "诚信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜很诚信，我每次都吃得饱饱的。", "explanation": "这里应该用〈好吃〉。诚信说的是守信不骗人，形容味道要用好吃。"}, {"text": "这孩子很诚信，一学就会。", "explanation": "这里应该用〈聪明〉。诚信说的是品行，学得快要用聪明。"}, {"text": "爷爷身体很诚信，每天都去公园散步。", "explanation": "这里应该用〈健康〉。诚信是品德，身体状况要用健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老板很非常诚信，从不欺骗客户。", "corrected_sentence": "这位老板很诚信，从不欺骗客户。", "error_description": "错误在程度副词叠用。“很”和“非常”都表示程度，同一位置只用其一，应说“这位老板很诚信”，不能说“很非常诚信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板是个很诚信人，说好的事一定做到。", "corrected_sentence": "老板是个很诚信的人，说好的事一定做到。", "error_description": "错误在“的”。“很诚信”修饰“人”时要用“的”连接，应说“很诚信的人”，漏掉“的”就不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
