INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97024, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "诚实守信。", "primary_collocate": null, "pronunciation": "chéng xìn", "ipa": "ʈʂʰɤŋ˧˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "她是一个非常诚信的人。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生都很诚信。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诚信的员工，公司都喜欢。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他诚信又努力，大家都信任他。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理很诚信，既不说假话，也守约定。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意的人最好诚信一点。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就诚信，从不撒谎。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人诚信可靠，值得信任。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一位诚信的合作伙伴。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩都很诚信，合作得很愉快。", "target_word": "诚信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诚信度", "label": "复合"}, {"form": "不诚信", "label": "否定"}], "register": "中性", "sense_fingerprint": "为人诚实，遵守约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诚信", "is_correct": true, "explanation": "正确答案：诚信（chéng xìn），意思是诚实守信。"}, {"text": "诚心", "is_correct": false, "explanation": "声调不同：“诚心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是真心、实意。"}, {"text": "成心", "is_correct": false, "explanation": "声调不同：“成心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是故意。"}, {"text": "征信", "is_correct": false, "explanation": "声母不同：“征信”读 zhēng xìn，zh 与 ch 不同，首字也是一声，意思是征集信息或信用调查。"}], "explanations": {"诚信": "正确答案：诚信（chéng xìn），意思是诚实守信。", "诚心": "声调不同：“诚心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是真心、实意。", "成心": "声调不同：“成心”读 chéng xīn，末字是一声，与“诚信”的四声不同，意思是故意。", "征信": "声母不同：“征信”读 zhēng xìn，zh 与 ch 不同，首字也是一声，意思是征集信息或信用调查。"}, "sentence_index": null, "correct_answer": "诚信"}, "level_3": {"options": [{"text": "诚信", "is_correct": true, "explanation": "正确。“诚信”形容她为人诚实守信，符合语境。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能用来形容一个人。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势，与描写人的性格无关。"}, {"text": "可口", "is_correct": false, "explanation": "搭配：“可口”形容食物的味道，不能用来形容人。"}], "explanations": {"诚信": "正确。“诚信”形容她为人诚实守信，符合语境。", "宽敞": "搭配：“宽敞”形容空间，不能用来形容一个人。", "陡峭": "语义：“陡峭”形容地势，与描写人的性格无关。", "可口": "搭配：“可口”形容食物的味道，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "诚信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很诚信，每天都学习到深夜。", "explanation": "这里应该用〈勤奋〉。诚信指诚实守信，形容学习刻苦要用勤奋。"}, {"text": "她很诚信，一学就会。", "explanation": "这里应该用〈聪明〉。诚信说的是品行，学得快要用聪明。"}, {"text": "他很诚信，常常逗大家笑。", "explanation": "这里应该用〈幽默〉。诚信说的是守信不骗人，让人发笑要用幽默。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诚信", "is_correct": true, "explanation": "正确。“诚信”说明他从小就守信不撒谎，符合语境。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”形容温度，与人的品行无关。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气或物体，不能用来形容人的品行。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，与人从小的品行无关。"}], "explanations": {"诚信": "正确。“诚信”说明他从小就守信不撒谎，符合语境。", "烫": "语义：“烫”形容温度，与人的品行无关。", "干燥": "搭配：“干燥”形容空气或物体，不能用来形容人的品行。", "咸": "语义：“咸”形容味道，与人从小的品行无关。"}, "sentence_index": 6, "correct_answer": "诚信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很诚信，从不浪费水电。", "explanation": "这里应该用〈节约〉。诚信指守信不骗人，不浪费要用节约。"}, {"text": "这个孩子很诚信，一刻也闲不住。", "explanation": "这里应该用〈活泼〉。诚信说的是品行，爱动、精力旺要用活泼。"}, {"text": "老师很诚信，声音大得全校都能听见。", "explanation": "这里应该用〈洪亮〉。诚信说的是守信不骗人，声音响亮要用洪亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位医生是个非常诚信人，从不隐瞒病情。", "corrected_sentence": "那位医生是个非常诚信的人，从不隐瞒病情。", "error_description": "错误在“的”。“诚信”修饰“人”时要用“的”连接，应说“非常诚信的人”，漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩很非常诚信，都守时守约。", "corrected_sentence": "他们俩很诚信，都守时守约。", "error_description": "错误在程度副词叠用。“很”和“非常”都表示程度，同一位置只用其一，应说“他们俩很诚信”，不能说“很非常诚信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
