INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97025, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在一个工作里做了很多年，很有经验。", "primary_collocate": null, "pronunciation": "zī shēn", "ipa": "tsz̩˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "小李刚来公司，老张已在这里干了二十年，是资深员工。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了二十年司机，是个资深司机。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题，可以问问资深的同事。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是资深护士，打针一点也不疼。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位资深导游去过很多国家。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸是资深木匠，做了一辈子家具。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请资深老师来帮新老师看看教案。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行工作多年，是资深的经理。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有几位资深理发师。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资深的老师讲课，大家都听得懂。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个工作做了很多年，很有经验", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年纪轻，与“已在这里干了二十年”的资历相矛盾。"}, {"text": "资深", "is_correct": true, "explanation": "正确：“资深”指在某个工作里做了很多年、很有经验，与老张是老员工相符。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：“嫩”不能直接修饰“员工”，说“嫩员工”不通，而且“嫩”表示经验少，也与老张干了二十年相矛盾。"}, {"text": "年幼", "is_correct": false, "explanation": "语义：“年幼”指年纪很小，与“老张”和干了二十年的员工身份都不相符。"}], "explanations": {"年轻": "语义：“年轻”说年纪轻，与“已在这里干了二十年”的资历相矛盾。", "资深": "正确：“资深”指在某个工作里做了很多年、很有经验，与老张是老员工相符。", "嫩": "搭配：“嫩”不能直接修饰“员工”，说“嫩员工”不通，而且“嫩”表示经验少，也与老张干了二十年相矛盾。", "年幼": "语义：“年幼”指年纪很小，与“老张”和干了二十年的员工身份都不相符。"}, "sentence_index": 0, "correct_answer": "资深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他修车修得很资深。", "explanation": "这里应该用〈熟练〉。资深说的是在某工作里做了多年，形容动作或技术的熟练程度要用熟练。"}, {"text": "这个小男孩做事很资深，像个大人似的。", "explanation": "这里应该用〈成熟〉。资深指在某个工作里做了很多年、有经验，不能用来形容小孩做事稳重；形容做事稳重、不像小孩，要用成熟。"}, {"text": "这棵大树很资深。", "explanation": "这里应该用〈古老〉。资深只用于人的工作经历，不能形容树木；说树龄长要用古老。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容人不肯做事，与“请来帮新老师看教案”的求助目的相矛盾。"}, {"text": "资深", "is_correct": true, "explanation": "正确：“资深”指在工作中积累了多年经验，适合用来形容被请来指导的老教师。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”指不熟悉、不熟练，与“请来帮新老师看教案”的求助目的相矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”形容认识或讲述的明白程度，不修饰“老师”这类身份名词，说“清楚老师”不通。"}], "explanations": {"懒惰": "语义：“懒惰”形容人不肯做事，与“请来帮新老师看教案”的求助目的相矛盾。", "资深": "正确：“资深”指在工作中积累了多年经验，适合用来形容被请来指导的老教师。", "生疏": "语义：“生疏”指不熟悉、不熟练，与“请来帮新老师看教案”的求助目的相矛盾。", "清楚": "搭配：“清楚”形容认识或讲述的明白程度，不修饰“老师”这类身份名词，说“清楚老师”不通。"}, "sentence_index": 6, "correct_answer": "资深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对这条路很资深，闭着眼也能走。", "explanation": "这里应该用〈熟悉〉。资深指在某个工作里做了很多年、很有经验，对路况的了解要用熟悉。"}, {"text": "我刚学会骑车，就是资深车手。", "explanation": "这里应该用〈新手〉。资深指在某个工作里做了很多年、很有经验；刚学会骑车的人是新手，不能称资深车手。"}, {"text": "这个苹果很资深，你尝尝看。", "explanation": "这里应该用〈新鲜〉。资深只用于人的工作经历，不能形容水果；说水果刚摘下、不陈旧，要用新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在这家餐厅干了十年，是一只资深厨师。", "corrected_sentence": "我在这家餐厅干了十年，是一位资深厨师。", "error_description": "量词错误：“厨师”指人，量词应用“位”或“名”，“只”多用于动物等，不能用来数人。应改为“一位资深厨师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请一位很资深老师来看看我的论文。", "corrected_sentence": "请一位资深老师来看看我的论文。", "error_description": "“很”修饰作定语的“资深”时，名词前须带“的”（如“很资深的老师”）；这里“一位很资深老师”缺“的”，应说“一位资深老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
