INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97026, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在某一行业有多年经验的。", "primary_collocate": null, "pronunciation": "zī shēn", "ipa": "tsz̩˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "他是一位资深记者，采访过很多大人物。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院请了一位资深医生来给大家上课。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资深律师告诉我，这个官司很难赢。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了三十年老师，是学校里最资深的老师。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找一位资深设计师来带新人。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王师傅是我们厂里最资深的工人。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位资深厨师做了四十年菜。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是新手，而是一位资深的编辑。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请资深会计帮忙检查了这些账。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是几位资深翻译家一起翻译的。", "target_word": "资深", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在某一行业有多年经验的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼小", "is_correct": false, "explanation": "语义：“幼小”指年纪很小，不能形容记者，也与“采访过很多大人物”相矛盾。"}, {"text": "资深", "is_correct": true, "explanation": "正确：“资深”指在行业里工作多年、经验丰富，与“采访过很多大人物”相符。"}, {"text": "初级", "is_correct": false, "explanation": "语义：“初级”指等级低，与“采访过很多大人物”的资历不符。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：“嫩”不能直接修饰“记者”，说“一位嫩记者”不通，也与后文的丰富经历相矛盾。"}], "explanations": {"幼小": "语义：“幼小”指年纪很小，不能形容记者，也与“采访过很多大人物”相矛盾。", "资深": "正确：“资深”指在行业里工作多年、经验丰富，与“采访过很多大人物”相符。", "初级": "语义：“初级”指等级低，与“采访过很多大人物”的资历不符。", "嫩": "搭配：“嫩”不能直接修饰“记者”，说“一位嫩记者”不通，也与后文的丰富经历相矛盾。"}, "sentence_index": 0, "correct_answer": "资深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他办事很资深，客户都很信任他。", "explanation": "这里应该用〈老练〉。资深说的是在某行业工作多年的资历，形容办事的熟练程度要用老练。"}, {"text": "这座古城的历史很资深。", "explanation": "这里应该用〈悠久〉。资深只用于说人的工作经历，不能用来形容古城或历史；说历史长要用悠久。"}, {"text": "这个孩子说话很资深，大家都觉得他像大人。", "explanation": "这里应该用〈老成〉。资深说的是在某行业工作多年的资历，不能用来形容小孩说话成熟；形容年纪小却说话稳重，要用老成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年纪轻，与“做了四十年菜”的经历相矛盾。"}, {"text": "资深", "is_correct": true, "explanation": "正确：“资深”指长期从事某项工作、经验丰富，与“做了四十年菜”相符。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”指不熟练，与“做了四十年菜”的经历相矛盾。"}, {"text": "年幼", "is_correct": false, "explanation": "语义：“年幼”指年纪很小，与“厨师”的身份和“做了四十年菜”都相矛盾。"}], "explanations": {"年轻": "语义：“年轻”说年纪轻，与“做了四十年菜”的经历相矛盾。", "资深": "正确：“资深”指长期从事某项工作、经验丰富，与“做了四十年菜”相符。", "生疏": "语义：“生疏”指不熟练，与“做了四十年菜”的经历相矛盾。", "年幼": "语义：“年幼”指年纪很小，与“厨师”的身份和“做了四十年菜”都相矛盾。"}, "sentence_index": 6, "correct_answer": "资深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座老房子比那座资深十年。", "explanation": "这里应该用〈老〉。资深只用于人的工作经历，不能用来比较房屋；说房子建了多久，要用“老”。"}, {"text": "他刚进公司一周，就是资深员工。", "explanation": "这里应该用〈新手〉。资深指在某行业工作多年、经验丰富，刚进公司一周的人是新手，不能称资深员工。"}, {"text": "这辆旧自行车很资深。", "explanation": "这里应该用〈陈旧〉。资深只用于人的工作经历，不能形容自行车这类物品；说东西用久了、不新，要用陈旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只资深编辑，已经干了二十年。", "corrected_sentence": "她是一位资深编辑，已经干了二十年。", "error_description": "量词错误：“编辑”指人，量词应用“位”，“只”多用于动物等，不能用来数“编辑”。应改为“一位资深编辑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请一位很资深厨师来教我们做菜。", "corrected_sentence": "请一位资深厨师来教我们做菜。", "error_description": "“很”修饰作定语的“资深”时，名词前须带“的”（如“很资深的厨师”）；这里“很资深厨师”缺“的”，应去掉“很”，说“一位资深厨师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
