INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个地方经过，到了另一边。", "primary_collocate": null, "pronunciation": "zǒu guò", "ipa": "tsou˨˩˦ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "小朋友走过马路，到了学校。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起走过这座桥吧。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过河上的小桥，到了对面。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿灯亮了，大家快走过马路。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走过长长的走廊，到了另一边。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走过铁路，到了河的那边。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢走过人行天桥。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过草地，到了对面的树下。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走过这条街，银行就在对面。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两只羊走过小桥，到了河对岸。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走过了", "label": "体标"}, {"form": "没走过", "label": "否定"}, {"form": "走過", "label": "繁体"}], "register": "中性", "sense_fingerprint": "步行越过马路、桥等，到达另一侧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走过", "is_correct": true, "explanation": "走过：步行越过马路到达另一侧，与“到了学校”的语境相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语须是饮品，不能说喝马路。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”指用手触碰，句子说的是越过马路，与触碰无关。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，小朋友不会去修马路，与句意不符。"}], "explanations": {"走过": "走过：步行越过马路到达另一侧，与“到了学校”的语境相合。", "喝": "搭配：“喝”的宾语须是饮品，不能说喝马路。", "摸": "语义：“摸”指用手触碰，句子说的是越过马路，与触碰无关。", "修": "语义：“修”指修理，小朋友不会去修马路，与句意不符。"}, "sentence_index": 0, "correct_answer": "走过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走过了考试，终于拿到了证书。", "explanation": "这里应该用〈通过〉。走过只指步行越过某地，考试合格要说通过，此处换成走过不对。"}, {"text": "这只小鸡走过了天空。", "explanation": "这里应该用〈飞过〉。走过是步行越过地面，小鸡在天空中只能用飞过。"}, {"text": "老人走过了那封信，眼里含着泪。", "explanation": "这里应该用〈读〉。走过是步行越过某地，阅读信件要说读，此处不能用走过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走过", "is_correct": true, "explanation": "走过：慢慢步行越过人行天桥，符合老人慢慢行走的语境。"}, {"text": "挡", "is_correct": false, "explanation": "配价：“挡”需要能被遮挡的物体作宾语，不能直接以“人行天桥”这样的通道为宾语。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语须是食物，不能说煮人行天桥。"}, {"text": "贴", "is_correct": false, "explanation": "配价：“贴”需要被贴的物作宾语，并用“在”引出处所，不能直接带“人行天桥”。"}], "explanations": {"走过": "走过：慢慢步行越过人行天桥，符合老人慢慢行走的语境。", "挡": "配价：“挡”需要能被遮挡的物体作宾语，不能直接以“人行天桥”这样的通道为宾语。", "煮": "搭配：“煮”的宾语须是食物，不能说煮人行天桥。", "贴": "配价：“贴”需要被贴的物作宾语，并用“在”引出处所，不能直接带“人行天桥”。"}, "sentence_index": 6, "correct_answer": "走过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗帘走过了房间。", "explanation": "这里应该用〈挂〉。走过的主语须能步行，窗帘不能走，应说“窗帘挂在窗前”。"}, {"text": "妈妈走过了我的作业，然后关灯睡觉了。", "explanation": "这里应该用〈检查〉。走过的宾语须是地点或人，检查作业要用“检查”，不能说走过作业。"}, {"text": "他走过了这个决定。", "explanation": "这里应该用〈做出〉。走过的宾语须是地点或人，作决定要说“做出这个决定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们牵着手走过了了那座小桥。", "corrected_sentence": "我们牵着手走过了那座小桥。", "error_description": "“走过了”中的“了”已表示完成，此处多加了一个“了”，应删去重复的“了”，说“走过了那座小桥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们还没走过了那座铁桥。", "corrected_sentence": "我们还没走过那座铁桥。", "error_description": "“没”表示未经历，与“了”不能同用；否定经历应说“还没走过”，此处应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
