INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过某处；从旁边通过。", "primary_collocate": null, "pronunciation": "zǒu guò", "ipa": "tsou˨˩˦ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "我每天早上都走过那家面包店。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从我身边走过，没有看我。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走过学校门口，看见了老师。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班时，我走过公园，天已经黑了。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗从桌子旁边走过。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过那座老房子，又回头看了一眼。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢走过我们的窗前。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走过一家花店，买了一些花。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次走过银行，他都会看一下时间。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子走过我身边，笑着说你好。", "target_word": "走过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走过了", "label": "体标"}, {"form": "没走过", "label": "否定"}, {"form": "走過", "label": "繁体"}], "register": "中性", "sense_fingerprint": "步行时经过某地或从某人身旁经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走过", "is_correct": true, "explanation": "走过：步行经过那家面包店，符合“每天早上都”的日常语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语须是食物，不能说吃一家面包店。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指撞击破坏，与“每天早上都”的日常经过不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲或戏，不能说唱一家店。"}], "explanations": {"走过": "走过：步行经过那家面包店，符合“每天早上都”的日常语境。", "吃": "搭配：“吃”的宾语须是食物，不能说吃一家面包店。", "砸": "语义：“砸”指撞击破坏，与“每天早上都”的日常经过不符。", "唱": "搭配：“唱”的宾语是歌曲或戏，不能说唱一家店。"}, "sentence_index": 0, "correct_answer": "走过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子弹走过了木板。", "explanation": "这里应该用〈穿过〉。走过指人或动物步行经过，子弹穿透木板要用穿过；子弹不能走。"}, {"text": "这件事走过了三次修改，才定下来。", "explanation": "这里应该用〈经过〉。走过只指步行越过某地，表示事情的过程要用经过，此处换成走过不对。"}, {"text": "我走过了他的电话。", "explanation": "这里应该用〈接〉。走过只能指步行经过地点或人，不能以电话为对象；接电话要用“接”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走过", "is_correct": true, "explanation": "走过：慢慢步行从窗前经过，符合老人慢慢走的语境。"}, {"text": "挡", "is_correct": false, "explanation": "配价：“挡”需要能被遮挡的物体作宾语，不能直接以“窗前”这样的地点为宾语。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语须是食物，不能说煮窗前。"}, {"text": "贴", "is_correct": false, "explanation": "配价：“贴”需要被贴的物作宾语，并用“在”引出处所，不能直接带“窗前”。"}], "explanations": {"走过": "走过：慢慢步行从窗前经过，符合老人慢慢走的语境。", "挡": "配价：“挡”需要能被遮挡的物体作宾语，不能直接以“窗前”这样的地点为宾语。", "煮": "搭配：“煮”的宾语须是食物，不能说煮窗前。", "贴": "配价：“贴”需要被贴的物作宾语，并用“在”引出处所，不能直接带“窗前”。"}, "sentence_index": 6, "correct_answer": "走过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起走过三个小时，终于到了山顶。", "explanation": "这里应该用〈走了〉。走过表示经过某处，不能带时间段作宾语，说走了多久要用“走了”。"}, {"text": "这个问题我已经走过三次了。", "explanation": "这里应该用〈想过〉。走过指步行经过某地或某人身旁，问题不是地点，思考问题要说想过。"}, {"text": "那棵树走过了我的窗前。", "explanation": "这里应该用〈立〉，说“那棵树立在我的窗前”。走过的主语须能步行，树是静止的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天没不走过那家面包店。", "corrected_sentence": "我昨天没走过那家面包店。", "error_description": "“没”与“不”不能叠用；否定过去的经历只用“没”，应删去“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从我身边走过过，什么也没说。", "corrected_sentence": "她从我身边走过，什么也没说。", "error_description": "重复体标：“过”不能连用两次，“走过过”应删去一个“过”，说成“走过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
