INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97030, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "至少；最低限度。", "primary_collocate": null, "pronunciation": "qǐ mǎ", "ipa": "tɕʰi˨˩˦ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "做人起码要讲诚实。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你起码应该给他打个电话。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借了别人的东西，起码要说声谢谢。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进别人家以前，起码先敲一下门。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师起码应该先看完作业，再给分数。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不来也行，起码要告诉我们一声。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车起码要遵守交通规则。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你吃不完就算了，起码尝一口吧。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚回家，起码发个短信告诉妈妈。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生病了，我们起码应该去看看他。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做事、要求的最低限度，至少应该怎样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起码", "is_correct": true, "explanation": "正确：“起码”表示最低限度的要求，“做人起码要讲诚实”即做人最基本应当讲诚实。"}, {"text": "差点", "is_correct": false, "explanation": "语义：差点表示几乎要发生某事，不能引出“要讲诚实”这类应然的要求。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：竟然表示出乎意料，而“做人要讲诚实”是常理，不能用出乎意料来修饰。"}, {"text": "尚且", "is_correct": false, "explanation": "搭配：尚且需与“更”或“何况”呼应，单句中不能独立说“做人尚且要讲诚实”。"}], "explanations": {"起码": "正确：“起码”表示最低限度的要求，“做人起码要讲诚实”即做人最基本应当讲诚实。", "差点": "语义：差点表示几乎要发生某事，不能引出“要讲诚实”这类应然的要求。", "竟然": "语义：竟然表示出乎意料，而“做人要讲诚实”是常理，不能用出乎意料来修饰。", "尚且": "搭配：尚且需与“更”或“何况”呼应，单句中不能独立说“做人尚且要讲诚实”。"}, "sentence_index": 0, "correct_answer": "起码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "进别人家以前，起码不用敲门。", "explanation": "“起码”引出必须做到的最低要求，“不用敲门”取消了要求，二者矛盾；应说“起码先敲一下门”。"}, {"text": "进别人家以前，起码正好敲一下门。", "explanation": "这里表示恰好的数量，与最低要求不符，应该用〈刚好〉。"}, {"text": "进别人家以前，起码可以不敲门。", "explanation": "“起码”表示必须做到的最低要求，与“可以不敲门”的许可义相矛盾；这里是许可的意思，应删去“起码”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起码", "is_correct": true, "explanation": "正确：“起码”表示最低限度的要求，“开车起码要遵守交通规则”即开车最基本应遵守规则。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：幸亏表示庆幸，所引出的应是结果，不能引出“要遵守规则”这类规范。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然表示突然发生，而交通规则是长期要求，二者不相合。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：已经表示完成或已出现的状态，与表示应然的“要”不相合。"}], "explanations": {"起码": "正确：“起码”表示最低限度的要求，“开车起码要遵守交通规则”即开车最基本应遵守规则。", "幸亏": "语义：幸亏表示庆幸，所引出的应是结果，不能引出“要遵守规则”这类规范。", "忽然": "语义：忽然表示突然发生，而交通规则是长期要求，二者不相合。", "已经": "体貌：已经表示完成或已出现的状态，与表示应然的“要”不相合。"}, "sentence_index": 6, "correct_answer": "起码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友生病了，我们起码正好去看了他一次。", "explanation": "这里表示恰好的数量，与最低要求不符，应该用〈恰好〉。"}, {"text": "朋友生病了，我们起码可以不去看他。", "explanation": "“起码”表示必须做到的最低要求，与“可以不去看他”的许可义相矛盾；这里是许可的意思，应删去“起码”。"}, {"text": "朋友生病了，我们起码不用去看他。", "explanation": "“起码”引出必须做到的最低要求，“不用去看他”取消了要求，二者矛盾；应说“起码应该去看看他”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子做错事，起码的要认真道歉。", "corrected_sentence": "孩子做错事，起码要认真道歉。", "error_description": "“起码”是副词，直接修饰其后的“要”，不能加“的”；应写作“起码要认真道歉”，“起码的要认真道歉”是错误形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
